def pop_u16(self):
    """ Remove the last two bytes of data, returning them as a big-endian
    16-bit unsigned integer.
    """
    # Identify the buffer attribute
    if hasattr(self, "_bytes"):
        buf_attr = "_bytes"
    elif hasattr(self, "data"):
        buf_attr = "data"
    elif hasattr(self, "buffer"):
        buf_attr = "buffer"
    else:
        raise AttributeError("Instance has no buffer attribute (expected '_bytes', 'data', or 'buffer')")

    buf = getattr(self, buf_attr)

    # Ensure buffer is a sequence with enough bytes
    try:
        length = len(buf)
    except Exception as exc:
        raise TypeError("Buffer attribute is not a sequence") from exc

    if length < 2:
        raise ValueError("Insufficient bytes to pop a 16-bit value")

    # Retrieve the high and low bytes
    try:
        high = buf[-2]
        low = buf[-1]
    except Exception as exc:
        raise TypeError("Buffer elements must be integers (0-255)") from exc

    # Compute the 16‑bit big‑endian value
    value = (high << 8) | low

    # Remove the last two bytes from the buffer
    try:
        del buf[-2:]
    except Exception:
        # Buffer might be immutable; fall back to creating a new mutable buffer
        try:
            new_buf = bytearray(buf)
            del new_buf[-2:]
            setattr(self, buf_attr, new_buf)
        except Exception as exc:
            raise RuntimeError("Failed to modify buffer after popping bytes") from exc

    return value

