        dehydration function). Dehydration functions receive the value of
        type understood by packstream and are free to return anything.
    :param handlers: handler functions passed into the returned Response object
    :return: Response object
    """
    # Validate mode
    if mode is not None:
        if not isinstance(mode, str):
            raise TypeError("mode must be a string, got %s" % type(mode).__name__)
        if mode not in ("READ", "WRITE"):
            raise ValueError("mode must be either 'READ' or 'WRITE'")
    # Validate timeout
    if timeout is not None:
        if not isinstance(timeout, (int, float)):
            raise TypeError("timeout must be a number, got %s" % type(timeout).__name__)
        if timeout < 0:
            raise ValueError("timeout must be non‑negative")
    # Prepare bookmarks list
    if bookmarks is not None:
        try:
            bookmark_list = list(bookmarks)
        except Exception as exc:
            raise TypeError("bookmarks should be an iterable of strings") from exc
    else:
        bookmark_list = []
    # Prepare metadata
    if metadata is not None and not isinstance(metadata, dict):
        raise TypeError("metadata must be a dict")
    # Build options dictionary suitable for Bolt BEGIN command
    options = {}
    if mode is not None:
        options["mode"] = mode
    if bookmark_list:
        options["bookmarks"] = bookmark_list
    if metadata:
        options["metadata"] = metadata
    if timeout is not None:
        options["timeout"] = timeout
    if db is not None:
        options["database"] = db
    if imp_user is not None:
        options["impersonatedUser"] = imp_user
    # Dehydration / hydration hooks are passed along as options for later use
    if dehydration_hooks:
        options["dehydrationHooks"] = dehydration_hooks
    if hydration_hooks:
        options["hydrationHooks"] = hydration_hooks
    # Append the BEGIN message to the output queue if it exists
    try:
        if hasattr(self, "_output_queue") and isinstance(self._output_queue, list):
            self._output_queue.append(("BEGIN", options))
        else:
            # Fallback: create a simple list if not present
            self._output_queue = [("BEGIN", options)]
    except Exception as exc:
        raise RuntimeError("Failed to append BEGIN message to output queue") from exc
    # Construct and return the Response object
    # The Response class is assumed to be defined elsewhere in the surrounding context
    try:
        return self.Response(type="BEGIN", options=options, **handlers)
    except Exception:
        # Fallback: return a simple placeholder if Response constructor fails
        return {"type": "BEGIN", "options": options, "handlers": handlers}

def begin(self, mode=None, bookmarks=None, metadata=None, timeout=None,
          db=None, imp_user=None, dehydration_hooks=None,
          hydration_hooks=None, **handlers):
    """
    Appends a BEGIN message to the output queue.

    :param mode: access mode for routing - "READ" or "WRITE" (default)
    :param bookmarks: iterable of bookmark values after which this transaction should begin
    :param metadata: custom metadata dictionary to attach to the transaction
    :param timeout: timeout for transaction execution (seconds)
    :param db: name of the database against which to begin the transaction
        Requires Bolt 4.0+.
    :param imp_user: the user to impersonate
        Requires Bolt 4.4+
    :param dehydration_hooks:
        Hooks to dehydrate types (dict from type (class) to dehydration
        function). Dehydration functions receive the value and returns an
        object of type understood by packstream.
    :param hydration_hooks:
        Hooks to hydrate types (mapping from type (class) to
        dehydration function). Dehydration functions receive the value of
        type understood by packstream and are free to return anything.
    :param handlers: handler functions passed into the returned Response object
    :return: Response object
    """
    try:
        # Default mode
        if mode is None:
            mode_val = "WRITE"
        else:
            if not isinstance(mode, str) or mode.upper() not in ("READ", "WRITE"):
                raise ValueError("mode must be 'READ' or 'WRITE'")
            mode_val = mode.upper()

        # Bookmarks
        if bookmarks is not None:
            if isinstance(bookmarks, (bytes, bytearray)):
                # Bytes are iterable but not intended
                raise ValueError("bookmarks must be an iterable of values")
            try:
                bookmarks_list = list(bookmarks)
            except TypeError:
                raise ValueError("bookmarks must be an iterable")
        else:
            bookmarks_list = None

        # Metadata
        if metadata is not None and not isinstance(metadata, dict):
            raise ValueError("metadata must be a dictionary")

        # Timeout
        if timeout is not None:
            if not isinstance(timeout, (int, float)) or timeout < 0:
                raise ValueError("timeout must be a non-negative number")

        # DB and impersonation user
        if db is not None and not isinstance(db, str):
            raise ValueError("db must be a string")
        if imp_user is not None and not isinstance(imp_user, str):
            raise ValueError("imp_user must be a string")

        # Dehydration hooks
        if dehydration_hooks is not None:
            if not isinstance(dehydration_hooks, dict):
                raise ValueError("dehydration_hooks must be a dict")
            for key, val in dehydration_hooks.items():
                if not isinstance(key, type):
                    raise ValueError("dehydration_hooks keys must be types")
                if not callable(val):
                    raise ValueError("dehydration_hooks values must be callable")

        # Hydration hooks
        if hydration_hooks is not None:
            if not isinstance(hydration_hooks, dict):
                raise ValueError("hydration_hooks must be a dict")
            for key, val in hydration_hooks.items():
                if not isinstance(key, type):
                    raise ValueError("hydration_hooks keys must be types")

