def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass.
    """
    # Input validation
    if not isinstance(name, str):
        raise TypeError("name must be a string")
    if not isinstance(fields, (list, tuple)):
        raise TypeError("fields must be a list or tuple")
    if not isinstance(srid_map, dict):
        raise TypeError("srid_map must be a dictionary")

    # Prepare class attributes
    attrs = {"__srid_map__": srid_map.copy()}

    # Normalize field definitions
    for f in fields:
        if isinstance(f, (list, tuple)):
            fname, fdefault = f
        else:
            fname, fdefault = f, None
        if not isinstance(fname, str):
            raise TypeError("field names must be strings")
        attrs[fname] = fdefault

    # Define a simple __init__ that accepts keyword args for fields
    def __init__(self, *args, **kwargs):
        for fname in attrs:
            if fname in ("__srid_map__", "__init__"):
                continue
            setattr(self, fname, kwargs.get(fname, attrs[fname]))
    attrs["__init__"] = __init__

    # Try to inherit from a global Point; fallback to object if not defined
    bases = ()
    try:
        Point = globals()["Point"]
    except (KeyError, NameError):
        Point = object
    bases = (Point,)

    return type(name, bases, attrs)

