        "_fields": fields,
        "_srid_map": srid_map,
    }

    # Define the __init__ method for the dynamic class
    def __init__(self, *coords, **kwargs):
        # Call the base Point initializer
        super(self.__class__, self).__init__(*coords)
        # Assign any additional fields
        for field_name in fields:
            setattr(self, field_name, kwargs.get(field_name))

    attrs["__init__"] = __init__

    # Optionally, provide a helpful repr
    def __repr__(self):
        base_repr = super(self.__class__, self).__repr__()
        field_parts = " ".join(f"{k}={getattr(self, k)!r}" for k in fields)
        return f"{base_repr[:-1]}, {field_parts})"

    attrs["__repr__"] = __repr__

    # Dynamically create and return the subclass
    return type(name, (Point,), attrs)

def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass. """
    # Validate input types
    if not isinstance(name, str):
        raise TypeError("name must be a string")
    if not isinstance(fields, (list, tuple)):
        raise TypeError("fields must be a list or tuple of field names")
    if not isinstance(srid_map, dict):
        raise TypeError("srid_map must be a dictionary")

    # Ensure all field names are strings
    for field in fields:
        if not isinstance(field, str):
            raise TypeError(f"field name {field!r} is not a string")

    # Define the __init__ method for the dynamic class
    def _init(self, *args, **kwargs):
        # Default coordinate values
        self.x = None
        self.y = None
        self.z = None
        # Assign coordinates from positional args
        if len(args) >= 2:
            self.x = args[0]
            self.y = args[1]
        if len(args) >= 3:
            self.z = args[2]
        # Assign additional fields from kwargs
        for field in fields:
            setattr(self, field, kwargs.get(field))
        # Set SRID if provided in srid_map
        self.srid = srid_map.get('srid')

    # Define a nice __repr__ method
    def _repr(self):
        coords = f"x={self.x}, y={self.y}"
        if self.z is not None:
            coords += f", z={self.z}"
        field_reprs = ", ".join(f"{f}={getattr(self, f, None)}" for f in fields)
        attrs = ", ".join([coords] + [field_reprs] + [f"srid={getattr(self, 'srid', None)}"])
        return f"{name}({attrs})"

    # Compose the class dictionary
    class_dict = {
        '__init__': _init,
        '__repr__': _repr,
    }

    # Create the dynamic class
    try:
        DynamicPoint = type(name, (object,), class_dict)
    except Exception as exc:
        raise RuntimeError(f"Failed to create dynamic class {name}") from exc

    return DynamicPoint

def deprecated(message):
    """
    Decorator for deprecating functions and methods.

    ::

        @deprecated("'foo' has been deprecated in favour of 'bar'")
        def foo(x):
            pass
    """
    if not isinstance(message, str):
        raise TypeError("deprecation message must be a string")

    def decorator(func):
        if not callable(func):
            raise TypeError("deprecated decorator requires a callable")

        def wrapper(*args, **kwargs):
            try:
                # Get the warnings module dynamically to avoid a global import
                warnings = __import__('warnings')
                # Emit a deprecation warning with stacklevel to point to the caller
                warnings.warn(message,
                              category=warnings.DeprecationWarning,
                              stacklevel=2)
                return func(*args, **kwargs)
            except Exception:
                # Re-raise any exception from the wrapped function unchanged
                raise

        # Preserve function metadata
        wrapper.__name__ = func.__name__
        wrapper.__doc__ = func.__doc__
        wrapper.__module__ = func.__module__
        wrapper.__dict__.update(func.__dict__)
        return wrapper

    return decorator

