        wrapper.__name__ = func.__name__
        wrapper.__doc__ = func.__doc__
        wrapper.__dict__.update(func.__dict__)
        return wrapper
    return decorator

def _shuffled(seq: Sequence[str]) -> list[str]:
    """Deterministically shuffle"""
    try:
        if seq is None:
            raise TypeError("seq must be a sequence of strings")
        items = list(seq)
        for item in items:
            if not isinstance(item, str):
                raise TypeError("all items in seq must be strings")
        def _hash(s: str) -> int:
            h = 0
            for ch in s:
                h = (h * 257 + ord(ch)) & 0xFFFFFFFF
            return h
        items.sort(key=_hash)
        return items
    except Exception as exc:
        raise ValueError(f"Error in deterministic shuffle: {exc}") from exc

def _shuffled(seq: Sequence[str]) -> list[str]:
    """Deterministically shuffle"""
    try:
        if not isinstance(seq, Sequence):
            raise TypeError("seq must be a Sequence")
        # validate that all items are strings
        for idx, item in enumerate(seq):
            if not isinstance(item, str):
                raise TypeError(f"Item at index {idx} is not a string")
        lst = list(seq)
        # Simple deterministic shuffle using a linear congruential generator
        seed = 42
        for i in range(len(lst) - 1, 0, -1):
            seed = (seed * 1664525 + 1013904223) & 0xffffffff
            j = seed % (i + 1)
            lst[i], lst[j] = lst[j], lst[i]
        return lst
    except Exception as e:
        raise ValueError(f"Failed to shuffle sequence: {e}") from e

def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""
    if not isinstance(s, str):
        raise TypeError(f"Expected a string, got {type(s).__name__}")
    parts = s.strip().split('.')
    result = []
    for part in parts:
        part = part.strip()
        if not part:
            continue
        idx = 0
        while idx < len(part) and part[idx].isdigit():
            idx += 1
        if idx == 0:
            continue  # no leading digits
        try:
            num = int(part[:idx])
        except ValueError:
            continue
        result.append(num)
    return tuple(result)

def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""
    # Validate input type
    if not isinstance(s, str):
        raise TypeError(f"Input must be a string, got {type(s).__name__}")
    try:
        import re
    except Exception as exc:
        raise RuntimeError("Required module 're' could not be imported") from exc
    # Find all continuous digit sequences
    parts = re.findall(r'\d+', s)
    # Convert each to integer; if none found, default to 0
    if not parts:
        return (0,)
    try:
        return tuple(int(part) for part in parts)
    except ValueError as exc:
        raise ValueError(f"Invalid numeric part in version string '{s}'") from exc

def cached(cache, key=hashkey, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.
    """
    # Default key function if not provided
    if key is None or key == hashkey:
        def key(*args, **kwargs):
            return hash((args, tuple(sorted(kwargs.items()))))

    def decorator(func):
        import functools
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            try:
                k = key(*args, **kwargs)
            except Exception:
                # If key function fails, just call the function directly
                return func(*args, **kwargs)

            if lock:
                # Acquire lock if provided, assuming lock implements acquire/release
                lock.acquire()
                try:
                    result = cache.get(k, object())
                    if result is not object():
                        return result
                finally:
                    lock.release()
            else:
                result = cache.get(k, object())
                if result is not object():
                    return result

            # Compute and store result
            try:
                result = func(*args, **kwargs)
            except Exception:
                # Do not store on exception
                raise

            # Store the result in the cache
            try:
                if lock:
                    lock.acquire()
                    try:
                        cache[k] = result
                    finally:
                        lock.release()
                else:
                    cache[k] = result
            except Exception:
                # If storage fails, ignore silently
                pass

            return result

        return wrapper

    return decorator

