def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """
    Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    def decorate(func):
        import time
        cache = {}
        order = []

        def _make_key(args, kwargs):
            if typed:
                args_key = tuple((arg, type(arg)) for arg in args)
                kwargs_key = tuple((k, type(v)) for k, v in sorted(kwargs.items()))
            else:
                args_key = args
                kwargs_key = tuple(sorted(kwargs.items()))
            return (args_key, kwargs_key)

        def wrapper(*args, **kwargs):
            key = _make_key(args, kwargs)
            now = timer()
            # Check cache
            if key in cache:
                value, expire = cache[key]
                if now <= expire:
                    # Refresh LRU order
                    if key in order:
                        order.remove(key)
                    order.append(key)
                    return value
                else:
                    # expired
                    del cache[key]
                    if key in order:
                        order.remove(key)
            # Compute new value
            result = func(*args, **kwargs)
            # Store in cache
            if maxsize <= 0:
                return result
            cache[key] = (result, now + ttl)
            order.append(key)
            # Evict if necessary
            while len(cache) > maxsize:
                oldest_key = order.pop(0)
                cache.pop(oldest_key, None)
            return result

        wrapper.cache_info = lambda: {"maxsize": maxsize, "currsize": len(cache)}
        wrapper.cache_clear = lambda: (cache.clear(), order.clear())
        wrapper.__name__ = func.__name__
        wrapper.__doc__ = func.__doc__
        return wrapper

    return decorate

def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    if maxsize is not None and maxsize < 0:
        raise ValueError("maxsize must be a non-negative integer or None")
    if ttl < 0:
        raise ValueError("ttl must be non-negative")

    def decorator(func):
        cache = {}
        hits = 0
        misses = 0

        def _make_key(args, kw, typed):
            key = args
            if kw:
                # Convert keyword arguments to a tuple of sorted items
                items = tuple(sorted(kw.items()))
                key += items
            if typed:
                key += tuple(type(v) for v in args)
                if kw:
                    key += tuple(type(v) for _, v in items)
            return key

        def wrapper(*args, **kw):
            nonlocal hits, misses
            try:
                key = _make_key(args, kw, typed)
            except TypeError:
                # If key elements are unhashable, fallback to direct call
                misses += 1
                return func(*args, **kw)

            now = timer()
            entry = cache.get(key)
            if entry is not None:
                expire, value = entry
                if expire > now:
                    hits += 1
                    # Move key to end to mark as recently used
                    cache.pop(key)
                    cache[key] = (expire, value)
                    return value
                else:
                    # Expired entry
                    cache.pop(key)
            misses += 1
            result = func(*args, **kw)
            if maxsize is None or maxsize > 0:
                if len(cache) >= (maxsize if maxsize is not None else 0):
                    # Evict least-recently used item
                    oldest_key = next(iter(cache))
                    cache.pop(oldest_key)
                cache[key] = (now + ttl, result)
            return result

        def cache_clear():
            nonlocal hits, misses
            cache.clear()
            hits = 0
            misses = 0

        def cache_info():
            return {
                'hits': hits,
                'misses': misses,
                'maxsize': maxsize,
                'currsize': len(cache)
            }

        wrapper.cache_clear = cache_clear
        wrapper.cache_info = cache_info
        wrapper.__wrapped__ = func
        wrapper.__name__ = func.__name__
        wrapper.__doc__ = func.__doc__
        return wrapper

    return decorator

def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    # Validate arguments
    if not isinstance(maxsize, int) or maxsize <= 0:
        raise ValueError("maxsize must be a positive integer")
    if not isinstance(ttl, (int, float)) or ttl <= 0:
        raise ValueError("ttl must be a positive number")
    if not callable(timer):
        raise ValueError("timer must be a callable that returns the current time")
    if not isinstance(typed, bool):
        raise ValueError("typed must be a boolean")

    def decorator(func):
        if not callable(func):
            raise ValueError("ttl_cache can only be applied to callables")

        from collections import OrderedDict

        cache = OrderedDict()

        def make_key(args, kwargs):
            """Create a hashable key based on function arguments."""
            try:
                key = args
                if kwargs:
                    key = key + tuple(sorted(kwargs.items()))
