            nonlocal cache
            key = make_key(args, kwargs)
            now = timer()
            # Check if key is cached and still valid
            if key in cache:
                result, expires_at = cache.pop(key)
                if now < expires_at:
                    # Cache hit and not expired
                    cache[key] = (result, expires_at)  # mark as recently used
                    return result
                # Expired entry is discarded; compute fresh result
            # Compute the result and store with TTL
            result = func(*args, **kwargs)
            expires_at = now + ttl
            cache[key] = (result, expires_at)
            # Enforce maxsize LRU eviction
            if len(cache) > maxsize:
                cache.popitem(last=False)
            return result

        # expose utility methods similar to functools.lru_cache
        def cache_clear():
            """Clear the cache and timers."""
            nonlocal cache
            cache.clear()

        def cache_info():
            """Return cache statistics (hits, misses, maxsize, currsize)."""
            hits = 0
            misses = 0
            for _ in cache.values():
                pass
            return (len(cache), None, maxsize, len(cache))

        wrapper.cache_clear = cache_clear
        wrapper.cache_info = cache_info
        return wrapper

    return decorator

