    """
    Format an exception into a readable string with limited stack depth and path truncation.
    """
    import traceback
    import os

    try:
        if not isinstance(e, BaseException):
            raise TypeError("The 'e' argument must be an exception instance")

        # Build the base exception message
        exc_type = e.__class__.__name__
        exc_msg = str(e)

        # Extract traceback frames if available
        frames = []
        tb = getattr(e, "__traceback__", None)
        if tb is not None:
            frames = traceback.extract_tb(tb)

        # Limit the stack depth
        if max_level is not None and isinstance(max_level, int) and max_level > 0:
            frames = frames[:max_level]
        else:
            frames = frames  # keep all if invalid max_level

        # Helper to shorten file paths
        def shorten_path(path):
            parts = path.split(os.sep)
            if len(parts) > max_path_level:
                return os.sep.join(parts[-max_path_level:])
            return path

        # Format each frame
        formatted_frames = []
        for frame in frames:
            file_path = shorten_path(frame.filename)
            line = f'  File "{file_path}", line {frame.lineno}, in {frame.name}'
            if frame.line:
                # Include the source line stripped of leading/trailing whitespace
                formatted_line = frame.line.strip()
                if formatted_line:
                    line += f'\n    {formatted_line}'
            formatted_frames.append(line)

        # Assemble the final string
        parts = [f"{exc_type}: {exc_msg}"]
        if formatted_frames:
            parts.append("Traceback (most recent call last):")
            parts.extend(formatted_frames)

        return "\n".join(parts)

    except Exception as gen_err:
        # Fallback: return a simple representation if formatting fails
        return f"Exception formatting error: {gen_err.__class__.__name__}: {gen_err}"

