@classmethod
def _reset_logging(cls):
    """
    Reset the logging configuration for the application by clearing all handlers
    and restoring the root logger to its default level. Any errors encountered
    during the reset process are silently ignored to avoid disrupting the
    calling code.
    """
    try:
        import logging
        root = logging.getLogger()
        # Close and remove handlers of the root logger
        for handler in root.handlers[:]:
            try:
                handler.close()
            except Exception:
                pass
            root.removeHandler(handler)
        # Reset root logger level
        root.setLevel(logging.WARNING)
        # Optionally, clear any other loggers that might still hold handlers
        for name in list(logging.root.manager.loggerDict):
            try:
                logger = logging.getLogger(name)
                for handler in logger.handlers[:]:
                    try:
                        handler.close()
                    except Exception:
                        pass
                    logger.removeHandler(handler)
                logger.setLevel(logging.WARNING)
            except Exception:
                pass
    except Exception:
        # Silently ignore any issues during resetting
        pass

