def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    # Validate input type
    try:
        iterable = list(classes)
    except Exception as exc:
        raise TypeError("Expected an iterable of classes") from exc

    # Remove duplicates while preserving order
    seen = set()
    unique_classes = []
    for cls in iterable:
        if not isinstance(cls, type):
            raise TypeError(f"Element {cls!r} is not a class type")
        if cls not in seen:
            seen.add(cls)
            unique_classes.append(cls)

    # Determine minimal set: keep classes that are not superclasses of any other
    minimal = []
    for cand in unique_classes:
        # If cand is a superclass of some other class in the list, skip it
        is_super = False
        for other in unique_classes:
            if other is cand:
                continue
            try:
                if issubclass(other, cand):
                    is_super = True
                    break
            except TypeError:
                # Skip if other is not a class (shouldn't happen after validation)
                continue
        if not is_super:
            minimal.append(cand)

    return minimal

