def _normalizeargs(sequence, output=None):
    """
    Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []

    # Helper to decide whether to expand or keep the item
    def _is_interface(item):
        # Treat Python classes and strings as interfaces
        return isinstance(item, type) or isinstance(item, str)

    def _is_implements_spec(item):
        # Heuristic: a tuple like ('implements', interface or spec)
        return (
            isinstance(item, tuple)
            and len(item) == 2
            and isinstance(item[0], str)
            and item[0].lower() == "implements"
        )

    def _add(item):
        """
        Recursively add normalized items to output.
        """
        try:
            # If the item is a Declarion (we assume it has an attribute
            # 'is_declarion' or similar). Since we cannot import the
            # actual class, we use a duck-typing approach.
            if hasattr(item, "is_declarion") and getattr(item, "is_declarion"):
                output.append(item)

            # Individual interfaces: keep as is
            elif _is_interface(item):
                output.append(item)

            # Implements specs: keep as is
            elif _is_implements_spec(item):
                output.append(item)

            # If it's a tuple or list but not a special case, expand it
            elif isinstance(item, (list, tuple)):
                for sub in item:
                    _add(sub)

            # If it's an iterable but not a string (so we don't split strings)
            elif hasattr(item, "__iter__"):
                for sub in item:
                    _add(sub)

            # Fallback: keep the item
            else:
                output.append(item)

        except Exception:
            # In case of any runtime issue, just ignore the problematic
            # element to keep normalization robust.
            pass

    # If the incoming sequence is not iterable, treat it as a single item
    try:
        for elem in sequence:
            _add(elem)
    except TypeError:  # sequence is not iterable
        _add(sequence)

    return output

