def _should_attempt_c_optimizations():
    """
    Return a true value if we should attempt to use the C optimizations.

    This takes into account whether we're on PyPy and the value of the
    ``PURE_PYTHON`` environment variable, as defined in `_use_c_impl`.
    """
    try:
        import os
        import sys
    except Exception:
        # In case imports fail, do not attempt C optimizations
        return False

    # Determine if we are running on PyPy
    try:
        is_pypy = hasattr(sys, "pypy_version_info")
    except Exception:
        is_pypy = False

    # Check for the environment variable that forces pure-python mode
    try:
        pure_python_val = os.getenv("PURE_PYTHON", "")
        pure_python = pure_python_val.lower() in {"1", "true", "yes"}
    except Exception:
        pure_python = False

    # We attempt C optimizations only on CPython when PURE_PYTHON is not set
    return not (is_pypy or pure_python)

