            elif hasattr(point, "coord") or hasattr(point, "coords"):
                coords = getattr(point, "coord", getattr(point, "coords", None))
            elif hasattr(point, "__iter__") and len(point) > 0:
                # Assume the first element is coordinates
                coords = point[0]
            else:
                coords = []

            # Extract values: try common attribute names
            values = None
            if hasattr(point, "values"):
                values = point.values
            elif hasattr(point, "value"):
                values = point.value
            elif hasattr(point, "__iter__") and len(point) > 1:
                values = point[1]
            else:
                values = None

            # Normalize coordinates to an iterable
            if isinstance(coords, (list, tuple)):
                coord_parts = [str(c) for c in coords]
            elif coords is None:
                coord_parts = []
            else:
                # Treat single coordinate as scalar
                coord_parts = [str(coords)]

            # Normalize values to an iterable of scalar values
            if isinstance(values, (list, tuple)):
                value_parts = [str(v) for v in values]
            elif values is None:
                value_parts = []
            else:
                value_parts = [str(values)]

            # Compose the CSV line
            line = separator.join(coord_parts + value_parts)
            lines.append(line)

        # Join all lines with newline character
        return "\n".join(lines)

def to_csv(self, separator=",", header=None):
    """
    Convert graph's points to CSV.

    *separator* delimits values, the default is comma.

    *header*, if not ``None``, is the first string of the output
    (new line is added automatically).

    Since a graph can be multidimensional,
    for each point first its coordinate is converted to string
    (separated by *separator*), then each part of its value.
    """
    # Validate separator
    if not isinstance(separator, str):
        raise TypeError("separator must be a string")

    # Validate header
    if header is not None and not isinstance(header, str):
        raise TypeError("header must be a string or None")

    # Attempt to retrieve points from the graph
    points = getattr(self, "points", None)
    if points is None:
        raise AttributeError("The object has no 'points' attribute")

    lines = []

    # Optional header line
    if header is not None:
        lines.append(header)

    try:
        for idx, point in enumerate(points):
            # Expect point to be a (coordinate, value) pair
            if not isinstance(point, (tuple, list)) or len(point) != 2:
                raise ValueError(
                    f"Point #{idx} does not have the expected (coordinate, value) format: {point!r}"
                )
            coord, val = point

            # Convert coordinate to string
            if not isinstance(coord, (tuple, list)):
                raise TypeError(f"Coordinate of point #{idx} is not iterable: {coord!r}")
            try:
                coord_parts = [str(c) for c in coord]
            except Exception as exc:
                raise ValueError(
                    f"Error converting coordinate {coord!r} of point #{idx} to string: {exc}"
                ) from exc
            coord_str = separator.join(coord_parts)

            # Convert value parts to string
            if isinstance(val, (list, tuple, set)):
                val_parts = [str(v) for v in val]
            else:
                val_parts = [str(val)]

            # Combine into a CSV line
            line = separator.join([coord_str] + val_parts)
            lines.append(line)

        return "\n".join(lines)

    except Exception as exc:
        raise ValueError(f"Failed to generate CSV: {exc}") from exc

def to_csv(self, separator=",", header=None):
        """.. deprecated:: 0.5 in Lena 0.5 to_csv is not used.
              Iterables are converted to tables.

        Convert graph's points to CSV.

        *separator* delimits values, the default is comma.

        *header*, if not ``None``, is the first string of the output
        (new line is added automatically).

        Since a graph can be multidimensional,
        for each point first its coordinate is converted to string
        (separated by *separator*), then each part of its value.

        To convert :class:`Graph` to CSV inside a Lena sequence,
        use :class:`lena.output.ToCSV`.
        """
        try:
            # Try to use a dedicated points method if present
            points_iterable = self.points()
        except Exception:
            # Fallback: use the instance itself as an iterable of points
            points_iterable = self

        # Helper to safely convert a coordinate iterable to a string.
        def _coord_to_string(coord):
            try:
                # If coordinate is already a string, return it unchanged.
                if isinstance(coord, (str, bytes)):
                    return str(coord)
                return separator.join(str(c) for c in coord)
            except Exception:
                # In case of non-iterable coord, just convert to str.
                return str(coord)

        # Helper to convert a value part to a string.
        def _value_parts(val):
            if val is None:
                return []
            if isinstance(val, (str, bytes)):
                return [str(val)]
            if hasattr(val, "__iter__"):
                # Exclude strings from iteration
                try:
                    return [str(v) for v in val]
                except Exception:
                    return [str(val)]
            return [str(val)]

        output_lines = []

        # Add header if provided
        if header is not None:
            output_lines.append(str(header))

        # Generate CSV lines
        for point in points_iterable:
            # Expect point to be a pair (coordinate, value)
            # If not, wrap it into a coordinate and leave value empty
            try:
                coord, val = point[0], point[1]
            except Exception:
                coord, val = point, None

            coord_str = _coord_to_string(coord)
            val_parts = _value_parts(val)

            line = separator.join([coord_str] + val_parts)
            output_lines.append(line)

        return "\n".join(output_lines)

def _get_err_indices(self, coord_name):
