def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    try:
        # Retrieve the place where error data is stored
        err_ref = getattr(self, "errors", None)
        if err_ref is None:
            raise AttributeError("No 'errors' attribute found.")

        # Case 1: errors is a dict mapping coordinate names to error arrays
        if isinstance(err_ref, dict):
            if coord_name not in err_ref:
                raise ValueError(f"No error entry for coordinate '{coord_name}'.")
            err_vals = err_ref[coord_name]
            # If the entry itself is a list/tuple/iterable, return indices for each
            if hasattr(err_vals, "__iter__") and not isinstance(err_vals, (str, bytes)):
                return list(range(len(err_vals)))
            # Otherwise, treat as a single error value
            return [0]

        # Case 2: errors is a list or tuple of error arrays aligned with self.coord_names
        if isinstance(err_ref, (list, tuple)):
            if not hasattr(self, "coord_names"):
                raise AttributeError("Missing 'coord_names' attribute required when errors is a list/tuple.")
            try:
                idx = self.coord_names.index(coord_name)
                return [idx]
            except ValueError:
                raise ValueError(f"Coordinate '{coord_name}' not found in 'coord_names'.")

        # Case 3: errors is an object having a 'columns' attribute (e.g., a pandas DataFrame)
        # Attempt to detect a column named '{coord_name}_err'
        if hasattr(err_ref, "columns"):
            col_name = f"{coord_name}_err"
            try:
                col_index = err_ref.columns.get_loc(col_name)
                return [col_index]
            except Exception:
                raise ValueError(f"Error column '{col_name}' not found in the errors data structure.")

        # If we reach here, the errors structure type is not recognized
        raise TypeError("Unsupported type for 'errors' attribute.")
    except Exception as exc:
        raise ValueError(f"Failed to get error indices for coordinate '{coord_name}': {exc}") from exc

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    if not isinstance(coord_name, str):
        raise TypeError("coord_name must be a string")

    if not hasattr(self, "_err_indices"):
        raise AttributeError("The instance does not have an '_err_indices' attribute")

    mapping = getattr(self, "_err_indices")
    if not isinstance(mapping, dict):
        raise TypeError("'_err_indices' attribute must be a dict mapping coordinate names to iterable indices")

    if coord_name not in mapping:
        raise KeyError(f"No error indices recorded for coordinate '{coord_name}'")

    indices = mapping[coord_name]
    try:
        # Convert to list of integers, handling numpy array or other iterables
        return [int(i) for i in indices]
    except Exception as exc:
        raise TypeError(f"Error indices for coordinate '{coord_name}' must be an iterable of integers") from exc

