def _update_context(self, context):
    """
    Update *context* with the properties of this graph.

    *context.error* is appended with indices of errors.
    Example subcontext for a graph with fields "E,t,error_E_low":
    {"error": {"x_low": {"index": 2}}}.
    Note that error names are called "x", "y" and "z"
    (this corresponds to first three coordinates,
    if they are present), which allows to simplify plotting.
    Existing values are not removed
    from *context.value* and its subcontexts.
    """
    try:
        # Ensure context has an 'error' attribute which is a dict
        if not hasattr(context, 'error') or not isinstance(context.error, dict):
            context.error = {}
    except Exception:
        # In case context is not writable, silently skip
        return

    # Attempt to obtain the list of field names from the graph
    field_names = None
    for attr in ('fields', '_fields', 'get_fields', 'columns'):
        if hasattr(self, attr):
            try:
                potential = getattr(self, attr)
                if callable(potential):
                    field_names = potential()
                else:
                    field_names = potential
                if isinstance(field_names, (list, tuple)):
                    field_names = list(field_names)
                else:
                    field_names = None
            except Exception:
                field_names = None
            break

    if not isinstance(field_names, list):
        # Cannot map coordinates; fall back to using suffixes as error keys
        field_to_coord = {}
    else:
        # Map first three fields to 'x', 'y', 'z' coordinates
        coord_labels = ['x', 'y', 'z']
        field_to_coord = {name: coord for name, coord in zip(field_names[:3], coord_labels)}

    # Iterate over attributes that may store error indices
    for attr_name in dir(self):
        if not attr_name.startswith('error_'):
            continue
        try:
            index_value = getattr(self, attr_name)
        except AttributeError:
            continue
        if not isinstance(index_value, (int, float)):
            # Skip if not a numeric index
            continue
        suffix = attr_name[6:]  # remove 'error_'
        # Try to map field part to coordinate
        if '_' in suffix:
            field_part, rest = suffix.split('_', 1)
            coord = field_to_coord.get(field_part, field_part)
            error_key = f"{coord}_{rest}"
        else:
            # No underscore, treat entire suffix as field part
            field_part = suffix
            coord = field_to_coord.get(field_part, field_part)
            error_key = coord
        # Insert into context.error mapping
        try:
            context.error.setdefault(error_key, {})['index'] = int(index_value)
        except Exception:
            # If context.error is read‑only or corrupted, skip this error
            continue
    # No explicit return needed; the context is mutated in place.

def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    # Basic input validation
    try:
        bins_list = list(bins)
    except Exception:
        raise TypeError("bins must be an iterable of numeric values")
    try:
        edges_list = list(edges)
    except Exception:
        raise TypeError("edges must be an iterable of numeric values")

    n = len(bins_list)
    if len(edges_list) != n + 1:
        raise ValueError(f"edges length must be len(bins)+1; got {len(edges_list)} vs {n+1}")

    # Convert to float and validate numeric types
    try:
        bins_float = [float(b) for b in bins_list]
    except Exception as e:
        raise TypeError("All bins must be numeric values") from e
    try:
        edges_float = [float(e) for e in edges_list]
    except Exception as e:
        raise TypeError("All edges must be numeric values") from e

    # Compute bin widths and check for non-positive widths
    widths = []
    for i in range(n):
        width = edges_float[i + 1] - edges_float[i]
        if width <= 0:
            raise ValueError(f"Bin width must be positive; "
                             f"got width {width} at bin index {i}")
        widths.append(width)

    # Compute integral as sum of bin values times widths
    total = 0.0
    for val, w in zip(bins_float, widths):
        total += val * w

    return total

