    try:
        nbins = len(bins)
        nedges = len(edges)
    except Exception as exc:
        raise TypeError("bins and edges must be sequence-like types") from exc

    if nbins == 0:
        # Nothing to integrate, return zero
        return 0.0

    if nedges != nbins + 1:
        raise ValueError(
            f"Number of edges ({nedges}) must be exactly one more than number of bins ({nbins})"
        )

    # Compute integral as sum of bin values times bin widths
    total = 0.0
    try:
        for i in range(nbins):
            # Width of the current bin
            width = edges[i + 1] - edges[i]
            # Contribution of this bin to the integral
            total += bins[i] * width
    except Exception as exc:
        raise ValueError("bins and edges must contain numeric values") from exc

    return total

