    """
    # Validate inputs
    if not isinstance(d1, dict) or not isinstance(d2, dict):
        raise TypeError("Both d1 and d2 must be dictionaries")

    # Normalise level: -1 means unlimited recursion
    def _diff(src, target, lvl):
        result = {}
        for key, val in src.items():
            if key not in target:
                # Key missing in target: include value
                result[key] = dict(val) if isinstance(val, dict) else val
            else:
                val2 = target[key]
                if isinstance(val, dict) and isinstance(val2, dict):
                    # Both values are dictionaries
                    if lvl == 0:
                        # Do not recurse further: consider them different
                        result[key] = dict(val) if isinstance(val, dict) else val
                    else:
                        # Recurse with decremented level if lvl > 0, else keep lvl (-1)
                        next_lvl = lvl - 1 if lvl > 0 else lvl
                        sub = _diff(val, val2, next_lvl)
                        if sub:
                            result[key] = sub
                else:
                    # Primitive values or mismatched types
                    if val != val2:
                        result[key] = val
        return result

    try:
        return _diff(d1, d2, level)
    except Exception as exc:
        raise RuntimeError("An error occurred while computing the difference") from exc

