def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """

    # Helper that performs the recursive comparison.
    def _diff(inner_d1, inner_d2, depth):
        if not isinstance(inner_d1, dict):
            raise TypeError("The first argument must be a dictionary.")
        if inner_d2 is None:
            # If d2 is None, just copy d1.
            return dict(inner_d1)

        result = {}
        for key, val in inner_d1.items():
            if key not in inner_d2:
                # Key missing in d2 – include it.
                if isinstance(val, dict):
                    # Return a shallow copy for consistency
                    result[key] = dict(val)
                else:
                    result[key] = val
            else:
                d2_val = inner_d2[key]

                # If we cannot recurse (depth == 0), compare directly.
                if depth == 0:
                    if val != d2_val:
                        # Include the differing value.
                        if isinstance(val, dict):
                            result[key] = dict(val)
                        else:
                            result[key] = val
                    continue

                # Negative depth indicates infinite recursion.
                next_depth = depth - 1 if depth > 0 else -1

                # If both values are dictionaries, recurse.
                if isinstance(val, dict) and isinstance(d2_val, dict):
                    sub_diff = _diff(val, d2_val, next_depth)
                    if sub_diff:
                        result[key] = sub_diff
                else:
                    # One or both are not dictionaries; include if they differ.
                    if val != d2_val:
