    if not isinstance(d1, dict):
        raise TypeError("d1 must be a dictionary")
    if d2 is None or not isinstance(d2, dict):
        # If d2 is None or not a dict, the difference is just d1.
        return dict(d1)

    # Determine initial depth.
    init_depth = -1 if level == -1 else int(level)

    # Compute and return the difference.
    return _diff(d1, d2, init_depth)

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    import numpy as np

    # Ensure the histogram has the expected attributes
    try:
        edges = getattr(self, "edges")
        bins = getattr(self, "bins")
    except AttributeError as e:
        raise AttributeError(
            "The histogram object must have 'edges' and 'bins' attributes"
        ) from e

    if edges is None or bins is None:
        raise ValueError("Histogram not properly initialized: missing edges or bins")

    # Convert the coordinate to a numpy array and validate its dimensions
    try:
        coord_arr = np.asarray(coord)
    except Exception as e:
        raise TypeError("coord must be array‑like") from e

    if coord_arr.ndim != 1 or coord_arr.size != len(edges):
        raise ValueError(
            f"coord must have length equal to histogram dimensionality ({len(edges)})"
        )

    # Find the bin index for each dimension, ignoring out-of‑range coords
    bin_indices = []
    for dim, edge in enumerate(edges):
        if coord_arr[dim] < edge[0] or coord_arr[dim] >= edge[-1]:
            return  # coordinate lies outside the histogram bounds
        # Locate the bin using searchsorted (right edge inclusive, left exclusive)
        idx = np.searchsorted(edge, coord_arr[dim], side="right") - 1
        if idx < 0 or idx >= len(edge) - 1:
            return  # safety guard (should not happen)
        bin_indices.append(idx)

    # Increment the histogram bin by the given weight
    try:
        bins[tuple(bin_indices)] += weight
    except Exception as e:
        raise RuntimeError("Failed to update histogram bin") from e

