    if not hasattr(self, "edges") or not hasattr(self, "data"):
        raise AttributeError("Histogram object missing required 'edges' or 'data' attributes")

    # Ensure coord is an iterable with correct dimensionality
    if not hasattr(coord, "__iter__"):
        raise TypeError("coord must be an iterable of coordinates")
    coord = tuple(coord)
    if len(coord) != len(self.edges):
        raise ValueError(f"coord must have {len(self.edges)} elements, got {len(coord)}")

    # Find bin indices for each dimension
    import bisect
    indices = []
    for c, edges in zip(coord, self.edges):
        # Locate the rightmost index where edges[i] <= c
        idx = bisect.bisect_right(edges, c) - 1
        # If coordinate is outside the histogram range, ignore it
        if idx < 0 or idx >= len(edges) - 1:
            return
        indices.append(idx)

    # Increment the appropriate bin
    try:
