    """
    try:
        # Validate weight
        if not isinstance(weight, (int, float)):
            raise TypeError(f"Weight must be numeric, got {type(weight).__name__}")

        # Ensure coord is an iterable with the correct dimensionality
        if isinstance(coord, (list, tuple)):
            coord_iter = list(coord)
        else:
            # Allow a single scalar if the histogram is 1‑D
            if self.ndim != 1:
                raise ValueError(f"Coordinate should be a sequence of length {self.ndim}")
            coord_iter = [coord]

        if len(coord_iter) != self.ndim:
            raise ValueError(f"Coordinate length {len(coord_iter)} does not match histogram dimensionality {self.ndim}")

        # Find the bin indices for each dimension
        bin_indices = []
        for c, edges in zip(coord_iter, self.edges):
            # edges is a monotonically increasing sequence defining bin boundaries
            # The bin is the interval [edges[i], edges[i+1]), so find i such that
            # edges[i] <= c < edges[i+1]
            found = False
            for i in range(len(edges) - 1):
                if edges[i] <= c < edges[i + 1]:
                    bin_indices.append(i)
                    found = True
                    break
            if not found:
                # Coordinate is outside the valid range; ignore
                return

        # Increment the histogram value at the found bin
        self.data[tuple(bin_indices)] += weight

    except Exception as exc:
        # Provide context for debugging while hiding internal details
        raise RuntimeError(f"Failed to fill histogram at {coord} with weight {weight}") from exc

