                else:
                    new_list.append(None)
            result[key] = new_list
            continue

        # Primitive values
        if first_level and key in identifying_keys:
            # Preserve the original value for identifying keys
            result[key] = value
        else:
            result[key] = None

    return result

def _convert_list(l):
    """Helper to apply the default conversion logic to a list."""
    new_list = []
    for element in l:
        if isinstance(element, dict):
            new_list.append(generate_default_observer_schema_dict(element, first_level=False))
        elif isinstance(element, list):
            new_list.append(_convert_list(element))
        else:
            new_list.append(None)
    return new_list

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """Together with :func:``generate_default_observer_schema_list``, this function is
    called recursively to generate part of a default ``observer_schema`` from part of a
    Kubernetes resource, defined respectively by ``manifest_dict`` or ``manifest_list``.

    Args:
        manifest_dict (dict): Partial Kubernetes resources
        first_level (bool, optional): If True, indicates that the dictionary represents
            the whole observer schema of a Kubernetes resource

    Returns:
        dict: Generated partial observer_schema

    This function creates a new dictionary from ``manifest_dict`` and replaces all
    non-list and non-dict values by ``None``.

    In case of ``first_level`` dictionary (i.e. complete ``observer_schema`` for a
    resource), the values of the identifying fields are copied from the manifest file.

    """
    # Identify the keys that are considered identifying fields at the top level.
    IDENTIFYING_FIELDS = {"apiVersion", "kind"}

    def _process(value, is_top=False):
        # Process a value which may be a dict, list, or a scalar.
        if isinstance(value, dict):
            processed = {}
            for k, v in value.items():
                # At the top level we may keep identifying fields as is.
                if is_top and k in IDENTIFYING_FIELDS:
                    processed[k] = v
                else:
                    processed[k] = _process(v, is_top=False)
            return processed
        elif isinstance(value, list):
            # Process each element in the list
            return [_process(item, is_top=False) for item in value]
        else:
            # Scalars are replaced with None unless we are at the top identifying field
            return None

    if not isinstance(manifest_dict, dict):
        raise TypeError(
            f"Expected manifest_dict to be a dict, got {type(manifest_dict).__name__}"
        )

    try:
        return _process(manifest_dict, is_top=first_level)
    except Exception as exc:  # pragma: no cover
        # In case of any unexpected errors, re-raise with a clear message
        raise RuntimeError(
            f"Error generating default observer schema dict: {exc}"
        ) from exc

def update_last_applied_manifest_list_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Recursively update a partial ``last_applied_manifest`` list using a
    partial response from the Kubernetes API and the observer schema.

    Args:
        last_applied_manifest (list): The list being updated.
        observer_schema (list): Schema describing the expected list elements
            (may contain nested schemas for dict elements).
        response (list): Partial response from the Kubernetes API.

    Returns:
        list: The updated ``last_applied_manifest`` list.

    The function expands the ``last_applied_manifest`` to match the
    ``observer_schema`` length and fills missing entries with the values from
    ``response`` when present.  For entries that represent nested dictionaries,
    :func:`update_last_applied_manifest_dict_from_resp` is called
    recursively (the function must exist in the same module).
    """
    # Basic input validation
    try:
        if not isinstance(last_applied_manifest, list):
            raise TypeError("last_applied_manifest must be a list")
        if not isinstance(observer_schema, list):
            raise TypeError("observer_schema must be a list")
        if not isinstance(response, list):
            raise TypeError("response must be a list")
    except Exception as e:
        # If inputs are invalid, simply return the original manifest unchanged
        return last_applied_manifest

    # Ensure the manifest list is at least as long as the observer schema
    for idx, schema_item in enumerate(observer_schema):
        if idx >= len(last_applied_manifest):
            # If the response provides a value, copy it; otherwise use an empty dict
            if idx < len(response):
                last_applied_manifest.append(response[idx])
            else:
                last_applied_manifest.append({})

        # Handle nested dictionary schemas
        if isinstance(schema_item, dict):
            # Determine the nested schema; default to empty list if unspecified
            nested_schema = schema_item.get("schema", [])
            # Get the corresponding response element if it exists
            nested_resp = response[idx] if idx < len(response) else {}
            # Recurse only if the element in the manifest is a dict
            if isinstance(last_applied_manifest[idx], dict):
                try:
                    # The nested update function should already be defined
                    update_last_applied_manifest_dict_from_resp(
                        last_applied_manifest[idx], nested_schema, nested_resp
                    )
                except Exception:
                    # Silently ignore failures for nested updates to avoid breaking the loop
                    pass

    return last_applied_manifest

def update_last_applied_manifest_list_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Together with :func:``update_last_applied_manifest_dict_from_resp``, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (list): partial ``last_applied_manifest`` being
            updated
        observer_schema (list): partial ``observer_schema``
        response (list): partial response from the Kubernetes API.

    This function go through all observed fields, and initialized their value in
    last_applied_manifest if they are not yet present

    """
    # Basic type validation
    if not isinstance(last_applied_manifest, list) or not isinstance(observer_schema, list) or not isinstance(response, list):
        return last_applied_manifest

    # Ensure the length of last_applied_manifest matches observer_schema
    for idx, schema in enumerate(observer_schema):
        try:
            # Fetch or create the element in last_applied_manifest
            if idx < len(last_applied_manifest):
                elem = last_applied_manifest[idx]
            else:
                # Create a placeholder based on the schema type
                if isinstance(schema, dict):
                    elem = {}
                elif isinstance(schema, list):
                    elem = []
                else:
                    elem = None
                last_applied_manifest.append(elem)

            # Fetch the corresponding response element
            resp_elem = response[idx] if idx < len(response) else {}

            # Recursive handling based on the schema type
            if isinstance(schema, dict) and isinstance(elem, dict):
                # Update a dictionary element
                update_last_applied_manifest_dict_from_resp(elem, schema, resp_elem)
            elif isinstance(schema, list) and isinstance(elem, list):
                # Update a list element
                update_last_applied_manifest_list_from_resp(elem, schema, resp_elem)
            else:
                # If the schema indicates a scalar or the element is None,
                # initialize it from the response if available
                if elem is None and resp_elem is not None:
                    last_applied_manifest[idx] = resp_elem
        except Exception:
            # Skip problematic indices but continue processing others
            continue

    return last_applied_manifest

def generate_default_observer_schema(app):
    """
    Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    Returns:
        dict: Mapping from resource names to their default observer schemas.
    """
    try:
        # Retrieve the list of resources from the application spec
        manifests = getattr(app.spec, "manifest", [])
        if not isinstance(manifests, list):
            raise TypeError("app.spec.manifest must be a list of resource dictionaries")

        # Custom observer schemas already defined in the application
        custom_schemas = getattr(app.spec, "observer_schema", {})
        if not isinstance(custom_schemas, dict):
            raise TypeError("app.spec.observer_schema must be a dictionary")

        defaults = {}
        for resource in manifests:
            # Skip entries that are not mappings
            if not isinstance(resource, dict):
                continue

            # Determine a unique key for the resource (name or metadata.name)
            name = None
            if "name" in resource:
                name = resource["name"]
            else:
                metadata = resource.get("metadata", {})
                if isinstance(metadata, dict):
                    name = metadata.get("name")

            # Skip resources without a recognizable name
            if not isinstance(name, str) or not name:
                continue

            # If a custom observer schema already exists, skip generating the default
            if name in custom_schemas:
                continue

            # Create a minimal default schema – an empty object schema
            default_schema = {
                "type": "object",
                "properties": {}
            }

            defaults[name] = default_schema

        return defaults
    except (AttributeError, TypeError, ValueError) as exc:
        # Wrap any issue that arises in a ValueError for clarity
        raise ValueError(f"Could not generate default observer schema: {exc}") from exc

def format(self, sql, params):
    """
    Convert the SQL query to use the out-style parameters instead of
    the in-style parameters.

    *sql* (:class:`str` or :class:`bytes`) is the SQL query.

    *params* (:class:`~collections.abc.Mapping` or :class:`~collections.abc.Sequence`)
    contains the set of in-style parameters. It maps each parameter
    (:class:`str` or :class:`int`) to value. If :attr:`.SQLParams.in_style`
    is a named parameter style. then *params* must be a :class:`~collections.abc.Mapping`.
    If :attr:`.SQLParams.in_style` is an ordinal parameter style, then
    *params* must be a :class:`~collections.abc.Sequence`.

    Returns a :class:`tuple` containing:

    -   The formatted SQL query (:class:`str` or :class:`bytes`).

    -   The set of converted out-style parameters (:class:`dict` or
        :class:`list`).
    """
    # Retrieve the instance's input parameter style
    try:
        in_style = getattr(self, "in_style")
    except Exception as exc:
        raise AttributeError("Instance must have an 'in_style' attribute") from exc

    # Converting named parameters to '?' placeholders
    def _convert_named(sql_str, mapping):
        import re
        pattern = re.compile(r"(:\w+)|%\(([^)]+)\)s")
        names = []

        def repl(match):
            if match.group(1):
                name = match.group(1)[1:]
            else:
                name = match.group(2)
            names.append(name)
            return "?"

        new_sql = pattern.sub(repl, sql_str)
        try:
            values = [mapping[name] for name in names]
        except KeyError as exc:
            raise ValueError(f"Missing parameter for placeholder {exc}") from exc
        return new_sql, values

    # No conversion needed for ordinal; just verify length
    def _convert_ordinal(sql_str, seq):
        placeholder_count = sql_str.count("?")
        if placeholder_count != len(seq):
            raise ValueError(
                f"Placeholder count ({placeholder_count}) does not match params length ({len(seq)})"
            )
        return sql_str, list(seq)

    # Normalize sql to text
    if isinstance(sql, bytes):
        try:
            sql_text = sql.decode()
        except Exception:
            sql_text = sql.decode("latin1")
    else:
        sql_text = sql

    if in_style == "named":
        if not isinstance(params, dict):
            raise TypeError("For named parameters, 'params' must be a mapping.")
        formatted_sql, out_params = _convert_named(sql_text, params)
    elif in_style == "ordinal":
        if not hasattr(params, "__iter__") or isinstance(params, (str, bytes)):
            raise TypeError

def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    try:
        import os
        nspath = os.path.abspath(path)
        if not os.path.isdir(nspath):
            # Path must be an existing directory
            return False

        # If the directory contains an .ocfl-version file, treat it as an OCFL object
        ocfl_version = os.path.join(nspath, ".ocfl-version")
        if os.path.isfile(ocfl_version):
            # Basic validity checks for a single OCFL object
            try:
                with open(ocfl_version, "r", encoding="utf-8") as f:
                    version = f.read().strip()
                # Accept known OCFL versions; extend as needed
                if version not in {"00.1.0", "01.0.0"}:
                    return False
            except Exception:
                return False

            # The object should have an "objects" directory
            objects_dir = os.path.join(nspath, "objects")
            if not os.path.isdir(objects_dir):
                return False

            # Each commit directory should contain a metadata.xml that is well‑formed
            for commit_name in os.listdir(objects_dir):
                commit_path = os.path.join(objects_dir, commit_name)
                if not os.path.isdir(commit_path):
                    continue  # skip non‑directory entries
                metadata_path = os.path.join(commit_path, "metadata.xml")
                if not os.path.isfile(metadata_path):
                    return False
                try:
                    import xml.etree.ElementTree as ET
                    ET.parse(metadata_path)
                except Exception:
                    return False

            # All checks passed
            return True

        # If there's no .ocfl-version file, treat the path as a pyfs root that
        # contains multiple OCFL objects
        subdirs = [d for d in os.listdir(nspath) if os.path.isdir(os.path.join(nspath, d))]
        if not subdirs:
            # Nothing to validate
            return False

        for sub in subdirs:
            sub_path = os.path.join(nspath, sub)
            if not self.validate(sub_path):
                return False
        return True
    except Exception:
        # Any unexpected error results in a validation failure
        return False

def validate(self, path):
    """
    Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    try:
        # Input validation
        if not isinstance(path, str):
            raise TypeError("path must be a string")

        # Ensure the path exists
        import os  # local import to avoid module-level imports
        if not os.path.exists(path):
            return False

        # Basic OCFL structure checks
        # Most OCFL objects contain an 'objects' directory with subdirectories
        objects_dir = os.path.join(path, "objects")
        if not os.path.isdir(objects_dir):
            return False

        # At least one object ID directory should exist
        object_ids = [
            name for name in os.listdir(objects_dir)
            if os.path.isdir(os.path.join(objects_dir, name))
        ]
        if not object_ids:
            return False

        # Verify each object has a COMMITMENT file
        for obj_id in object_ids:
            obj_dir = os.path.join(objects_dir, obj_id)
            commitment_file = os.path.join(obj_dir, "COMMITMENT")
            if not os.path.isfile(commitment_file):
                return False

        # If all basic checks pass, we consider it valid
        return True
    except Exception:
        # Any unexpected error should result in validation failure
        return False

def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    try:
        # Resolve target root
        if path is None:
            if hasattr(self, "root"):
                root = self.root
            else:
                return False
        else:
            root = path

        # Validate presence of the .ocfl-version file
        ocfl_version_path = os.path.join(root, ".ocfl-version")
        if not os.path.isfile(ocfl_version_path):
            return False

        # Read and sanity‑check the version string
        try:
            with open(ocfl_version_path, "r", encoding="utf-8") as f:
                version = f.read().strip()
        except (OSError, IOError):
            return False

        # Only simple numeric version format is accepted
        if not re.match(r"^\d+\.\d+$", version):
            return False

        # Check that the mandatory "objects" directory exists
        objects_dir = os.path.join(root, "objects")
        if not os.path.isdir(objects_dir):
            return False

        # Basic checks passed; consider the OCFL object valid
        return True

    except Exception:
        # Any unexpected error is treated as a failed validation
        return False

def status_str(self, prefix=''):
    """Return string of validator status, with optional prefix."""
    try:
        if prefix is None:
            prefix = ''
        parts = []
        # Determine overall validity if available
        has_valid = hasattr(self, 'valid')
        if has_valid:
            val = getattr(self, 'valid')
            parts.append('valid' if val else 'invalid')
        # Count errors if present
        if hasattr(self, 'errors'):
            err = getattr(self, 'errors')
            if isinstance(err, (list, tuple, set)):
                count = len(err)
                parts.append(f"errors={count}" if count else "no errors")
            else:
                parts.append(f"errors={err}")
        # Count warnings if present
        if hasattr(self, 'warnings'):
            warn = getattr(self, 'warnings')
            if isinstance(warn, (list, tuple, set)):
                count = len(warn)
                parts.append(f"warnings={count}" if count else "no warnings")
            else:
                parts.append(f"warnings={warn}")
        status = ', '.join(parts) if parts else 'unknown status'
        return f"{prefix}: {status}" if prefix else status
    except Exception as exc:
        err_msg = f"Error retrieving status: {exc}"
        return f"{prefix}: {err_msg}" if prefix else err_msg

