def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    # Basic type check
    if not isinstance(inventory, dict):
        raise TypeError(f"Inventory must be a dict, got {type(inventory).__name__}")

    # Required keys in the inventory (example: name and components)
    required_keys = {"name", "components"}
    missing = required_keys - inventory.keys()
    if missing:
        raise ValueError(f"Inventory is missing required keys: {', '.join(sorted(missing))}")

    # Validate components is a list (or similar iterable)
    components = inventory.get("components")
    if not isinstance(components, (list, tuple)):
        raise TypeError(f"'components' must be a list or tuple, got {type(components).__name__}")

    # Optional: basic validation of each component
    for idx, comp in enumerate(components, start=1):
        if not isinstance(comp, dict):
            raise TypeError(f"Component #{idx} must be a dict, got {type(comp).__name__}")
        if "id" not in comp or "type" not in comp:
            raise ValueError(f"Component #{idx} is missing required 'id' or 'type' keys")

    # Handle spec version extraction
    spec_version = getattr(self, "spec_version", None)
    if extract_spec_version:
        type_value = inventory.get("type")
        if isinstance(type_value, str):
            # Try to extract a numeric suffix (e.g., 'inventory-v2' -> '2')
            import re
            match = re.search(r"(?i)spec[ -]?v?(\\d+)", type_value)
            if match:
                extracted = match.group(1)
                if extracted.isdigit():
                    spec_version = extracted
        if not spec_version:
            # Fallback to self.spec_version if already set
            spec_version = getattr(self, "spec_version", None)

    # Validate spec_version format (assuming it should be a string of digits)
    if spec_version is None or not isinstance(spec_version, str) or not spec_version.isdigit():
        raise ValueError(f"Unsupported or missing specification version: {spec_version!r}")

    # All checks passed; optionally store spec_version for later use
    setattr(self, "_validated_spec_version", spec_version)
    return True

