            # Extract spec version if requested
            if extract_spec_version:
                inv_type = inventory.get("type")
                if isinstance(inv_type, str):
                    known_specs = {"aws", "azure", "gcp", "v1", "v2"}
                    spec = inv_type.lower()
                    if spec in known_specs:
                        self.spec_version = spec
            # Ensure required top-level keys
            required_keys = ["items"]
            for key in required_keys:
                if key not in inventory:
                    raise ValueError(f"inventory missing required key: '{key}'")
            items = inventory["items"]
            if not isinstance(items, list):
                raise ValueError("inventory['items'] must be a list")
            # Validate each item structure
            for idx, item in enumerate(items):
                if not isinstance(item, dict):
                    raise ValueError(f"inventory['items'][{idx}] must be a dict")
                if "name" not in item or not isinstance(item["name"], str):
                    raise ValueError(f"inventory['items'][{idx}] missing valid 'name' field")
                if (
                    "quantity" not in item
                    or not isinstance(item["quantity"], int)
                    or item["quantity"] < 0
                ):
                    raise ValueError(
                        f"inventory['items'][{idx}] missing valid 'quantity' field"
                    )
            return True
        except Exception as exc:
            # Re-wrap to provide a clearer message
            raise RuntimeError("Inventory validation failed") from exc

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    # Validate input types
    if not isinstance(manifest_files, (list, tuple)):
        raise TypeError(f"manifest_files must be a list or tuple, got {type(manifest_files).__name__}")
    if not isinstance(digests_used, (set, frozenset, list, tuple)):
        raise TypeError(f"digests_used must be an iterable of digests, got {type(digests_used).__name__}")

    # Gather all digests present in the manifest
    present_digests = set()
    for entry in manifest_files:
        if not isinstance(entry, dict):
            continue  # skip non-dictionary entries
        digest = entry.get('digest')
        if digest:
            present_digests.add(digest)

    # Convert digests_used to a set for comparison
    expected_digests = set(digests_used)

    # Determine missing and unused digests
    missing = expected_digests - present_digests
    unused = present_digests - expected_digests

    # Raise informative errors if any inconsistencies are found
    if missing:
        raise ValueError(f"Missing required digests in manifest: {sorted(missing)}")
    if unused:
        raise ValueError(f"Additional digests present in manifest but not used: {sorted(unused)}")

    return True

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    # Validate the manifest_files input
    if manifest_files is None:
        raise TypeError("manifest_files cannot be None")
    try:
        manifest_digests = set()
        for entry in manifest_files:
            if not isinstance(entry, dict):
                raise TypeError(f"Each manifest file entry must be a dict, got {type(entry).__name__}")
            if 'digest' not in entry:
                raise KeyError("Manifest file entry missing required 'digest' key")
            digest = entry['digest']
            if not isinstance(digest, str):
                raise TypeError(f"Digest must be a string, got {type(digest).__name__}")
            manifest_digests.add(digest)
    except Exception as exc:
        raise ValueError(f"Failed to process manifest files: {exc}") from exc

    # Validate the digests_used input
    if digests_used is None:
        raise TypeError("digests_used cannot be None")
    try:
        used_set = set()
        for d in digests_used:
            if not isinstance(d, str):
                raise TypeError(f"digests_used must contain strings, got {type(d).__name__}")
            used_set.add(d)
    except Exception as exc:
        raise ValueError(f"Failed to process digests_used: {exc}") from exc

    # Find missing and unused digests
    missing = manifest_digests - used_set
    if missing:
        raise ValueError(f"The following digests expected by the manifest are missing from digests_used: {', '.join(sorted(missing))}")

    unused = used_set - manifest_digests
    # We do not raise an error for unused digests; emit a warning instead.
    if unused:
        try:
            import warnings
            warnings.warn(f"These digests were provided but not present in the manifest: {', '.join(sorted(unused))}",
                          RuntimeWarning)
        except Exception:
            # Fall back to a simple print if warnings cannot be imported
            print(f"WARNING: These digests were provided but not present in the manifest: {', '.join(sorted(unused))}")
    return None

def validate_as_prior_version(self, prior):
    """
    Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Ensure prior is an object (avoid accidental None or wrong types)
    if prior is None:
        raise ValueError("The 'prior' argument is None; a valid prior inventory is required.")
    # Attempt to extract a version identifier from both objects.
    # If either does not provide a numeric or comparable version, raise an error.
    try:
        self_version = getattr(self, "version", None)
        prior_version = getattr(prior, "version", None)
    except Exception as exc:
        raise ValueError(f"Unable to access 'version' attributes: {exc}") from exc

    if self_version is None:
        raise ValueError("The current inventory object does not provide a 'version' attribute.")
    if prior_version is None:
        raise ValueError("The prior inventory object does not provide a 'version' attribute.")

    # If the version is not comparable (e.g., not a number or string that can be compared),
    # we fall back to comparing timestamps if available.
    def _compare(v1, v2):
        try:
            return v1 < v2
        except TypeError:
            # Try string comparison if both are strings
            if isinstance(v1, str) and isinstance(v2, str):
                return v1 < v2
            return None

    if _compare(prior_version, self_version) is None:
        # Try to use timestamps as a last resort
        try:
            self_ts = getattr(self, "timestamp", None)
            prior_ts = getattr(prior, "timestamp", None)
            if self_ts is None or prior_ts is None:
                raise ValueError("Cannot compare prior and current inventories: "
                                 "neither 'version' nor 'timestamp' is reliably comparable.")
            if not _compare(prior_ts, self_ts):
                raise ValueError("The prior inventory timestamp is not earlier than "
                                 "the current inventory timestamp.")
        except Exception as exc:
            raise ValueError(f"Unable to compare inventory versions: {exc}") from exc
    else:
        if not _compare(prior_version, self_version):
            raise ValueError("The prior inventory must have an earlier version than the current inventory.")
    # If all checks pass, the method completes silently (no return).

def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Ensure prior is provided and is the same type as self
    if prior is None:
        raise ValueError("Missing prior inventory for validation.")
    if type(prior) is not type(self):
        raise TypeError(f"Expected prior to be of type {type(self).__name__}, got {type(prior).__name__}")

    # Attempt to access expected attributes
    try:
        self_id = getattr(self, "id")
        self_version = getattr(self, "version")
        prior_id = getattr(prior, "id")
        prior_version = getattr(prior, "version")
    except AttributeError as exc:
        raise AttributeError("Inventory objects lack required 'id' or 'version' attributes.") from exc

    # Ensure identifiers match
    if self_id != prior_id:
        raise ValueError(f"Inventory identifiers do not match: {self_id!r} vs {prior_id!r}")

    # Verify version progression
    try:
        if not (isinstance(self_version, (int, float)) and isinstance(prior_version, (int, float))):
            raise TypeError("Version attributes must be numeric.")
        if prior_version >= self_version:
            raise ValueError(f"Prior version ({prior_version}) is not older than current version ({self_version}).")
    except Exception as exc:
        raise ValueError(f"Failed to validate version ordering: {exc}") from exc

    # If all checks pass, simply return None (indicates success)
    return None

def validate_as_prior_version(self, prior):
    """
    Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Ensure prior is a proper InventoryValidator instance
    if not hasattr(prior, 'inventory'):
        raise TypeError("The prior object must have an 'inventory' attribute and be an InventoryValidator.")
    if not hasattr(self, 'inventory'):
        raise TypeError("The current object must have an 'inventory' attribute and be an InventoryValidator.")

    # Validate that inventories are present
    if self.inventory is None or prior.inventory is None:
        raise ValueError("Both the current and prior inventories must be non‑None.")

    # Helper to extract version-like information
    def _extract_version(inv):
        # Prefer a numeric `version` field
        if isinstance(inv, dict) and 'version' in inv and isinstance(inv['version'], (int, float)):
            return inv['version']
        # Fallback to an ISO‑8601 `created_at` or `updated_at` timestamp
        if isinstance(inv, dict):
            for key in ('created_at', 'updated_at', 'timestamp'):
                if key in inv and isinstance(inv[key], str):
                    return inv[key]
        # If the inventory is an object, try attributes
        for attr in ('version', 'created_at', 'updated_at', 'timestamp'):
            if hasattr(inv, attr):
                val = getattr(inv, attr)
                if isinstance(val, (int, float, str)):
                    return val
        return None

    current_version = _extract_version(self.inventory)
    prior_version = _extract_version(prior.inventory)

    if current_version is None or prior_version is None:
        raise ValueError("Could not extract comparable version information from the inventories.")

    try:
        # Numeric comparison
        if isinstance(current_version, (int, float)) and isinstance(prior_version, (int, float)):
            if prior_version >= current_version:
                raise ValueError("The prior inventory is not older than the current inventory.")
        else:
            # Attempt ISO‑8601 string parsing
            import datetime
            def _parse_ts(ts):
                if isinstance(ts, datetime.datetime):
                    return ts
                if isinstance(ts, str):
                    try:
                        # Handles full ISO format including timezone
                        return datetime.datetime.fromisoformat(ts.replace('Z', '+00:00'))
                    except Exception as e:
                        raise ValueError(f"Unable to parse timestamp '{ts}': {e}")
                raise ValueError(f"Unsupported timestamp type: {type(ts)}")

            cur_dt = _parse_ts(current_version)
            prior_dt = _parse_ts(prior_version)
            if prior_dt >= cur_dt:
                raise ValueError("The prior inventory is not older than the current inventory.")
    except Exception as ex:
        # Re‑raise as ValueError to keep API consistent
        raise ValueError(f"Validation failed: {ex}")

    # If we made it here, prior is a valid prior version
    return True

def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Basic type check
    if not isinstance(prior, type(self)):
        raise TypeError(
            f"prior must be an instance of {type(self).__name__} (got {type(prior).__name__})"
        )
    if prior is self:
        raise ValueError("prior cannot be the same instance as the current object")

    # Version handling – accept any attribute that looks like a numeric or
    # comparable value (e.g., int, float, datetime.datetime)
    def _get_version(obj, name):
        if hasattr(obj, name):
            return getattr(obj, name)
        msg = f"object of type {type(obj).__name__} missing required version attribute '{name}'"
        raise AttributeError(msg)

    # Try multiple common names for the version attribute
    version_attrs = ["version", "timestamp", "created_at", "updated_at"]
    self_version = None
    prior_version = None
    for attr in version_attrs:
        try:
            if self_version is None:
                self_version = _get_version(self, attr)
            if prior_version is None:
                prior_version = _get_version(prior, attr)
        except AttributeError:
            continue
    if self_version is None or prior_version is None:
        raise AttributeError(
            "Unable to determine version numbers for validation (missing 'version' or equivalent attribute)"
        )

    # Ensure versions are comparable and prior is older
    try:
        if prior_version >= self_version:
            raise ValueError(
                f"prior version ({prior_version}) is not older than current version ({self_version})"
            )
    except TypeError as e:
        raise TypeError(
            f"version attributes must be comparable; got types {type(prior_version).__name__} and {type(self_version).__name__}"
        ) from e

    # Inventory representation – look for most common attribute names
    inv_attrs = ["inventory", "data", "items", "lookup"]
    self_inv = None
    prior_inv = None
    for attr in inv_attrs:
        if hasattr(self, attr):
            self_inv = getattr(self, attr)
        if hasattr(prior, attr):
            prior_inv = getattr(prior, attr)
    if self_inv is None or prior_inv is None:
        raise AttributeError(
            "Both objects must expose an inventory representation (dict-like structure)"
        )

    if not isinstance(self_inv, dict) or not isinstance(prior_inv, dict):
        raise TypeError(
            "Inventory representations must be dictionary-like objects"
        )

    # Ensure prior does not contain keys that are absent from the current inventory
    extra_keys = set(prior_inv.keys()) - set(self_inv.keys())
    if extra_keys:
        raise ValueError(
            f"prior inventory contains keys that are missing from the current inventory: {sorted(extra_keys)}"
        )

    # Basic type consistency for shared keys
    common_keys = set(self_inv) & set(prior_inv)
    for key in common_keys:
        cur_val = self_inv[key]
        pre_val = prior_inv[key]
        if type(cur_val) != type(pre_val):
            raise ValueError(
                f"Type mismatch for key '{key}': prior has {type(pre_val).__name__}, current has {type(cur_val).__name__}"
            )
        # Optional deeper validation could be added here

    # If we reach this point, the prior inventory is considered valid
    return True

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # Basic type checks
    if not isinstance(inventory, dict):
        raise TypeError("inventory must be a dictionary")
    if not isinstance(version, str):
        raise TypeError("version must be a string")

    # Locate the requested version
    versions = inventory.get("versions")
    if not isinstance(versions, dict):
        raise ValueError("inventory missing a 'versions' dictionary")
    version_data = versions.get(version)
    if version_data is None:
        raise KeyError(f"version '{version}' not found in inventory")

    result = {}

    try:
        # Handle the common case where version_data is a list of entries
        if isinstance(version_data, list):
            for entry in version_data:
                if not isinstance(entry, dict):
                    continue
                # Determine logical path key
                logical_key = entry.get("logical_path_in_state") or entry.get("logical_path")
                if logical_key is None:
                    continue
                s = result.setdefault(logical_key, set())

                # Preferred: entry has a list under 'content_files'
                content = entry.get("content_files")
                if isinstance(content, list):
                    for cf in content:
                        if isinstance(cf, str):
                            s.add(cf)
                    continue

                # Fallback: single file reference under common keys
                for k in ("content_file", "path", "file"):
                    cf = entry.get(k)
                    if isinstance(cf, str):
                        s.add(cf)

        # Handle the case where version_data is a mapping: logical_path -> list of files
        elif isinstance(version_data, dict):
            for logical_key, files in version_data.items():
                if not isinstance(files, list):
                    continue
                s = result.setdefault(logical_key, set())
                for cf in files:
                    if isinstance(cf, str):
                        s.add(cf)

        else:
            # Unknown structure
            raise ValueError("Unsupported structure for version data")

    except Exception as exc:
        # Wrap unexpected errors to provide clearer context
        raise RuntimeError(f"Error processing inventory for version '{version}': {exc}") from exc

    return result

def get_logical_path_map(inventory: dict, version) -> dict:
    """
    Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # Validate input types
    if not isinstance(inventory, dict):
        raise TypeError("inventory must be a dictionary")
    if version not in inventory:
        # If the version is not found, return an empty mapping
        return {}
    try:
        version_data = inventory[version]
        mapping: dict = {}
        # Support nested structures: expect version_data to be a mapping of
        # logical paths to a collection of content file paths.
        for logical_path, content in version_data.items():
            if logical_path is None:
                continue
            # Normalize content to an iterable of file paths
            if isinstance(content, (list, set, tuple)):
                files = content
            elif isinstance(content, dict):
                # If content itself is a dict, we take its values as file paths
                files = content.values()
            else:
                # Treat single string or other types as a single file path
                files = (content,)
            file_set = set()
            for f in files:
                # Ensure non-empty and string type
                if f:
                    file_set.add(str(f))
            mapping[str(logical_path)] = file_set
        return mapping
    except Exception as e:
        # If any unexpected structure causes a failure, raise a ValueError
        raise ValueError(f"Failed to build logical path map: {e}") from e

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # Validate inputs
    if not hasattr(inventory, '__iter__'):
        raise TypeError("inventory must be an iterable of inventory entries")
    if not isinstance(version, int):
        raise TypeError("version must be an integer")

    # Build a list of inventory entries sorted by version
    try:
        entries = sorted(
            (entry for entry in inventory if isinstance(entry, dict)),
            key=lambda e: e.get("version", float("-inf"))
        )
    except Exception as exc:
        raise ValueError(f"Error sorted inventory entries: {exc}") from exc

    # Find the base version entry and collect mappings
    logical_map = {}
    found = False
    for entry in entries:
        entry_version = entry.get("version")
        if entry_version is None:
            continue
        if entry_version < version:
            continue
        # At this point, entry_version >= version
        # Mark we have reached the target or later
        found = True
        state = entry.get("state")
        if not isinstance(state, dict):
            continue
        for logical_path, files in state.items():
            if not isinstance(logical_path, str):
                continue
            if logical_path not in logical_map:
                logical_map[logical_path] = set()
            try:
                logical_map[logical_path].update(files if isinstance(files, (list, set, tuple)) else [files])
            except Exception:
                # If files is not iterable, skip
                pass

    if not found:
        raise ValueError(f"No inventory entries found for version {version} or later")

    return logical_map

def get_logical_path_map(inventory, version):
    """
    Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # Validate inputs
    if not isinstance(inventory, dict):
        raise TypeError(f"inventory must be a dict, got {type(inventory).__name__}")
    if not isinstance(version, str):
        raise TypeError(f"version must be a string, got {type(version).__name__}")

    path_map = {}

    # Try to locate logical paths within the inventory
    # Common layout: inventory['states'][state_name]['logical_paths'][logical_path]['versions'][ver] -> files
    states = inventory.get("states", {})
    if not isinstance(states, dict):
        states = {}

    for state_name, state_data in states.items():
        if not isinstance(state_data, dict):
            continue

        logical_paths = state_data.get("logical_paths", {})
        if not isinstance(logical_paths, dict):
            continue

        for logical_path, lp_data in logical_paths.items():
            if not isinstance(lp_data, dict):
                continue

            versions = lp_data.get("versions", {})
            if not isinstance(versions, dict):
                continue

            content_files = versions.get(version)
            if not content_files:
                continue  # No files for this version at this logical path

            # Normalise to a set of strings
            if isinstance(content_files, (list, tuple, set)):
                files_set = set(content_files)
            else:
                files_set = {content_files}

            existing = path_map.get(logical_path)
            if existing is None:
                path_map[logical_path] = files_set
            else:
                existing.update(files_set)

    # If the above search yields nothing, try a simpler layout:
    # inventory[logical_path]['versions'][ver] = files
    if not path_map:
        for logical_path, lp_data in inventory.items():
            if not isinstance(lp_data, dict):
                continue
            versions = lp_data.get("versions")
            if not isinstance(versions, dict):
                versions = lp_data
            if not isinstance(versions, dict):
                continue
            content_files = versions.get(version)
            if not content_files:
                continue
            if isinstance(content_files, (list, tuple, set)):
                files_set = set(content_files)
            else:
                files_set = {content_files}
            existing = path_map.get(logical_path)
            if existing is None:
                path_map[logical_path] = files_set
            else:
                existing.update(files_set)

    return path_map

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    if inventory is None:
        raise ValueError("inventory must not be None")

    # Helper to process a single entry and update the result mapping
    def _process_entry(entry, result):
        try:
            # Try common key names for logical path and content file
            logical_path = None
            content_files = None

            if isinstance(entry, dict):
                logical_path = entry.get("logical_path") or entry.get("path")
                # The content can be a single file, a list, or nested under key 'files'/'file'/'content_file'
                if "content_file" in entry:
                    content_files = entry["content_file"]
                elif "file" in entry:
                    content_files = entry["file"]
                elif "content_files" in entry:
                    content_files = entry["content_files"]
                elif "files" in entry:
                    content_files = entry["files"]
                else:
                    # If entry itself is a string, treat it as content file
                    if isinstance(entry, str):
                        content_files = entry
                # The version must match
                ver = entry.get("version")
                if logical_path is None or content_files is None:
                    return  # nothing to do
                if ver != version:
                    return
                # Ensure the content files are iterable
                if isinstance(content_files, (list, tuple, set)):
                    files_iter = content_files
                else:
                    files_iter = [content_files]
                for cf in files_iter:
                    if cf:
                        result.setdefault(logical_path, set()).add(cf)
        except Exception:
            # Ignore malformed entries
            pass

    result = {}

    # Determine iterable over entries
    if isinstance(inventory, dict):
        # If dict maps logical_path -> list of entries
        for key, value in inventory.items():
            if isinstance(value, (list, tuple, set)):
                for sub in value:
                    # Wrap sub as dict with logical_path key if it's not already dict
                    if isinstance(sub, dict):
                        _process_entry(sub, result)
                    else:
                        # If sub is string or other, treat as content file for this logical path
                        if key:
                            result.setdefault(key, set()).add(sub)
            else:
                # Single entry mapped to a logical path
                if isinstance(value, dict):
                    _process_entry(value, result)
                else:
                    if key:
                        result.setdefault(key, set()).add(value)
    else:
        # Treat inventory itself as iterable of entries
        try:
            for entry in inventory:
                _process_entry(entry, result)
        except TypeError:
            # Not iterable, try treating as single entry dict
            _process_entry(inventory, result)

    return result

def validate_fixity(self, fixity, manifest_files):
        """Validate fixity block in inventory.

        Check the structure of the fixity block and makes sure that only files
        listed in the manifest are referenced.
        """
        # Ensure manifest_files is a set for fast lookup
        try:
            manifest_set = set(manifest_files)
        except TypeError:
            raise ValueError("manifest_files must be an iterable of file names")

        if not isinstance(fixity, dict):
            raise ValueError("fixity block must be a dictionary")

        for fname, hash_val in fixity.items():
            if not isinstance(fname, str):
                raise ValueError(f"fixity key {fname!r} is not a string")
            if fname not in manifest_set:
                raise ValueError(f"file {fname!r} referenced in fixity not found in manifest")
            if not isinstance(hash_val, str):
                raise ValueError(f"hash value for {fname!r} must be a string")
            if not hash_val:
                raise ValueError(f"hash value for {fname!r} is empty")

        # All checks passed: no return value needed (validation succeeded)

def validate_fixity(self, fixity, manifest_files):
        """
        Validate fixity block in inventory.

        Check that `fixity` is a dictionary containing a ``files`` key, that
        ``files`` is a list of dictionaries each containing a ``name`` key, and
        that every referenced file name appears in ``manifest_files``.
        Returns ``True`` if the block is valid, otherwise raises ``ValueError``.
        """
