    Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package
    Returns
    -------
    dict
    """
    import os
    from collections import defaultdict
    try:
        if not isinstance(folder, str) or not os.path.isdir(folder):
            return {}
        groups = defaultdict(list)
        for entry in os.listdir(folder):
            full_path = os.path.join(folder, entry)
            if os.path.isfile(full_path):
                name, _ = os.path.splitext(entry)
                groups[name].append(full_path)
        return dict(groups)
    except Exception:
        return {}

def _explore_folder(folder):
    """
    Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package
    Returns
    -------
    dict
        Dictionary where keys are basenames (without extension) of XML files
        and values are lists of full paths to all files in the folder that
        share that basename.
    """
    import os

    # Validate input
    if not isinstance(folder, str) or not folder:
        return {}

    if not os.path.isdir(folder):
        return {}

    try:
        all_entries = os.listdir(folder)
    except OSError:
        return {}

    # Build mapping from basename to list of full paths
    basename_map = {}
    for entry in all_entries:
        full_path = os.path.join(folder, entry)
        # Skip directories and symlinks that are not regular files
        if not os.path.isfile(full_path):
            continue

        base, _ = os.path.splitext(entry)
        basename_map.setdefault(base, []).append(full_path)

    # Only keep groups whose basename has an XML file
    result = {}
    for base, paths in basename_map.items():
        has_xml = any(os.path.splitext(p)[1].lower() == ".xml" for p in paths)
        if has_xml:
            result[base] = paths

    return result

