def pretty(self, indent=0, debug=False):
        """
        Return a pretty formatted representation of self.
        """
        def _dump(obj, level):
            prefix = ' ' * level
            if isinstance(obj, str):
                return repr(obj)
            if isinstance(obj, bytes):
                return repr(obj)
            if isinstance(obj, dict):
                if not obj:
                    return '{}'
                lines = []
                for k, v in obj.items():
                    k_part = _dump(k, level + 2)
                    v_part = _dump(v, level + 2)
                    lines.append(f'{k_part}: {v_part}')
                inner = ',\n'.join(prefix + '  ' + line for line in lines)
                return f'{{\n{inner}\n{prefix}}}'
            if isinstance(obj, (list, tuple, set)):
                if not obj:
                    if isinstance(obj, list):
                        return '[]'
                    if isinstance(obj, tuple):
                        return '()'
                    return 'set()'
                lines = [_dump(e, level + 2) for e in obj]
                inner = ',\n'.join(prefix + '  ' + l for l in lines)
                if isinstance(obj, list):
                    return f'[\n{inner}\n{prefix}]'
                if isinstance(obj, tuple):
                    return f'(\n{inner}\n{prefix})'
                return f'set([\n{inner}\n{prefix}])'
            if hasattr(obj, '__dict__'):
                attrs = obj.__dict__
                if not attrs:
                    return f'{obj.__class__.__name__}()'
                lines = []
                for k, v in attrs.items():
                    val = _dump(v, level + 2)
                    lines.append(f'{k}={val}')
                inner = ',\n'.join(prefix + '  ' + l for l in lines)
                return f'{obj.__class__.__name__}(\n{inner}\n{prefix})'
            if debug:
                return f'({type(obj).__name__}){repr(obj)}'
            return repr(obj)

        try:
            if indent < 0:
                raise ValueError("indent must be non-negative")
            return _

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    seen = set()

    def _repr(obj, level):
        """Recursively build a pretty string for *obj*."""
        indent_str = ' ' * (level * 4)
        # Prevent infinite recursion
        if id(obj) in seen:
            return f"{indent_str}<...>"
        seen.add(id(obj))

        if isinstance(obj, (str, int, float, bool, type(None))):
            return repr(obj)

        if isinstance(obj, (list, tuple, set)):
            items = ',\n'.join(_repr(item, level + 1) for item in obj)
            close = {list: ']', tuple: ')', set: '}'.__getitem__}
            if isinstance(obj, list):
                return f"[\n{items}\n{indent_str}]"
            if isinstance(obj, tuple):
                return f"(\n{items}\n{indent_str})"
            if isinstance(obj, set):
                return f"{{\n{items}\n{indent_str}}}"

        if hasattr(obj, "__dict__"):
            attrs = []
            for k, v in sorted(obj.__dict__.items()):
                attrs.append(f"{k}={_repr(v, level + 1)}")
            name = obj.__class__.__name__
            # Incorporate debug information if requested
            debug_info = ""
            if debug:
                debug_info = f"  # id={id(obj)}, module={obj.__class__.__module__}"
            return f"{name}(\n{indent_str}    " + f",\n{indent_str}    ".join(attrs) + f"\n{indent_str}){debug_info}"

        # Fallback for any other type
        return repr(obj)

    try:
        return _repr(self, indent // 4)
    except Exception as exc:  # pragma: no cover
        return f"<Error pretty printing {self!:r}: {exc!r}>"

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    def _format(value, level):
        pad = ' ' * level
        # Handle simple types
        if isinstance(value, (int, float, bool, type(None))):
            base = repr(value)
        elif isinstance(value, str):
            base = repr(value)
        elif isinstance(value, (list, tuple)):
            inner = ', '.join(_format(v, level + 2) for v in value)
            base = f"{'[' if isinstance(value, list) else '('}{inner}{']' if isinstance(value, list) else ')'}"
        elif isinstance(value, set):
            inner = ', '.join(_format(v, level + 2) for v in value)
            base = f"{{{inner}}}"
        elif isinstance(value, dict):
            items = []
            for k, v in value.items():
                items.append(f"{_format(k, level + 2)}: {_format(v, level + 2)}")
            base = f"{{{', '.join(items)}}}"
        else:
            try:
                attrs = getattr(value, "__dict__", {})
                if isinstance(attrs, dict):
                    items = []
                    for k, v in attrs.items():
                        items.append(f"{k}={_format(v, level + 2)}")
                    base = f"{value.__class__.__name__}(" + ", ".join(items) + ")"
                else:
                    base = repr(value)
            except Exception:
                base = f"<unrepresentable {type(value).__name__}>"

        if debug:
            return f"{base} ({type(value).__name__})"
        return base

    try:
        return _format(self, indent)
    except Exception as exc:
        return f"<Error in pretty(): {repr(exc)}>"

