    """Decorator function to add a new handler to the registry.

    Args:
        hook (HookType): Hook attribute for which to register the handler.
    Returns:
        callable: Decorator for registering listeners for the specified hook.
    """
    if hook is None:
        raise ValueError("hook cannot be None")

    def decorator(func):
        if not callable(func):
            raise TypeError(f"Listener {func!r} is not callable")

        try:
            listeners = self._listeners.setdefault(hook, [])
            listeners.append(func)
        except Exception as exc:
            raise RuntimeError(f"Failed to register listener for hook '{hook}': {exc}") from exc

        return func

    return decorator

