        self._handlers[hook] = []

    def decorator(func):
        """
        Inner decorator that registers the function `func` for the given hook.
        """
        if not callable(func):
            raise TypeError(f"Listener for hook {hook!r} must be callable, got {type(func).__name__}")

        try:
            self._handlers[hook].append(func)
        except Exception as exc:
            raise RuntimeError(
                f"Failed to register listener {func.__name__!r} to hook {hook!r}: {exc}"
            ) from exc

        return func

    return decorator

