def render(pieces, style):
    """Render the given version pieces into the requested style."""
    # Mapping of supported style names to separators
    _STYLE_MAP = {
        'semver': '.',
        'dot': '.',
        'point': '.',
        'hyphen': '-',
        'dash': '-',
        'minus': '-',
        'underscore': '_',
        'under': '_',
        'path': '/',
        'slash': '/',
        'space': ' ',
    }

    # Validate and normalize style
    if not isinstance(style, str):
        raise TypeError(f"style must be a string, got {type(style).__name__}")
    separator = _STYLE_MAP.get(style.lower())
    if separator is None:
        raise ValueError(f"Unsupported style '{style}'. Supported styles: {', '.join(sorted(_STYLE_MAP))}")

    # Convert pieces to a list; handle None or empty iterable
    try:
        # Accept any iterable
        piece_iter = iter(pieces)
    except TypeError as exc:
        raise TypeError(f"pieces must be an iterable, got {type(pieces).__name__}") from exc

    result_parts = []
    for elem in piece_iter:
        if elem is None:
            # Skip None elements quietly
            continue
        # Convert elements to string representation
        try:
            part_str = str(elem)
        except Exception as exc:
            raise TypeError(f"cannot convert element {elem!r} to string") from exc
        result_parts.append(part_str)

    if not result_parts:
        # If no valid parts, return empty string
        return ''

    return separator.join(result_parts)

