    if verbose:
        print(f"Running command: {cmd}")
        if cwd:
            print(f"  Working directory: {cwd}")
        if env:
            print(f"  Environment variables: {env}")

    # Merge provided environment with the current one
    env_final = os.environ.copy()
    if env:
        env_final.update(env)

    # Decide how to handle stderr
    stderr_arg = subprocess.STDOUT if hide_stderr else subprocess.PIPE

    try:
        result = subprocess.run(
            cmd,
            cwd=cwd,
            env=env_final,
            stdout=subprocess.PIPE,
            stderr=stderr_arg,
            text=True,
        )
    except FileNotFoundError as fnf_error:
        raise FileNotFoundError(f"Command {commands} not found") from fnf_error
