                if check_digests and is_valid:
                    try:
                        hasher = hashlib.sha256()
                        with open(full_path, 'rb') as f:
                            for chunk in iter(lambda: f.read(8192), b''):
                                hasher.update(chunk)
                        digest = hasher.hexdigest()
                        expected = expected_digests.get(full_path)
                        if expected and digest != expected:
                            is_valid = False
                            if show_warnings:
                                print(f"Warning: digest mismatch for '{full_path}'.")
                    except Exception as exc:
                        if show_warnings:
                            print(f"Warning: could not compute digest for '{full_path}': {exc}")
                        is_valid = False

                if is_valid:
                    good_objects += 1

        return (num_objects, good_objects)

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """
    Validate storage root hierarchy.

    Returns:
        num_objects (int): number of objects checked
        good_objects (int): number of objects checked that were found to be valid
    """
    # ---- Input validation -------------------------------------------------
    if not isinstance(validate_objects, bool):
        raise TypeError(f"validate_objects must be a bool, got {type(validate_objects)!r}")
    if not isinstance(check_digests, bool):
        raise TypeError(f"check_digests must be a bool, got {type(check_digests)!r}")
    if not isinstance(show_warnings, bool):
        raise TypeError(f"show_warnings must be a bool, got {type(show_warnings)!r}")

    # ---- Determine root path ----------------------------------------------
    root_path = getattr(self, "root_path", None)
    if root_path is None:
        raise AttributeError("The instance must have a 'root_path' attribute pointing to the storage root.")
    if not isinstance(root_path, str):
        raise TypeError(f"root_path must be a string, got {type(root_path)!r}")

    # ---- Setup counters ----------------------------------------------------
    num_objects = 0
    good_objects = 0

    # ---- Import modules locally to satisfy the no-import rule ----------
    # (Assumes that os and hashlib are available globally; otherwise, import
    # them in the surrounding module where this class is defined.)
    try:
        import os
        import hashlib
    except Exception as exc:
        raise RuntimeError("Required modules 'os' and 'hashlib' are not available.") from exc

    # ---- Helper functions -----------------------------------------------
    def _is_valid_object(file_path):
        """Perform basic validity check on a single file."""
        if not file_path or not isinstance(file_path, str):
            return False
        if not os.path.isfile(file_path):
            return False
        try:
            size = os.path.getsize(file_path)
            return size > 0  # non-empty file considered valid
        except OSError:
            return False

    def _digest_matches(file_path, digest_path):
        """Check if the SHA256 digest of file matches the stored digest."""
        try:
            with open(file_path, "rb") as fp:
                data = fp.read()
            actual_digest = hashlib.sha256(data).hexdigest()
            with open(digest_path, "r") as df:
                expected_digest = df.read().strip()
            return actual_digest == expected_digest
        except Exception:
            return False

    # ---- Walk through the directory hierarchy ----------------------------
    for dirpath, _, filenames in os.walk(root_path):
        for name in filenames:
            # Skip hidden files and digest files themselves
            if name.startswith(".") or name.lower().endswith(".digest"):
                continue
            file_path = os.path.join(dirpath, name)
            num_objects += 1
            is_valid = True

            # Object validation
            if validate_objects:
                if not _is_valid_object(file_path):
                    is_valid = False
                    if show_warnings:
                        print(f"Warning: File '{file_path}' failed validation check.")

            # Digest check
            if check_digests:
                digest_path = file_path + ".digest"
                if os.path.isfile(digest_path):
                    if not _digest_matches(file_path, digest_path):
                        is_valid = False
                        if show_warnings:
                            print(f"Warning: Digest mismatch for '{file_path}'.")
                else:
                    # If a digest is expected but missing, treat as invalid
                    is_valid = False
                    if show_warnings:
                        print(f"Warning: Missing digest file for '{file_path}'.")

            if is_valid:
                good_objects += 1

    return num_objects, good_objects

def next_version(version):
    """
    Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not isinstance(version, str):
        raise TypeError("version must be a string")
    if not version.isdigit():
        raise ValueError("version must be numeric")
    try:
        current = int(version)
    except Exception as exc:
        raise ValueError("invalid numeric value") from exc
    next_num = current + 1
    if version.startswith("0") and len(version) > 1:
        return str(next_num).zfill(len(version))
    return str(next_num)

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    # Basic validation
    if not isinstance(version, str):
        return None
    version = version.strip()
    if not version:
        return None

    try:
        parts = version.split(".")
        # If there's only one part handle it directly
        if len(parts) == 1:
            part = parts[0]
            if not part.isdigit():
                return None  # invalid numeric part
            width = len(part)
            new_num = int(part) + 1
            return str(new_num).zfill(width)
        else:
            # Increment the last component
            last = parts[-1]
            if not last.isdigit():
                return None
            width = len(last)
            new_last = str(int(last) + 1).zfill(width)
            parts[-1] = new_last
            return ".".join(parts)
    except Exception:
        return None

def validate_version_inventories(self, version_dirs):
    """
    Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    import os
    import json

    if not isinstance(version_dirs, (list, tuple)):
        raise ValueError("`version_dirs` must be a list or tuple of directory paths")

    # Ensure the root inventory exists; it should be a dict mapping path -> digest
    root_inventory = getattr(self, "root_inventory", {})
    if not isinstance(root_inventory, dict):
        raise AttributeError("Instance must have a 'root_inventory' attribute of type dict")

    differences = []

    for v_dir in version_dirs:
        if not isinstance(v_dir, str):
            raise ValueError(f"Directory name must be a string; got {type(v_dir).__name__}")
        if not os.path.isdir(v_dir):
            raise FileNotFoundError(f"Version directory does not exist: {v_dir}")

        # The inventory filename is assumed to be 'inventory.json' inside the version dir
        inventory_path = os.path.join(v_dir, "inventory.json")
        if not os.path.isfile(inventory_path):
            # Missing inventory is considered an error
            raise FileNotFoundError(f"Missing inventory file in {v_dir}")

        try:
            with open(inventory_path, "r", encoding="utf-8") as fh:
                try:
                    inv_content = json.load(fh)
                except json.JSONDecodeError:
                    # Fallback: assume a simple key:value per line format
                    inv_content = {}
                    fh.seek(0)
                    for line in fh:
                        line = line.strip()
                        if not line or ":" not in line:
                            continue
                        key, val = line.split(":", 1)
                        inv_content[key.strip()] = val.strip()
        except Exception as e:
            raise RuntimeError(f"Error reading inventory from {inventory_path}") from e

        if not isinstance(inv_content, dict):
            raise TypeError(f"Inventory in {inventory_path} did not resolve to a dictionary")

        for file_path, version_digest in inv_content.items():
            root_digest = root_inventory.get(file_path)
            if root_digest is None:
                # If the file is not present in the root inventory, ignore it
                continue
            if root_digest != version_digest:
                differences.append({
                    "version": v_dir,
                    "file_path": file_path,
                    "root_digest": root_digest,
                    "version_digest": version_digest
                })

    # Keep a record of differences for later use
    setattr(self, "different_digests", differences)

    return differences

def validate_version_inventories(self, version_dirs):
        """
        Each version SHOULD have an inventory up to that point.

        Also keep a record of any content digests different from those in the root inventory
        so that we can also check them when validating the content.

        version_dirs is an array of version directory names and is assumed to be in
        version sequence (1, 2, 3...).
        """
        # Import modules locally to avoid global dependencies
        import os
        import json

        # Basic input validation
        if not isinstance(version_dirs, (list, tuple)):
            raise TypeError("version_dirs must be a list or tuple of directory paths")
        for path in version_dirs:
            if not isinstance(path, str):
                raise TypeError(f"Each element in version_dirs must be a string path, got {type(path)}")

        # Ensure we have a root inventory to compare against
        if not hasattr(self, "root_inventory") or not isinstance(self.root_inventory, dict):
            raise AttributeError("Instance must have a 'root_inventory' attribute of type dict")

        # Container for differences found per version
        differences = {}

        # Name of the inventory file expected inside each version directory
        inventory_filename = getattr(self, "inventory_filename", "inventory.json")

        for ver_dir in version_dirs:
            ver_inventories = {}
            inventory_path = os.path.join(ver_dir, inventory_filename)
            try:
                with open(inventory_path, "r", encoding="utf-8") as f:
                    try:
                        ver_inventories = json.load(f)
                        if not isinstance(ver_inventories, dict):
                            raise ValueError(f"Inventory file {inventory_path} does not contain a JSON object")
                    except json.JSONDecodeError as e:
                        raise ValueError(f"Failed to parse JSON inventory {inventory_path}: {e}") from e
            except FileNotFoundError:
                raise FileNotFoundError(f"Inventory file not found in version directory: {inventory_path}")

            # Compare this version's inventory against the root inventory
            ver_diff = []
            for key, ver_digest in ver_inventories.items():
                root_digest = self.root_inventory.get(key)
                if root_digest is None:
                    # Key present in version but not in root inventory; treat as difference
                    ver_diff.append((key, None, ver_digest))
                elif root_digest != ver_digest:
                    ver_diff.append((key, root_digest, ver_digest))

            # Also check for keys present in root but missing in this version's inventory
            for key in self.root_inventory:
                if key not in ver_inventories:
                    ver_diff.append((key, self.root_inventory[key], None))

            # Store differences if any
            if ver_diff:
                differences[ver_dir] = ver_diff

        # Store recorded differences on the instance for later use
        setattr(self, "inventory_differences", differences)

        # Return the differences for caller inspection
        return differences, len(differences) == 0

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    # Import os only when the function is called
    try:
        import os
    except Exception as e:
        return f"cannot import os module: {e}"

    # Validate input
    if not isinstance(path, str):
        return "invalid path: expected string"

    # Resolve to an absolute path for consistency
    try:
        abs_path = os.path.abspath(path)
    except Exception as e:
        return f"invalid path: {e}"

    # Check existence
    if not os.path.exists(abs_path):
        return "path does not exist"

    # If it's a file, return 'file'
    if os.path.isfile(abs_path):
        return "file"

    # If it's a directory, inspect its contents
    if os.path.isdir(abs_path):
        try:
            entries = os.listdir(abs_path)
        except Exception as e:
            return f"cannot list directory contents: {e}"

        # Find Namaste files that start with '0='
        namaste_files = [
            name for name in entries
            if name.startswith("0=") and os.path.isfile(os.path.join(abs_path, name))
        ]

        if namaste_files:
            return "object"

        # No Namaste files: might be a root. Check for typical root marker
        if "objects" in entries:
            objects_path = os.path.join(abs_path, "objects")
            if os.path.isdir(objects_path):
                return "root"

        # If none of the above, it's not an OCFL root or object
        return "not an OCFL root or object"

    # Default fallback (unlikely)
    return "unknown path type"

def find_path_type(path):
    """
    Return a string indicating the type of thing at the given path.

    Return values:
        'root'   - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file'   - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    try:
        import os
    except Exception as e:
        return f"Unable to import modules: {e}"

    if not path:
        return "Path is empty"

    try:
        if not os.path.exists(path):
            return "Path does not exist"

        if os.path.isfile(path):
            return "file"

        if not os.path.isdir(path):
            return f"Path is not a file or directory (type {type(path).__name__})"

        # Path is a directory
        try:
            entries = os.listdir(path)
        except Exception as e:
            return f"Error listing directory: {e}"

        # Find files starting with '0='
        namaste_files = [
            f for f in entries
            if f.startswith("0=") and os.path.isfile(os.path.join(path, f))
        ]

        if not namaste_files:
            return "No Namaste file found"

        # Use the first Namaste file found
        namaste_path = os.path.join(path, namaste_files[0])
        try:
            with open(namaste_path, "r", errors="ignore") as fh:
                content = fh.read()
        except Exception as e:
            return f"Error reading Namaste file: {e}"

        if "OCFL Storage Root" in content:
            return "root"
        if "OCFL Object" in content:
            return "object"

        return "Unknown Namaste file content"
    except Exception as ex:
        return f"Unhandled exception: {ex}"

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    # We keep the import inside the function to avoid adding module-level imports
    try:
        import os
    except Exception as e:
        return f"import error: {e}"

    # Resolve to an absolute path to avoid odd relative behaviours
    try:
        abs_path = os.path.abspath(path)
    except Exception as e:
        return f"path resolution error: {e}"

    # If it doesn't exist
    if not os.path.exists(abs_path):
        return "path does not exist"

    # If it's a file
    if os.path.isfile(abs_path):
        return "file"

    # If it's a directory, look for the namaste file
    if os.path.isdir(abs_path):
        namaste_path = os.path.join(abs_path, "0=namaste")
        if not os.path.isfile(namaste_path):
            return "not a recognized OCFL directory"

        try:
            with open(namaste_path, "r", encoding="utf-8") as f:
                first_line = f.readline().strip()
        except Exception as e:
            return f"namaste read error: {e}"

        # The file may have a prefix like "ocfl_root,..." or "ocfl_object,..."
        # We consider the part before the first comma or whitespace
        if not first_line:
            return "empty namaste file"
        key = first_line.split()[0].split(",")[0].lower()

        if key == "ocfl_root":
            return "root"
        elif key == "ocfl_object":
            return "object"
        else:
            return f"unknown namaste type: {first_line}"

    # Should not reach here, but catch any unexpected case
    return "unknown path type"

def find_path_type(path):
    # Dynamically import os within the function to avoid top‑level import
    os = __import__('os')

    try:
        # Check if the path exists
        if not os.path.exists(path):
            return f'path does not exist: {path!r}'

        # If it's a regular file, just return 'file'
        if os.path.isfile(path):
            return 'file'

        # Ensure we're dealing with a directory
        if not os.path.isdir(path):
            return f'path is not a file or directory: {path!r}'

        # List entries in the directory
        entries = os.listdir(path)

        # If any entry starts with '0=' it's a Namaste file => object directory
        for entry in entries:
            if entry.startswith('0='):
                # Only files matter, not subdirectories named like '0=...'
                full_entry = os.path.join(path, entry)
                if os.path.isfile(full_entry):
                    return 'object'

        # If we didn't see a Namaste file, treat as container root
        return 'root'

    except OSError as exc:
        # Capture OS level errors (missing permissions, etc.)
        return f'ocfl path type detect error: {exc}'

def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""
    # Ensure params is a dictionary
    if params is None:
        params = {}
    elif not isinstance(params, dict):
        raise TypeError(f"params must be a dict, got {type(params).__name__}")

    # Build a comma‑separated string of IDs
    try:
        if isinstance(bug_ids, (list, tuple, set)):
            if not bug_ids:
                raise ValueError("bug_ids iterable is empty")
            cleaned = []
            for bid in bug_ids:
                if isinstance(bid, (int, str)):
                    cleaned.append(str(bid))
                else:
                    raise TypeError(f"bug_ids element must be int or str, got {type(bid).__name__}")
            if not all(cleaned):
                raise ValueError("bug_ids contains empty values")
            bug_ids_str = ",".join(cleaned)
        elif isinstance(bug_ids, int):
            bug_ids_str = str(bug_ids)
        elif isinstance(bug_ids, str):
            bug_ids_str = bug_ids.strip()
            if not bug_ids_str:
                raise ValueError("bug_ids string is empty")
        else:
            raise TypeError(f"bug_ids must be an int, str, or iterable, got {type(bug_ids).__name__}")

        # Add/override the 'ids' key in params
        params['ids'] = bug_ids_str

    except Exception as exc:
        raise ValueError(f"Failed to amend Bugzilla params: {exc}") from exc

    return params

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''
    if not isinstance(nodes, list):
        return []

    def merge_mapping_nodes(map1, map2):
        """Assumes both arguments are MappingNode instances."""
        tag = map1.tag if hasattr(map1, 'tag') else getattr(map1, 'tag', None)
        # Build a dict for existing mappings from map1
        merged_pairs = []
        key_to_index = {}
        for idx, (k, v) in enumerate(map1.value):
            key_to_index[k.value] = idx
            merged_pairs.append((k, v))
        # Merge map2
        for k2, v2 in map2.value:
            key = k2.value
            if key in key_to_index:
                idx = key_to_index[key]
                v1 = merged_pairs[idx][1]
                # If both values are MappingNode, merge recursively
                if hasattr(v1, 'tag') and v1.tag == 'tag:yaml.org,2002:map' and hasattr(v2, 'tag') and v2.tag == 'tag:yaml.org,2002:map':
                    merged_pairs[idx] = (k2, merge_mapping_nodes(v1, v2))
                else:
                    merged_pairs[idx] = (k2, v2)  # last wins
            else:
                merged_pairs.append((k2, v2))
                key_to_index[key] = len(merged_pairs) - 1
        return type(map1)(tag=tag, value=merged_pairs)

    result = []
    seen_keys = {}
    for item in nodes:
        try:
            key_node, value_node = item
            key_val = getattr(key_node, 'value', None)
        except Exception:
            continue
        if key_val in seen_keys:
            # Merge with existing
            existing_key_node, existing_value_node = seen_keys[key_val]
            # Both mappings
            if hasattr(existing_value_node, 'tag') and existing_value_node.tag == 'tag:yaml.org,2002:map' and hasattr(value_node, 'tag') and value_node.tag == 'tag:yaml.org,2002:map':
                merged_node = merge_mapping_nodes(existing_value_node, value_node)
                seen_keys[key_val] = (existing_key_node, merged_node)
            else:
                # Replace with last
                seen_keys[key_val] = (existing_key_node, value_node)
        else:
            seen_keys[key_val] = (key_node, value_node)
            result.append((key_node, value_node))
    # Reconstruct result from seen_keys in order of insertion
    ordered_result = []
    for key in seen_keys:
        if key in seen_keys:
            ordered_result.append(seen_keys[key])
    return ordered_result

def deep_merge_nodes(nodes):
    """
    Deep merge a list of (ScalarNode, value) tuples that may contain duplicate keys.
    Duplicate keys are merged recursively if the values are MappingNodes;
    otherwise the last value wins.  The relative order of first occurrences
    of keys is preserved.

    Parameters
    ----------
    nodes : list of tuples
        Each tuple contains a ScalarNode key and a value node (MappingNode or other).

    Returns
    -------
    list of tuples
        The merged list of (ScalarNode, node) tuples.
    """
    # Helper to detect MappingNode without importing ruamel.yaml
    def _is_mapping_node(n):
        return (
            hasattr(n, "value")
            and isinstance(n.value, list)
            and isinstance(n.tag, str)
            and n.tag.startswith("tag:yaml.org,2002:map")
        )

    # Merge two MappingNode values (recursively)
    def _merge_mapping_nodes(n1, n2):
        # Build dict of existing entries from n1
        dict1 = {k.value: v for k, v in n1.value}
        # Merge entries from n2
        for k, v in n2.value:
            key = k.value
            if key in dict1:
                merged = _merge_nodes(dict1[key], v)
                dict1[key] = merged
            else:
                dict1[key] = v

        # Preserve order: start with n1's order, then add new keys from n2
        merged_list = []
        seen_keys = set()
        for k, _ in n1.value:
            key = k.value
            if key in dict1:
                # re-add after merging
                merged_list.append((k, dict1[key]))
                seen_keys.add(key)
        for k, _ in n2.value:
            key = k.value
            if key not in seen_keys:
                merged_list.append((k, dict1[key]))
                seen_keys.add(key)

        return type(n1)(tag=n1.tag, value=merged_list)

    # Merge two generic nodes
    def _merge_nodes(n1, n2):
        if _is_mapping_node(n1) and _is_mapping_node(n2):
            return _merge_mapping_nodes(n1, n2)
        else:
            # For non-mapping nodes, last one wins
            return n2

    # Main merging logic
    key_to_node = {}
    for key_node, value_node in nodes:
        key = key_node.value
        if key in key_to_node:
            key_to_node[key] = _merge_nodes(key_to_node[key], value_node)
        else:
            key_to_node[key] = value_node

    # Reconstruct list preserving first-encounter order
    merged = []
    seen = set()
    for key_node, _ in nodes:
        key = key_node.value
        if key not in seen:
            merged.append((key_node, key_to_node[key]))
            seen.add(key)

    return merged

def deep_merge_nodes(nodes):
    '''
