                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''
    try:
        def is_mapping(node):
            return getattr(node, 'tag', '').startswith('tag:yaml.org,2002:map')

        def merge_mapping(map1, map2):
            """
            Deep merge two MappingNode instances. Returns a new MappingNode with merged values.
            """
            # Create a mapping from subkey string to (key_node, value_node) for map1
            merged = {}
            for key_node, val_node in getattr(map1, 'value', []):
                merged[str(key_node.value)] = (key_node, val_node)
            # Merge map2 into merged
            for key_node, val_node in getattr(map2, 'value', []):
                key = str(key_node.value)
                if key in merged:
                    existing_key_node, existing_val_node = merged[key]
                    # If both are mappings, merge recursively
                    if is_mapping(existing_val_node) and is_mapping(val_node):
                        merged_val_node = merge_mapping(existing_val_node, val_node)
                        merged[key] = (existing_key_node, merged_val_node)
                    else:
                        # Last one wins; keep original key node
                        merged[key] = (existing_key_node, val_node)
                else:
                    merged[key] = (key_node, val_node)
            # Build new MappingNode
            merged_list = list(merged.values())
            # Preserve tag from first mapping node
            new_mapping = type(map1)(tag=map1.tag, value=merged_list)
            return new_mapping

        result_dict = {}
        for key_node, val_node in nodes:
            key = str(key_node.value)
            if key in result_dict:
                # Duplicate key found
                existing_key_node, existing_val_node = result_dict[key]
                if is_mapping(existing_val_node) and is_mapping(val_node):
                    merged_val_node = merge_mapping(existing_val_node, val_node)
                    result_dict[key] = (existing_key_node, merged_val_node)
                else:
                    # Last one wins, but keep original key node
                    result_dict[key] = (existing_key_node, val_node)
            else:
                result_dict[key] = (key_node, val_node)

        return list(result_dict.values())
    except Exception as exc:
        raise ValueError('Failed to deep merge nodes') from exc

