def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""
    # Validate inputs
    if url is None:
        return None
    if not isinstance(url, str):
        raise TypeError("url must be a string")
    if url_args is None:
        url_args = {}
    if not isinstance(url_args, dict):
        raise TypeError("url_args must be a dictionary")

    # Replace placeholders of the form {key}
    for key, value in url_args.items():
        placeholder = f"{{{key}}}"
        url = url.replace(placeholder, str(value))

    # Detect any placeholders that were not replaced
    if "{" in url and "}" in url:
        pos = 0
        missing_placeholders = []
        while True:
            start = url.find('{', pos)
            if start == -1:
                break
            end = url.find('}', start + 1)
            if end == -1:
                break
            placeholder = url[start + 1:end]
            if placeholder not in url_args:
                missing_placeholders.append(placeholder)
            pos = end + 1
        if missing_placeholders:
            missing_str = ", ".join(missing_placeholders)
            raise KeyError(f"Missing values for placeholders: {missing_str}")

    return url

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""
    try:
        if not isinstance(url, str):
            return url
        if not url_args:
            return url

        # Prepare replacement values
        if isinstance(url_args, dict):
            items = url_args.items()
        else:
            # Assume iterable of (key, value) pairs
            items = enumerate(url_args)

        from urllib.parse import quote

        for key, value in items:
            # Support multiple placeholder syntaxes
            placeholders = (f"{{{key}}}", f":{key}", f"<{key}>")
            rep = quote(str(value))
            for ph in placeholders:
                url = url.replace(ph, rep)

        return url
    except Exception:
        # In case of any error, fall back to original URL
        return url

