    if not isinstance(url_args, dict):
        raise TypeError(f"url_args must be a dict, got {type(url_args).__name__}")

    # Prepare a mapping where missing keys return the original placeholder
    class SafeMap(dict):
        def __missing__(self, key):  # pragma: no cover
            return '{' + key + '}'

    # Convert all values to strings for safe formatting
    safe_args = SafeMap({str(k): str(v) for k, v in url_args.items()})

    try:
        return url.format_map(safe_args)
