def was_processed(processed, path_name, verbose):
    """
    Check if a file or directory has already been processed.

    To prevent recursion, expand the path name to an absolute path
    call this function with a set that will store all the entries and
    the entry to test. If the entry is already in the set, report the issue
    and return ``True``. Otherwise, add the entry to the set and return
    ``False`` to allow the path to be processed.

    Args:
        processed: Set to store processed pathnames
        path_name: Path to a directory or file
        verbose: True if verbose output is requested

    Returns:
        True if it's already in the set. False if not.
    """
    # Ensure required modules are available
    try:
        import os
    except Exception as e:
        if verbose:
            print(f"Error importing os module: {e}")
        return True  # Conservative choice to avoid further processing

    # Validate 'processed' is a set
    if not isinstance(processed, set):
        if verbose:
            print(f"Invalid 'processed' type: expected set, got {type(processed).__name__}")
        return True

    # Guard against None or empty path_name
    if not path_name:
        if verbose:
            print("Empty or None path_name provided; treating as processed.")
        return True

    # Resolve path to an absolute path
    try:
        abs_path = os.path.abspath(str(path_name))
    except Exception as e:
        if verbose:
            print(f"Error resolving absolute path for '{path_name}': {e}")
        return True

    # Check if the absolute path has already been processed
    if abs_path in processed:
        if verbose:
            print(f"Already processed: {abs_path}")
        return True

    # Add the new path to the processed set
    try:
        processed.add(abs_path)
    except Exception as e:
        if verbose:
            print(f"Error adding '{abs_path}' to processed set: {e}")
        return True

    return False

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    # Basic input validation
    if not isinstance(number, int):
        raise TypeError(f"number must be an int, got {type(number).__name__}")
    if not isinstance(alphabet, list):
        raise TypeError(f"alphabet must be a list, got {type(alphabet).__name__}")
    if not alphabet:
        raise ValueError("alphabet cannot be empty")
    base = len(alphabet)
    if base <= 1:
        raise ValueError("alphabet must contain at least two symbols for base conversion")
    if number < 0:
        raise ValueError("number must be non-negative")
    if padding is not None:
        if not isinstance(padding, int):
            raise TypeError(f"padding must be an int, got {type(padding).__name__}")
        if padding < 0:
            raise ValueError("padding must be non-negative")

    # Convert number to base represented by alphabet
    digits: List[str] = []
    if number == 0:
        digits.append(alphabet[0])
    else:
        while number > 0:
            number, rem = divmod(number, base)
            digits.append(alphabet[rem])

    # Most significant digit first
    result = ''.join(reversed(digits))

    # Apply padding if requested
    if padding is not None and len(result) < padding:
        result = alphabet[0] * (padding - len(result)) + result

    return result

