    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    # Basic type validation
    if not isinstance(string, str):
        raise TypeError(f"Expected string for input, got {type(string).__name__}")
    if not isinstance(alphabet, list):
        raise TypeError(f"Expected list for alphabet, got {type(alphabet).__name__}")

    base = len(alphabet)
    if base == 0:
        raise ValueError("Alphabet must contain at least one character")

    # Ensure alphabet contains unique characters
    if len(set(alphabet)) != base:
        raise ValueError("Alphabet contains duplicate characters")

    # Create a mapping from character to its value
    try:
        value_map = {char: idx for idx, char in enumerate(alphabet)}
    except Exception as exc:
        raise ValueError(f"Failed to build character mapping: {exc}") from exc

    result = 0
    for pos, ch in enumerate(string):
        if ch not in value_map:
            raise ValueError(f"Character '{ch}' at position {pos} not found in alphabet")
        result = result * base + value_map[ch]

    return result

