    Args:
        url: url of the .tar.gz archive to download
        destination_path: the path on disk where to extract archive

    Returns:
        a directory Path where the archive has been extracted to.
    """
    # Ensure the destination_path is a Path instance
    if not isinstance(destination_path, Path):
        raise TypeError("destination_path must be a pathlib.Path instance")

    # Create a temporary file name for the downloaded archive
    tmp_archive = destination_path / "repo_archive.tmp.tar.gz"

    # Download the archive
    try:
        response = requests.get(url, stream=True, timeout=30)
        response.raise_for_status()
    except requests.RequestException as exc:
        raise RuntimeError(f"Could not download archive from {url!r}: {exc}") from exc

    try:
        with open(tmp_archive, "wb") as f:
            for chunk in response.iter_content(chunk_size=1024 * 1024):
                if chunk:
                    f.write(chunk)
    except OSError as exc:
        raise RuntimeError(f"Error writing archive to disk: {exc}") from exc

    # Extract the archive
    try:
        import tarfile
        # Ensure destination directory exists
        if destination_path.exists():
            # Clean up any existing contents to avoid stale files
            for child in destination_path.iterdir():
                if child.is_dir():
                    import shutil
                    shutil.rmtree(child)
                else:
                    child.unlink()
        destination_path.mkdir(parents=True, exist_ok=True)

        with tarfile.open(tmp_archive, mode="r:gz") as tar:
            tar.extractall(path=destination_path)
    except (tarfile.TarError, OSError) as exc:
        raise RuntimeError(f"Failed to extract archive {tmp_archive!r}: {exc}") from exc
    finally:
        # Clean up temporary file
        try:
            if tmp_archive.exists():
