            pass  # ignore cleanup failures

    return destination_path

def os_is_mac():
    """
    Checks if the os is macOS

    :return: True is macOS
    :rtype: bool
    """
    try:
        # On Unix-like systems, os.uname() should provide system name.
        return os.uname().sysname == 'Darwin'
    except AttributeError:
        # os.uname() not available (e.g., on Windows). Use sys.platform instead.
        try:
            import sys
            return sys.platform == 'darwin'
        except Exception:
            # If any unexpected exception occurs, fall back to False.
            return False
    except Exception:
        # In case of any other unexpected errors, return False.
        return False

def os_is_mac():
    """
    Checks if the os is macOS

    :return: True is macOS
    :rtype: bool
    """
    try:
        # On POSIX systems, os.uname() provides the system name
        if hasattr(os, "uname"):
            return os.uname().sysname == "Darwin"
    except Exception:
        pass

    try:
        # Some environments set OSTYPE to 'darwin*' on macOS
        return os.environ.get("OSTYPE", "").startswith("darwin")
    except Exception:
        pass

    # If all checks fail, assume it's not macOS
    return False

