    try:
        import os, sys, shlex
    except Exception as exc:
        raise RuntimeError(f"Failed to import required modules: {exc}") from exc

    if platform == 'this':
        platform = 1 if os.name == 'posix' else 0
    else:
        # Accept integer 0 or 1 or explicit string 'posix'/'windows'
        if isinstance(platform, str):
            if platform.lower() in ('posix', 'posix1'):
                platform = 1
            elif platform.lower() in ('windows', 'cmd'):
                platform = 0
            else:
                raise ValueError(f"Unsupported platform string: {platform!r}")
        elif isinstance(platform, int):
            if platform not in (0, 1):
                raise ValueError(f"Unsupported platform integer: {platform}")
        else:
            raise TypeError(f"Platform must be 'this', 0, 1 or a compatible str, got {type(platform).__name__}")

    # Empty string should return empty list
    if not s.strip():
        return []

    if platform == 1:  # POSIX
        try:
            return shlex.split(s, posix=True)
        except ValueError as e:
            raise ValueError(f"POSIX split failed: {e}") from e

