    # It captures either quoted groups or unquoted tokens.
    win_re = r'''(?:(?:"((?:[^"\\]|\\.)*)")|([^ \t\r\n]+))'''
    try:
        tokens = re.findall(win_re, s)
    except re.error as e:
        raise ValueError(f"Regex error during Windows split: {e}") from e

    args = []
    for quoted, unquoted in tokens:
        if quoted:
            # Process escape sequences inside quotes
            token = re.sub(r'\\(.)', r'\1', quoted)
        else:
            token = unquoted
        # Handle escaped spaces outside quotes
        if token.startswith('"') and token.endswith('"'):
            token = token[1:-1]
        token = re.sub(r'\\(.)', r'\1', token)
        args.append(token)

    return args

