def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    import os
    from pathlib import Path
    import datetime
    import subprocess

    try:
        archive = Path(archive_path).expanduser().resolve()
        if not archive.is_file():
            raise FileNotFoundError(f"Archive not found: {archive}")
    except Exception as exc:
        raise ValueError(f"Invalid archive_path '{archive_path}': {exc}") from exc

    try:
        target_dir_name = filename if filename else archive.stem
        tmp_dir = Path(tmp_path).expanduser().resolve()
        tmp_dir.mkdir(parents=True, exist_ok=True)
        dest_dir = tmp_dir / target_dir_name

        # Ensure unique destination if it already exists
        if dest_dir.exists():
            suffix = datetime.datetime.now().strftime("%Y%m%d%H%M%S")
            dest_dir = tmp_dir / f"{target_dir_name}_{suffix}"

        dest_dir.mkdir(parents=True, exist_ok=True)
    except Exception as exc:
        raise ValueError(f"Could not prepare extraction directory: {exc}") from exc

    try:
        suffixes = tuple(archive.suffixes)
        # Determine extraction command based on archive type
        if archive.suffix == ".zip":
            cmd = ["unzip", "-q", str(archive), "-d", str(dest_dir)]
        elif archive.suffix in {".tar", ".gz", ".bz2", ".xz"} or ".tar" in suffixes:
            # Handle .tar.* and .tar
            if archive.suffix in {".gz", ".bz2", ".xz"} or ".tar" in suffixes:
                # Determine appropriate compress option
                if ".tar.gz" in str(archive):
                    cmd = ["tar", "-xzf", str(archive), "-C", str(dest_dir)]
                elif ".tar.bz2" in str(archive):
                    cmd = ["tar", "-xjf", str(archive), "-C", str(dest_dir)]
                elif ".tar.xz" in str(archive):
                    cmd = ["tar", "-xJf", str(archive), "-C", str(dest_dir)]
                else:
                    cmd = ["tar", "-xf", str(archive), "-C", str(dest_dir)]
            else:
                # Just a plain .tar
                cmd = ["tar", "-xf", str(archive), "-C", str(dest_dir)]
        else:
            raise ValueError(f"Unsupported archive format: {archive}")

        # Execute extraction
        result = subprocess.run(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
        if result.returncode != 0:
            raise RuntimeError(
                f"Extraction failed: {result.stderr}".strip()
            )
    except Exception as exc:
        raise RuntimeError(f"Failed to extract archive '{archive}': {exc}") from exc

    repo_url = f"file://{dest_dir.resolve()}"
    return repo_url

def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """
    Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.
    This does not deal with the case where the archive passed along does not exist.
    """
    import os
    import pathlib
    import shutil
    import subprocess
    import tempfile

    # Resolve paths
    try:
        tmp_dir = pathlib.Path(tmp_path).expanduser().resolve()
    except Exception as exc:
        raise ValueError(f"Invalid tmp_path {tmp_path!r}: {exc}") from exc

    # Create a temporary extraction directory inside tmp_path
    try:
        extract_dir = tempfile.mkdtemp(dir=str(tmp_dir))
    except Exception as exc:
        raise OSError(f"Failed to create temporary extraction directory in {tmp_dir}: {exc}") from exc

    archive_file = pathlib.Path(archive_path).expanduser().resolve()
    if not archive_file.is_file():
        raise FileNotFoundError(f"Archive file not found: {archive_file}")

    # Determine archive type and extract
    try:
        if archive_file.suffix in {".zip"}:
            cmd = ["unzip", "-q", str(archive_file), "-d", extract_dir]
        elif archive_file.suffix in {".tar"}:
            cmd = ["tar", "-xf", str(archive_file), "-C", extract_dir]
        elif archive_file.suffix in {".gz", ".x"} or archive_file.suffix in {".tgz", ".tar.gz", ".tar.xz"}:
            # For .tar.gz/.tgz or .tar.xz
            cmd = ["tar", "-xf", str(archive_file), "-C", extract_dir]
        else:
            # Try helper with 'tar' generic
            cmd = ["tar", "-xf", str(archive_file), "-C", extract_dir]
        subprocess.run(cmd, check=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    except subprocess.SubprocessError as exc:
        # Clean up extracted dir
        shutil.rmtree(extract_dir, ignore_errors=True)
        raise RuntimeError(f"Extraction failed for {archive_file}: {exc}") from exc

    # Identify repository root
    repo_root = None
    if filename:
        candidate = pathlib.Path(extract_dir) / filename
        if candidate.exists():
            repo_root = candidate
        else:
            raise FileNotFoundError(f"Specified filename {filename!r} not found in archive.")
    else:
        # Prefer a single top-level directory, else use extract_dir directly
        entries = [p for p in pathlib.Path(extract_dir).iterdir() if p.is_dir()]
        if len(entries) == 1:
            repo_root = entries[0]
        else:
            repo_root = pathlib.Path(extract_dir)

    repo_url = repo_root.absolute().as_uri()
    return repo_url

def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    if frequency is None or str(frequency).strip().lower() == 'always':
        return None

    freq_str = str(frequency).strip().lower()
    import re
    match = re.fullmatch(r'(?P<value>\d+(?:\.\d+)?)\s*(?P<unit>\w+)', freq_str)
    if not match:
        raise ValueError(f"Frequency '{frequency}' is not in a valid format")

    try:
        value = float(match.group('value'))
    except ValueError:
        raise ValueError(f"Could not convert value part '{match.group('value')}' to float")

    unit = match.group('unit')
    # Mapping of unit synonyms to timedelta keyword arguments
    unit_map = {
        'day': 'days', 'days': 'days',
        'week': 'weeks', 'weeks': 'weeks',
        'hour': 'hours', 'hours': 'hours',
        'minute': 'minutes', 'minutes': 'minutes',
        'second': 'seconds', 'seconds': 'seconds',
    }
    if unit not in unit_map:
        raise ValueError(f"Unit '{unit}' is not recognized in frequency '{frequency}'")

    kwargs = {unit_map[unit]: value}
    return datetime.timedelta(**kwargs)

def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    # Handle null-like values
    if frequency is None:
        return None

    # Ensure we are dealing with a string
    try:
        freq_str = str(frequency).strip()
    except Exception as exc:
        raise ValueError(f"Invalid frequency type: {type(frequency).__name__}") from exc

    # Return None for the special 'always' keyword (case‑insensitive)
    if not freq_str or freq_str.lower() == 'always':
        return None

    parts = freq_str.split()
    if len(parts) != 2:
        raise ValueError(f"Frequency must consist of a number and a unit: '{frequency}'")

    number_str, unit_str = parts
    try:
        number = int(number_str)
    except ValueError:
        raise ValueError(f"Invalid numeric value in frequency: '{number_str}'")

    # Mapping of accepted unit aliases to timedelta keyword arguments
    unit_map = {
        'days': ['day', 'days'],
        'weeks': ['week', 'weeks'],
        'hours': ['hour', 'hours'],
        'minutes': ['minute', 'minutes'],
        'seconds': ['second', 'seconds'],
    }

    kwarg_name = None
    unit_lower = unit_str.lower()
    for kw_name, aliases in unit_map.items():
        if unit_lower in aliases:
            kwarg_name = kw_name
            break

    if kwarg_name is None:
        raise ValueError(f"Unsupported time unit in frequency: '{unit_str}'")

    kwargs = {kwarg_name: number}
    return datetime.timedelta(**kwargs)

