            packed = socket.inet_pton(socket.AF_INET6, ip_str)
            # ::1 is the only IPv6 loopback; no other addresses are loopback
            return packed == b'\x00'*15 + b'\x01'
        except OSError:
            pass
        return False

    # Check if the supplied value is a direct IP address
    if _is_loopback_ip(h):
        return True

    # Resolve the host to addresses and check each for loopback
    try:
        addr_info = socket.getaddrinfo(h, None, socket.AF_UNSPEC, socket.SOCK_STREAM)
    except socket.gaierror:
        return False
    for family, _, _, _, sockaddr in addr_info:
        try:
            if family == socket.AF_INET:
                ip = sockaddr[0]
                if ip.startswith("127."):
                    return True
            elif family == socket.AF_INET6:
                ip = sockaddr[0]
                if ip == "::1":
                    return True
        except Exception:
