def make_find_paths(find_paths):
    '''
    Given a sequence of path fragments or patterns as passed to `--find`, transform all path
    fragments into glob patterns. Pass through existing patterns untouched.

    For example, given find_paths of:

      ['foo.txt', 'pp:root/somedir']

    ... transform that into:

      ['sh:**/*foo.txt*/**', 'pp:root/somedir']
    '''
    if find_paths is None:
        return None
    try:
        iterator = iter(find_paths)
    except TypeError as exc:
        raise TypeError("find_paths must be an iterable") from exc

    result = []
    for path in iterator:
        try:
            s = str(path)
        except Exception as exc:
            raise ValueError(f"Unable to convert path {path!r} to string: {exc}") from exc

        # If the path already contains a scheme (e.g., 'pp:...' or 'sh:...'), treat it as a full pattern
        if ':' in s:
            result.append(s)
        else:
            # Wrap plain fragments into a glob pattern that matches anywhere under the 'sh' hierarchy
            # Example: 'foo.txt' -> 'sh:**/*foo.txt*/**'
            result.append(f'sh:**/*{s}*/**')
    return result

