def write_configuration(config_filename, rendered_config, mode=0o600, overwrite=False):
    """
    Given a target config filename and rendered config YAML, write it out to file.
    Create any containing directories as needed. But if the file already exists and
    overwrite is False, abort before writing anything.
    """
    # Validate input types
    if not isinstance(config_filename, str):
        raise TypeError("config_filename must be a string")
    if not isinstance(mode, int):
        raise TypeError("mode must be an integer")
    if not isinstance(overwrite, bool):
        raise TypeError("overwrite must be a boolean")

    # Convert rendered_config to a string if possible
    if not isinstance(rendered_config, str):
        try:
            rendered_config = str(rendered_config)
        except Exception as e:
            raise ValueError("rendered_config cannot be converted to a string") from e

    # Resolve absolute path and ensure parent directory exists
    abs_path = os.path.abspath(config_filename)
    dir_path = os.path.dirname(abs_path)

    try:
        if dir_path and not os.path.exists(dir_path):
            os.makedirs(dir_path, exist_ok=True)
    except OSError as e:
        raise OSError(f"Failed to create directories for '{abs_path}': {e}") from e

    # Check for existing file
    if os.path.exists(abs_path) and not overwrite:
        raise FileExistsError(f"File '{abs_path}' already exists and overwrite is set to False")

    # Write the configuration file
    try:
        with open(abs_path, "w", encoding="utf-8") as fp:
            fp.write(rendered_config)
        # Set desired file mode explicitly
        os.chmod(abs_path, mode)
    except OSError as e:
        raise OSError(f"Failed to write configuration file '{abs_path}': {e}") from e

    # Return nothing (side-effect only)
    return None

