def _resolve_string(matcher):
    """Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    """
    # Sentinel for missing default
    _UNSET = object()

    # Process matcher input
    if isinstance(matcher, (tuple, list)):
        if len(matcher) == 0:
            raise ValueError("Matcher tuple/list must contain at least a variable name.")
        name = matcher[0]
        default = matcher[1] if len(matcher) > 1 else _UNSET
    else:
        name = matcher
        default = _UNSET

    # Validate name
    if not isinstance(name, str):
        raise TypeError(f"Variable name must be a string, got {type(name).__name__}")

    # Retrieve value from environment
    value = os.getenv(name)

    if value is None:
        if default is _UNSET:
            raise ValueError(f"Environment variable '{name}' not found and no default value provided.")
        return str(default)

    return value

def _resolve_string(matcher):
