def _resolve_string(matcher):
    '''
    Get the value from the environment given a matcher containing a name and an optional default value.
    The matcher is expected to be a string of the form "VAR" or "VAR:default".
    If the variable is not defined in the environment and no default value is provided, raise a KeyError.
    '''
    if matcher is None:
        raise TypeError('matcher must be a non-empty string')
    if not isinstance(matcher, str):
        raise TypeError('matcher must be a string')
    parts = matcher.split(':', 1)
    var_name = parts[0].strip()
    if not var_name:
        raise ValueError('environment variable name cannot be empty')
    default = parts[1] if len(parts) == 2 else None
    try:
        return os.environ[var_name]
    except KeyError:
        if default is not None:
            return default
        raise KeyError(f'Environment variable "{var_name}" is not defined and no default was provided') from None

def _resolve_string(matcher):
    """
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    """
    # Determine the matcher format: (name,) or (name, default)
    if isinstance(matcher, (list, tuple)):
        if len(matcher) == 1:
            name, default = matcher[0], None
        elif len(matcher) == 2:
            name, default = matcher
        else:
            raise ValueError("Matcher must contain one or two elements (name[, default])")
    else:
        raise TypeError("Matcher must be a list or tuple")

    if not isinstance(name, str):
        raise TypeError("Variable name must be a string")

    try:
        value = os.getenv(name)
    except Exception as e:
        # In case environment access fails for some reason
        raise RuntimeError(f"Failed to read environment variable '{name}': {e}") from e

    if value is None:
        if default is not None:
            return default
        raise KeyError(f"Environment variable '{name}' is not set and no default value provided")
    return value

def _parse_image_ref(image_href: str) -> Tuple[str, str, bool]:
    """
    Parse an image href into composite parts.

    :param image_href: href of an image
    :returns: a tuple of the form (image_id, netloc, use_ssl)
    :raises ValueError: if the input cannot be parsed as a valid image reference.
    """
    if not isinstance(image_href, str):
        raise ValueError("image_href must be a string")

    try:
        parsed = urllib.parse.urlparse(image_href)
    except Exception as exc:
        raise ValueError(f"Invalid URL '{image_href}': {exc}") from exc

    if parsed.scheme not in ("http", "https"):
        raise ValueError(f"Unsupported scheme '{parsed.scheme}' in URL '{image_href}'")

    if not parsed.netloc:
        raise ValueError(f"Missing netloc in URL '{image_href}'")

    if not parsed.path or parsed.path == "/":
        raise ValueError(f"Missing image_id component in URL '{image_href}'")

    # Normalize image_id by stripping leading slashes and any trailing slashes
    image_id = parsed.path.lstrip("/").rstrip("/")
    if not image_id:
        raise ValueError(f"Empty image_id derived from URL '{image_href}'")

    use_ssl = parsed.scheme == "https"
    return image_id, parsed.netloc, use_ssl

