def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    try:
        # Normalize the command and arguments
        if isinstance(commands, (list, tuple)):
            cmd = list(commands)
            if args:
                if not isinstance(args, (list, tuple)):
                    raise ValueError("args must be a sequence of strings")
                cmd.extend(list(args))
        else:
            if not isinstance(commands, str):
                raise ValueError("commands must be a string or sequence of strings")
            if args:
                if not isinstance(args, (list, tuple)):
                    raise ValueError("args must be a sequence of strings")
                cmd = [commands] + list(args)
            else:
                cmd = [commands]

        if verbose:
            print(f"Running command: {' '.join(cmd)} (cwd={cwd})")

        result = subprocess.run(
            cmd,
            cwd=cwd,
            env=env,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
            check=True
        )

        if verbose:
            print(f"Command output:\n{result.stdout}")

        return result.stdout

    except subprocess.CalledProcessError as e:
        err_msg = f"Command '{' '.join(e.cmd)}' returned non-zero exit status {e.returncode}."
        if not hide_stderr and e.stderr:
            err_msg += f"\nStderr: {e.stderr}"
        if verbose:
            print(err_msg)
        raise RuntimeError(err_msg) from e
    except Exception as e:
        if not hide_stderr:
            print(f"Error running command: {e}")
        raise

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
