def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    # Validate input types
    if not isinstance(commands, (str, list, tuple)):
        raise ValueError("`commands` must be a string or a list/tuple of strings.")
    if not isinstance(args, (list, tuple)):
        raise ValueError("`args` must be a list or tuple of strings.")
    # Build the command list
    if isinstance(commands, str):
        cmd = [commands]
    else:
        cmd = list(commands)
    cmd.extend(map(str, args))
    # Optional verbose output
    if verbose:
        try:
            import shlex
            cmd_str = shlex.join(cmd)
        except Exception:
            cmd_str = ' '.join(str(part) for part in cmd)
        print(f"Running command: {cmd_str}")
    # Prepare subprocess arguments
    subprocess_kwargs = {
        "cwd": cwd,
        "env": env,
        "stdout": subprocess.PIPE,
        "stderr": subprocess.PIPE,
        "text": True,
        "check": False,
    }
    # If hide_stderr is requested, we still capture stderr but simply don't display it
    # (this allows error messages to be returned via the object)
    # Run the command
    try:
        result = subprocess.run(cmd, **subprocess_kwargs)
    except FileNotFoundError as e:
        raise RuntimeError(f"Command not found: {cmd[0]}") from e
    except Exception as exc:
        raise RuntimeError(f"Failed to run command '{cmd[0]}': {exc}") from exc
    # Raise an error if the command failed (non-zero exit code)
    if result.returncode != 0:
        error_msg = result.stderr.strip() or "Unknown error."
        raise RuntimeError(
            f"Command '{' '.join(map(str, cmd))}' exited with {result.returncode}: {error_msg}"
        )
    return result

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    import subprocess
    import os

    # Validate and build command list
    if isinstance(commands, str):
        cmd = [commands]
    elif isinstance(commands, list):
        # Ensure all elements are strings
        if not all(isinstance(x, str) for x in commands):
            raise TypeError("All elements of 'commands' must be strings")
        cmd = list(commands)  # make a copy
    else:
        raise TypeError("'commands' must be a string or a list of strings")

    if args is None:
        args = []
    if not isinstance(args, list):
        raise TypeError("'args' must be a list of strings")
    if not all(isinstance(arg, str) for arg in args):
        raise TypeError("All elements of 'args' must be strings")

    cmd.extend(args)

    if verbose:
        print(f"Running command: {' '.join(cmd)}", flush=True)

    # Merge environment with the current environment if env is provided
    if env is not None:
        if not isinstance(env, dict):
            raise TypeError("'env' must be a dict or None")
        merge_env = os.environ.copy()
        merge_env.update(env)
    else:
        merge_env = None

    try:
        # Use subprocess.run to execute the command
        result = subprocess.run(
            cmd,
            cwd=cwd,
            env=merge_env,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE if not hide_stderr else subprocess.DEVNULL,
            text=True,
            check=True,
        )
        if verbose:
            print(f"Return code: {result.returncode}", flush=True)
            if result.stdout:
                print(f"Stdout:\n{result.stdout}", flush=True)
            if not hide_stderr and result.stderr:
                print(f"Stderr:\n{result.stderr}", flush=True)
        return result
    except subprocess.CalledProcessError as exc:
        # The command exited with a non-zero status
        if verbose:
            print(f"Command failed with return code {exc.returncode}", flush=True)
            if exc.stdout:
                print(f"Stdout:\n{exc.stdout}", flush=True)
            if exc.stderr:
                print(f"Stderr:\n{exc.stderr}", flush=True)
        raise
    except FileNotFoundError as exc:
        raise RuntimeError(f"Command not found: {cmd[0]}") from exc
    except Exception as exc:
        raise RuntimeError(f"Failed to run command: {exc}") from exc

