def find_roots(
    graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None
) -> Set["Node"]:
    """
    Find the roots in some sort of transitive hierarchy.

    find_roots(graph, rdflib.RDFS.subClassOf)
    will return a set of all roots of the sub-class hierarchy

    Assumes triple of the form (child, prop, parent), i.e. the direction of
    RDFS.subClassOf or SKOS.broader

    """
    if graph is None:
        raise ValueError("The graph argument must not be None.")
    if prop is None:
        return set()

    try:
        # Collect all subjects (children) and all objects (parents) for the property
        children = set()
        parents = set()
        for s, p, o in graph.triples((None, prop, None)):
            children.add(s)
            parents.add(o)
    except Exception as exc:  # pragma: no cover
        raise ValueError(f"Failed to iterate over triples: {exc}") from exc

    if roots is None:
        # Roots are those that appear as children but never as parents
        return children - parents

    # If a set of candidate roots is provided, keep only those that have no parent
    return {node for node in roots if node not in parents}

def _dump_string(obj, dumper=None):
    """Dump to a py2-unicode or py3-string"""
