            if not hasattr(dumper, "dump"):
                raise TypeError("Provided dumper must have a 'dump' method")
            yaml_str = dumper.dump(obj)

        # Ensure the result is a unicode/string object
        if isinstance(yaml_str, bytes):
            try:
                yaml_str = yaml_str.decode("utf-8")
            except Exception as exc:
                raise RuntimeError(f"Failed to decode YAML bytes: {exc}") from exc

        if not isinstance(yaml_str, str):
            # Fall back to string conversion if something unexpected happened
            yaml_str = str(yaml_str)

        return yaml_str

    except yaml.YAMLError as exc:
        raise RuntimeError(f"YAML serialization error: {exc}") from exc
    except Exception as exc:
        raise RuntimeError(f"Error converting object to YAML string: {exc}") from exc

def _dump_string(obj, dumper=None):
