    import sys
    try:
        # Use provided dumper or default to yaml.safe_dump
        dump_func = dumper or yaml.safe_dump
        text = dump_func(obj)
    except Exception as exc:
        raise ValueError(f"Error dumping object to string: {exc}") from exc

    # Ensure the returned value is a text string
    if sys.version_info[0] < 3:  # Python 2: ensure unicode
        if isinstance(text, str):
            try:
                text = text.decode('utf-8')
            except Exception:
                # Fallback for non‑UTF8 data
                text = text.decode('latin1')
    else:  # Python 3: ensure str
        if not isinstance(text, str):
            try:
                text = str(text)
            except Exception as exc:
                raise ValueError(f"Dumped value is not a string: {type(text)!r}") from exc
    return text

