def make_array(shape, dtype=np.dtype("float32")):
    """
    Function to create an array with shape and dtype.

    Parameters
    ----------
    shape : tuple
        shape of the array to create
    dtype : `numpy.dtype`
        data-type of the array to create

    Returns
    -------
    ndarray
        An empty array of the specified shape and dtype.
    """
    # Validate shape
    if not isinstance(shape, tuple):
        raise TypeError(f"shape must be a tuple of integers, got {type(shape).__name__}")
    if not shape:
        raise ValueError("shape tuple cannot be empty")
    for idx, dim in enumerate(shape):
        if not isinstance(dim, int):
            raise TypeError(f"shape element at index {idx} is not an integer, got {type(dim).__name__}")
        if dim <= 0:
            raise ValueError(f"shape element at index {idx} is non‑positive ({dim})")
    # Validate dtype
    if isinstance(dtype, np.dtype):
        dt = dtype
    else:
        try:
