    # Local helpers
    def _create_error_record(exc, filename):
        """Create a LogRecord for an exception that occurred while processing a file."""
        level = logging.ERROR
        msg = f"Failed to load configuration '{filename}': {exc}"
        # Attempt to attach exception details
        return logging.LogRecord(name=__name__, level=level, pathname=filename,
                                 lineno=0, msg=msg, args=(), exc_info=(type(exc), exc, exc.__traceback__))

    def _resolve_env_in_node(node):
        """Recursively resolve environment variable placeholders in a node."""
        import re
        if isinstance(node, str):
            # Find all ${VAR} patterns
            def repl(match):
                var = match.group(1)
                return os.environ.get(var, match.group(0))
            return re.sub(r'\$\{([^}]+)\}', repl, node)
        elif isinstance(node, list):
            return [_resolve_env_in_node(item) for item in node]
        elif isinstance(node, dict):
            return {k: _resolve_env_in_node(v) for k, v in node.items()}
        else:
            return node

    import json
    import os

    for filename in iterator:
        # Attempt to read file
        try:
            with open(filename, 'r', encoding='utf-8') as f:
                content = f.read()
        except Exception as exc:
            error_records.append(_create_error_record(exc, filename))
            continue

        # Attempt to parse content as JSON
        try:
            config_data = json.loads(content)
        except Exception as exc:
            error_records.append(_create_error_record(exc, filename))
            continue

        # Validate that parsed data is a dictionary
        if not isinstance(config_data, dict):
            exc = TypeError(f"Configuration in '{filename}' is not a JSON object")
            error_records.append(_create_error_record(exc, filename))
            continue

        # Apply environment variable resolution if requested
        if resolve_env:
            try:
                config_data = _resolve_env_in_node(config_data)
            except Exception as exc:
                error_records.append(_create_error_record(exc, filename))
                continue

        # Apply overrides if provided
        if overrides is not None:
            if not isinstance(overrides, dict):
                error_records.append(_create_error_record(
                    TypeError("overrides must be a dict"), filename))
            else:
                # Shallow merge; override top-level keys
                try:
                    config_data.update(overrides)
                except Exception as exc:
                    error_records.append(_create_error_record(exc, filename))

        configs[filename] = config_data

    return configs, error_records

