def load_configurations(config_filenames, overrides=None, resolve_env=True):
    import json
    import os
    import re
    import logging
    from logging import LogRecord

    configs = {}
    errors = []

    # Helper to resolve environment variables in string values
    env_pattern = re.compile(r'\${([^}]+)}')

    def _resolve(value):
        if isinstance(value, str):
            def repl(match):
                var_name = match.group(1)
                return os.getenv(var_name, '')
            return env_pattern.sub(repl, value)
        elif isinstance(value, dict):
            return {k: _resolve(v) for k, v in value.items()}
        elif isinstance(value, list):
            return [_resolve(v) for v in value]
        else:
            return value

    if overrides is None:
        overrides = {}

    for filename in config_filenames:
        try:
            with open(filename, 'r', encoding='utf-8') as f:
                raw = f.read()
            try:
                data = json.loads(raw)
            except Exception as e:
                record = LogRecord(
                    name='config_loader',
                    level=logging.ERROR,
                    pathname=filename,
                    lineno=0,
                    msg=f'JSON parse error in {filename}: {e}',
                    args=None,
                    exc_info=None
                )
                errors.append(record)
                continue

            if resolve_env:
                try:
                    data = _resolve(data)
                except Exception as e:
                    record = LogRecord(
                        name='config_loader',
                        level=logging.ERROR,
                        pathname=filename,
                        lineno=0,
                        msg=f'Environment substitution error in {filename}: {e}',
                        args=None,
                        exc_info=None
                    )
                    errors.append(record)
                    continue

            configs[filename] = data

        except FileNotFoundError as e:
            record = LogRecord(
                name='config_loader',
                level=logging.ERROR,
                pathname=filename,
                lineno=0,
                msg=f'File not found: {filename}',
                args=None,
                exc_info=e
            )
            errors.append(record)
        except Exception as e:
            record = LogRecord(
                name='config_loader',
                level=logging.ERROR,
                pathname=filename,
                lineno=0,
                msg=f'Unexpected error loading {filename}: {e}',
                args=None,
                exc_info=e
            )
            errors.append(record)

    # Apply overrides to each config dict
    for cfg in configs.values():
        if isinstance(cfg, dict) and isinstance(overrides, dict):
            cfg.update(overrides)

    return configs, errors

