def scale(self, other=None):
        """Get or set the scale of the graph.

        If *other* is ``None``, return the scale of this graph.

        If a numeric *other* is provided, rescale to that value.
        If the graph has unknown or zero scale,
        rescaling that will raise :exc:`~.LenaValueError`.

        To get meaningful results, graph's fields are used.
        Only the last coordinate is rescaled.
        For example, if the graph has *x* and *y* coordinates,
        then *y* will be rescaled, and for a 3-dimensional graph
        *z* will be rescaled.
        All errors are rescaled together with their coordinate.
        """
        # Retrieve current scale
        try:
            current_scale = getattr(self, "scale", None)
        except Exception:
            current_scale = None

        # If no new scale is requested, simply return the current scale
        if other is None:
            return current_scale

        # Validate the new scale
        if not isinstance(other, (int, float)):
            raise TypeError(f"scale value must be numeric, got {type(other).__name__}")
        if current_scale is None or current_scale == 0:
            raise ValueError("Cannot rescale because current scale is unknown or zero")

        factor = other / current_scale

        # Identify coordinate attributes (x, y, z, t by convention)
        coord_candidates = ("x", "y", "z", "t")
        coordinate_names = []
        for name in coord_candidates:
            if hasattr(self, name):
                value = getattr(self, name)
                # Accept list/tuple or scalar numeric
                if isinstance(value, (list, tuple, set)):
                    coordinate_names.append(name)
                elif isinstance(value, (int, float)):
                    coordinate_names.append(name)

        # Fallback: if no conventional coordinates, search for any list/tuple attributes
        if not coordinate_names:
            for name in dir(self):
                if name.startswith("_"):
                    continue
                try:
                    value = getattr(self, name)
                except Exception:
                    continue
                if isinstance(value, (list, tuple, set)) or isinstance(value, (int, float)):
                    coordinate_names.append(name)

        if not coordinate_names:
            raise ValueError("No coordinate fields found for rescaling")

        # The last coordinate is the one to rescale
        last_coord = coordinate_names[-1]
        try:
            coord_value = getattr(self, last_coord)
        except Exception as exc:
            raise AttributeError(f"Failed to access coordinate '{last_coord}'") from exc

        # Perform rescaling
        def _rescale(value):
            try:
                # Handle scalars
                if isinstance(value, (int, float)):
                    return value * factor
                # Handle sequences
                return type(value)(v * factor for v in value)
            except Exception as e:
                raise ValueError(f"Failed to rescale value of '{last_coord}'") from e

        new_coord = _rescale(coord_value)
        setattr(self, last_coord, new_coord)

        # Rescale associated error field if it exists
        error_attr = f"{last_coord}_err"
        if hasattr(self, error_attr):
            err_value = getattr(self, error_attr)
            try:
                new_err = _rescale(err_value)
                setattr(self, error_attr, new_err)
            except Exception:
                # Ignore if error scaling fails
                pass

        # Update the scale attribute
        setattr(self, "scale", other)

        return self

