    if not tentative:
        try:
            provided = iface.providedBy(candidate)
            if not provided:
                errors.append(f'candidate {candidate!r} does not provide interface {iface}')
        except Exception as exc:
            errors.append(f'providing check failed for {candidate!r} with error: {exc}')

    # 2. Check that candidate defines all required methods
    # Interface methods are defined as attributes that are callable (functions or properties)
    iface_attrs = list(iface.__dict__.items())
    for name, attr in iface_attrs:
        # Skip special attributes
        if name.startswith('_'):
            continue
        # Determine if interface attribute is a method or attribute
        is_method = callable(attr)
        if name not in getattr(candidate, '__dict__', {}) and not hasattr(candidate, name):
            errors.append(f'candidate {candidate!r} lacks required {"method" if is_method else "attribute"} {name}')
            continue

        if is_method:
            # Signature comparison
            try:
                iface_sig = inspect_mod.signature(attr)
                cand_attr = getattr(candidate, name)
                cand_sig = inspect_mod.signature(cand_attr)
                # Compare parameters count (excluding * and **)
                iface_params = [
                    p for p in iface_sig.parameters.values()
                    if p.kind in (inspect_mod.Parameter.POSITIONAL_OR_KEYWORD,
                                  inspect_mod.Parameter.KEYWORD_ONLY)
                ]
                cand_params = [
                    p for p in cand_sig.parameters.values()
                    if p.kind in (inspect_mod.Parameter.POSITIONAL_OR_KEYWORD,
                                  inspect_mod.Parameter.KEYWORD_ONLY)
                ]
                if len(cand_params) < len(iface_params):
                    errors.append(
                        f'signature mismatch for {name}: interface expects at least {len(iface_params)} '
                        f'positional/keyword parameters, candidate provides {len(cand_params)}'
                    )
            except Exception as exc:
                errors.append(f'could not analyze signature for {name} due to error: {exc}')

    # 3. Check required attributes (non-callable interface attributes)
    for name, attr in iface_attrs:
        if name.startswith('_'):
            continue
        if callable(attr):
            continue  # Already handled as method
        if not hasattr(candidate, name):
            errors.append(f'candidate {candidate!r} lacks required attribute {name}')

    if errors:
        if len(errors) == 1:
            raise Invalid(errors[0])
        raise Invalid('; '.join(errors))

    return True

