def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    Returns True if candidate satisfies the interface; raises ValueError otherwise.
    """
    # Basic type checks
    if not isinstance(iface, type):
        raise TypeError("iface must be a class")
    if not isinstance(candidate, type):
        raise TypeError("candidate must be a class")

    # Collect required attribute names from iface
    required = set()
    for name in dir(iface):
        # Skip special attributes
        if name.startswith('__') and name.endswith('__'):
            continue
        try:
            attr = getattr(iface, name)
        except Exception:
            # If attribute lookup fails, skip it
            continue
        # If not tentative, only consider callables
        if tentative:
            required.add(name)
        else:
            if callable(attr):
                required.add(name)

    # Verify candidate has required attributes
    missing = []
    for name in required:
        if not hasattr(candidate, name):
            missing.append(name)
        elif not tentative and not callable(getattr(candidate, name)):
            # Interface expects a callable but candidate's attribute is not callable
            missing.append(name)

    if missing:
        raise ValueError("Candidate class does not satisfy interface requirements: missing or invalid attributes: %s" % ', '.join(sorted(missing)))

    return True

def determineMetaclass(bases, explicit_mc=None):
    """
    Determine the metaclass to use for a new class from its bases and an optional
    explicit metaclass.
    The algorithm follows the semantics of CPython's
    _calculate_metaclass: a metaclass is deduced when no explicit metaclass
    is supplied; otherwise the explicit one is used. The chosen metaclass
    must be a subclass of type and be a common superclass of all bases.
    A TypeError is raised when a suitable metaclass cannot be found or
    when the bases cannot share a common metaclass.
    """
    # Validate bases
    if not isinstance(bases, (tuple, list)):
        raise TypeError("bases must be a tuple or list of types")
    if not bases:
        raise TypeError("at least one base class required")

    # Ensure all bases are types
    for base in bases:
        if not isinstance(base, type):
            raise TypeError(f"base {base!r} is not a type")

    # Start with the explicit metaclass, if provided
    if explicit_mc is not None:
        if not isinstance(explicit_mc, type):
            raise TypeError("explicit_metaclass must be a type")
        metaclass = explicit_mc
    else:
        metaclass = None

    # Find and reconcile metaclasses from bases
    for base in bases:
        base_mc = getattr(base, "__metaclass__", None)
        if base_mc is None:
            continue
        if not isinstance(base_mc, type):
            raise TypeError(f"__metaclass__ attribute of {base!r} is not a type")
        if metaclass is None:
            metaclass = base_mc
        elif metaclass is not base_mc:
            # Resolve which metaclass is more derived
            try:
                if issubclass(metaclass, base_mc):
                    # current metaclass is more derived; keep it
                    pass
                elif issubclass(base_mc, metaclass):
                    metaclass = base_mc
                else:
                    raise TypeError
            except TypeError:
                raise TypeError(
                    f"metaclass conflict between {metaclass!r} and {base_mc!r}"
                ) from None

    # Default to type if no metaclass has been chosen yet
    if metaclass is None:
        metaclass = type

    # Ensure every base is a subclass of the selected metaclass
    for base in bases:
        if not issubclass(base, metaclass):
            raise TypeError(
                f"cannot create a consistent method resolution order (MRO) "
                f"for bases {bases}"
            )

    return metaclass

