    """Determine the most derived metaclass for the given bases and optional explicit __metaclass__"""
    # Gather metaclasses from bases
    metaclasses = [type(b) for b in bases]
    if explicit_mc is not None:
        metaclasses.append(explicit_mc)

    # If no metaclasses found, fall back to type
    if not metaclasses:
        return type

    # If only one metaclass, it's the answer
    if len(metaclasses) == 1:
        return metaclasses[0]

    # Find the most derived metaclass that all others are subclasses of
    for candidate in metaclasses:
        try:
            # Ensure candidate is a class (metaclass)
            if not isinstance(candidate, type):
                continue
            if all(issubclass(other, candidate) for other in metaclasses if other is not candidate):
