        except Exception:
            # Skip any candidates that are not suitable
            continue

    # If no common ancestor metaclass, fall back to type and raise error
    raise TypeError(
        f"Metaclass conflict for bases {tuple(b.__name__ for b in bases) if bases else '()'}: "
        f"{', '.join(mc.__name__ for mc in metaclasses)}"
    )

