def format_dt(dt):
    """
    Format a datetime in the way that D* nodes expect.
    The expected format is ISO 8601 in UTC, e.g. '2024-03-25T14:20:00Z'.
    If *dt* is not a datetime instance but a string that parses as ISO format,
    it will be converted to a datetime before formatting.
    """
    if dt is None:
        return None

    # If it's already a datetime, format it
    if isinstance(dt, datetime.datetime):
        # Ensure UTC: if naive, assume UTC; otherwise convert
        if dt.tzinfo is None:
            # Assume naive datetime is UTC
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        else:
            dt = dt.astimezone(datetime.timezone.utc)
        return dt.strftime("%Y-%m-%dT%H:%M:%SZ")

    # If it's a string, try to parse it as ISO 8601 and then format
    try:
        parsed = datetime.datetime.fromisoformat(dt)
        return format_dt(parsed)
    except Exception:
        # If parsing fails, return the original string unchanged
        return dt

