def fetch_content_type(url: str) -> Optional[str]:
    """
    Fetch the HEAD of the remote url to determine the content type.
    Returns the value of the "Content-Type" header if available, otherwise None.
    """
    try:
        urllib_request = __import__('urllib.request')
    except Exception:
        return None

    try:
        # Attempt a HEAD request first
        req = urllib_request.Request(url, method='HEAD')
        with urllib_request.urlopen(req) as resp:
            return resp.headers.get('Content-Type')
    except urllib_request.HTTPError as e:
        # Some servers reject HEAD; try a lightweight GET
        if e.code == 405:  # Method Not Allowed
            try:
                req = urllib_request.Request(url, method='GET')
                with urllib_request.urlopen(req) as resp:
                    return resp.headers.get('Content-Type')
            except Exception:
                return None
        return None
    except Exception:
        return None

