            for link in data.get("links", []):
                if not isinstance(link, dict):
                    continue
                rel = link.get("rel")
                href = link.get("href")
                if href:
                    links.append({"rel": rel, "href": href})
            return {"subject": subject, "aliases": aliases, "links": links}
    except Exception:
        # Fallback to XRD parsing
        pass

    # Attempt to parse XRD (XML)
    try:
        import xml.etree.ElementTree as ET
        root = ET.fromstring(document)
        # Detect namespace
        ns = ""
        if root.tag.startswith("{"):
            ns = root.tag.split("}")[0].strip("{")
        ns_prefix = f"{{{ns}}}" if ns else ""
        subject_el = root.find(f"{ns_prefix}Subject")
        subject = subject_el.text if subject_el is not None else None
