        link_els = root.findall(f"{ns_prefix}Link")
        for el in link_els:
            rel = el.attrib.get("rel")
            href = el.attrib.get("href")
            if href:
                links.append({"rel": rel, "href": href})
        return {"subject": subject, "aliases": aliases, "links": links}
    except Exception as e:
        # If parsing fails, return empty dict or you could log the error.
        # For safety, return an empty dictionary.
        return {}

