                else:
                    result["aliases"] = [str(a).strip() for a in aliases if isinstance(a, (str, bytes))]
            if "links" in data and isinstance(data["links"], list):
                links = []
                for item in data["links"]:
                    if isinstance(item, dict):
                        link = {k: v for k, v in item.items() if isinstance(k, str)}
                        links.append(link)
                if links:
                    result["links"] = links
        return result
    except Exception:
        # Ignore JSON errors and try XML
        pass

    # Try XRD (XML)
    try:
        import xml.etree.ElementTree as ET
        root = ET.fromstring(document)
    except Exception:
        # XML parsing failed
        return {}

    # Helper to strip namespace, if present
    def _strip_ns(tag: str) -> str:
        idx = tag.rfind("}")
        return tag[idx + 1 :] if idx != -1 else tag

    aliases = []
    for elem in root.iter():
        tag = _strip_ns(elem.tag)
        if tag.lower() == "alias" and elem.text:
            aliases.append(elem.text.strip())
    if aliases:
        result["aliases"] = aliases

    links = []
    for link_elem in root.findall(".//{*}Link") if hasattr(ET, "XPath") else []:  # noqa: E501
        pass  # placeholder for environments lacking XPath

    # Since ElementTree's findall doesn't support wildcard namespace directly,
    # we'll scan all elements and look for 'Link' tags.
    for elem in root.iter():
        tag = _strip_ns(elem.tag)
        if tag.lower() == "link":
            link = {}
            # Attributes: rel, type, href, template, title, etc.
            for attr in ("rel", "type", "href", "template", "title", "media", "hrefs"):
                if attr in elem.attrib:
                    link[attr] = elem.attrib[attr]
            # Sometimes link info is present in subelements
            for child in elem:
                child_tag = _strip_ns(child.tag).lower()
                if child_tag in ("rel", "type", "href", "template", "title", "media"):
                    if child.text:
                        link[child_tag] = child.text.strip()
            if link:
                links.append(link)
    if links:
        result["links"] = links

