def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    import xml.etree.ElementTree as ET

    def _parse_json(doc: str) -> Dict:
        try:
            data = json.loads(doc)
        except json.JSONDecodeError as exc:
            raise ValueError(f"Failed to parse JSON: {exc}") from exc

        subject = data.get("subject")
        aliases = data.get("aliases", [])
        if not isinstance(aliases, list):
            aliases = [aliases]
        links = []
        for item in data.get("links", []):
            if isinstance(item, dict):
                rel = item.get("rel")
                href = item.get("href")
                link_type = item.get("type")
                if rel and href:
                    links.append({"rel": rel, "href": href, "type": link_type})
        return {"subject": subject, "aliases": aliases, "links": links}

    def _parse_xrd(doc: str) -> Dict:
        ns = {"xrd": "http://docs.oasis-open.org/ns/xri/xrd-1.0"}
        try:
            root = ET.fromstring(doc)
        except ET.ParseError as exc:
            raise ValueError(f"Failed to parse XML: {exc}") from exc

        subject_el = root.find("xrd:Subject", ns)
        subject = subject_el.text.strip() if subject_el is not None and subject_el.text else None

        aliases = []
        for alias_el in root.findall("xrd:Alias", ns):
            if alias_el.text:
                aliases.append(alias_el.text.strip())

        links = []
        for link_el in root.findall("xrd:Link", ns):
            rel = link_el.attrib.get("rel")
            href = link_el.attrib.get("href")
            link_type = link_el.attrib.get("type")
            if rel and href:
                links.append({"rel": rel, "href": href, "type": link_type})

        return {"subject": subject, "aliases": aliases, "links": links}

    if not isinstance(document, str) or not document.strip():
        raise ValueError("Input document must be a non-empty string")

    doc = document.strip()
    # Heuristically decide between JSON and XML
    if doc.startswith("{") or doc.startswith("["):
        return _parse_json(doc)
    if doc.startswith("<"):
        return _parse_xrd(doc)
    # Try JSON first, fallback to XML
    try:
        return _parse_json(doc)
    except ValueError:
        return _parse_xrd(doc)

