            result['subject'] = data.get('subject')
            links = data.get('links', [])
            parsed_links = []
            for link in links:
                if isinstance(link, dict):
                    rel = link.get('rel')
                    href = link.get('href')
                    if rel and href:
                        parsed_links.append({'rel': rel, 'href': href})
            result['links'] = parsed_links
            return result
    except Exception:
        # Ignore and try XRD parsing
        pass

    # Attempt XRD parsing (old format)
    try:
        ET = __import__('xml.etree.ElementTree', fromlist=['ElementTree'])
        root = ET.fromstring(document)
        result: Dict[str, Any] = {}
        # Namespaces may be present; strip them
        def strip_ns(tag: str) -> str:
            return tag.split('}', 1)[-1] if '}' in tag else tag

        subject_elem = None
        for child in root:
            if strip_ns(child.tag) == 'Subject':
                subject_elem = child
                break
        result['subject'] = subject_elem.text if subject_elem is not None else None

        parsed_links = []
        for link in root.findall('.//Link'):
            rel = link.get('rel')
            href = None
            # <Href> might be a child element or attribute
            href_elem = link.find('.//Href')
            if href_elem is not None:
                href = href_elem.text
            else:
                href = link.get('href')
            if rel and href:
                parsed_links.append({'rel': rel, 'href': href})
        result['links'] = parsed_links
        return result
    except Exception as e:
        raise ValueError("Unsupported webfinger format or invalid document") from e

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    import xml.etree.ElementTree as ET

    # Try JSON first
    try:
        json_obj = json.loads(document)
        if isinstance(json_obj, dict):
            return json_obj
        raise ValueError("JSON webfinger must be an object")
    except Exception:
        pass  # fall back to XRD parsing

    # XRD format
    try:
        root = ET.fromstring(document.encode("utf-8"))
        ns = {"xrd": "http://docs.oasis-open.org/ns/xri/xrd-1.0"}

        result: Dict = {}

        sub_el = root.find("xrd:subject", ns)
        if sub_el is not None and sub_el.text:
            result["subject"] = sub_el.text

        aliases = [a.text for a in root.findall("xrd:Alias", ns) if a.text]
        if aliases:
            result["aliases"] = aliases

        links = []
        for link_el in root.findall("xrd:Link", ns):
            link: Dict = {}
            for attr in ("rel", "href", "type", "template"):
                if attr in link_el.attrib:
                    link[attr] = link_el.attrib[attr]
            if link:
                links.append(link)
        if links:
            result["links"] = links

        properties: Dict = {}
        for prop_el in root.findall("xrd:Property", ns):
            prop_type = prop_el.attrib.get("type")
            if prop_type:
                properties[prop_type] = prop_el.text
        if properties:
            result["properties"] = properties

        return result
    except ET.ParseError as e:
        raise ValueError(f"Unable to parse webfinger document as JSON or XRD: {e}") from e

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.
    :param handle: The account handle in the form acct:<user>@<domain>.
    :return: The webfinger document as a string if successful, otherwise None.
    """
    try:
        # Validation of the handle
        if not isinstance(handle, str) or '@' not in handle:
            return None

        # Extract domain part
        try:
            _, domain = handle.split('@', 1)
        except ValueError:
            return None
        if not domain:
            return None

        # Define the base URL with HTTPS; fallback to HTTP if HTTPS fails
        urls = [
            f"https://{domain}/.well-known/webfinger?resource=acct:{handle}",
            f"http://{domain}/.well-known/webfinger?resource=acct:{handle}",
        ]

        # Use standard library urllib for HTTP requests
        from urllib.request import Request, urlopen
        from urllib.error import URLError, HTTPError

        for url in urls:
            try:
                req = Request(url, headers={'User-Agent': 'PythonWebFingerClient/1.0'})
                with urlopen(req, timeout=5) as response:
                    if 200 <= response.status < 300:
                        content_bytes = response.read()
                        return content_bytes.decode('utf-8', errors='replace')
            except (HTTPError, URLError):
                # Try next URL option
                continue
    except Exception:
        # Any unforeseen error results in a graceful None
        pass

    return None

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
