        urllib_request = __import__("urllib.request", fromlist=["Request", "urlopen"])
        urllib_parse = __import__("urllib.parse", fromlist=["urlencode"])
        query = urllib_parse.urlencode({"resource": resource})
        url = f"https://{domain}/.well-known/webfinger?{query}"
        req = urllib_request.Request(url, headers={"Accept": "application/jrd+json"})
        with urllib_request.urlopen(req, timeout=5) as resp:
