def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.
    """
    # Validate handle format
    if not isinstance(handle, str) or '@' not in handle:
        return None

    local_part, domain = handle.split('@', 1)
    if not local_part or not domain:
        return None

    # Build the webfinger URL according to RFC 7033
    url = f"https://{domain}/.well-known/webfinger?resource=acct:{local_part}@{domain}"

    try:
        import urllib.request
        from urllib.error import URLError, HTTPError

        req = urllib.request.Request(url, headers={
            "User-Agent": "Python WebFinger Client"
        })
        with urllib.request.urlopen(req, timeout=5) as resp:
            # Attempt to decode the content as UTF-8
            raw = resp.read()
            try:
                return raw.decode("utf-8")
            except Exception:
                # Fallback: return bytes decoded with errors ignored
                return raw.decode("utf-8", errors="ignore")
    except (URLError, HTTPError, Exception):
        # Any error (network issue, bad status, decoding problems) results in a None return
        return None

def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    # Validate and parse the handle
    if not isinstance(handle, str) or '@' not in handle:
        return {}
    try:
        user_part, host_part = handle.split('@', 1)
    except ValueError:
        return {}
    if not user_part or not host_part:
        return {}

    # Build the WebFinger URL
    url = f"https://{host_part}/.well-known/webfinger?resource=acct:{handle}"
    headers = {'Accept': 'application/jrd+json'}

    # Perform the HTTP request
    try:
        import urllib.request
        import urllib.error
        import json

        req = urllib.request.Request(url, headers=headers, method='GET')
        with urllib.request.urlopen(req, timeout=10) as response:
            if response.status != 200:
                return {}
            content_type = response.headers.get('Content-Type', '')
            if 'application/jrd+json' not in content_type:
                # Attempt to parse anyway if JSON
                pass
            data_bytes = response.read()
            data_text = data_bytes.decode(response.headers.get_content_charset('utf-8'))
            return json.loads(data_text)
    except (urllib.error.HTTPError, urllib.error.URLError, json.JSONDecodeError, Exception):
        # Return an empty dict on any error
        return {}

def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    # Basic validation of the handle
    if not isinstance(handle, str) or '@' not in handle:
        return {}

    handle = handle.strip()
    try:
        username, domain = handle.split('@', 1)
    except ValueError:
        # Handle could not be split into username and domain
        return {}

    # Construct the WebFinger request URL
    resource = f'acct:{handle}'
    url = f"https://{domain}/.well-known/webfinger?resource={resource}"

    try:
        import requests
        response = requests.get(url, timeout=10)
        response.raise_for_status()
        data = response.json()
        if isinstance(data, dict):
            return data
    except Exception:
        # Any issue (network, JSON decoding, etc.) results in an empty dict
        pass

    return {}

def retrieve_diaspora_host_meta(host):
    """
    Retrieve a remote Diaspora host‑meta document.

    :arg host: Host to retrieve from, can be provided with or without scheme.
    :returns: ``XRD`` instance (in this implementation, an ElementTree Element)
    :raises ValueError: If the host argument is empty or invalid.
    :raises RuntimeError: If the HTTP request fails or the XML cannot be parsed.
    """
    if not isinstance(host, str) or not host.strip():
        raise ValueError("host must be a non‑empty string")

    host = host.strip()
    # Ensure a scheme is present
    if not host.startswith(("http://", "https://")):
        url = f"https://{host}"
    else:
        url = host

    # Append the well‑known path correctly
    if not url.endswith("/"):
        url += "/"
    url += ".well-known/host-meta"

    try:
        import requests
        import xml.etree.ElementTree as ET

        response = requests.get(url, timeout=10)
        response.raise_for_status()
    except Exception as exc:
        raise RuntimeError(f"Failed to retrieve host‑meta from {host!r}: {exc}") from exc

    try:
        # Parse the XML content; ElementTree.Element acts as an XRD representation
        return ET.fromstring(response.content)
    except ET.ParseError as exc:
        raise RuntimeError(f"Failed to parse host‑meta XML from {host!r}: {exc}") from exc

def retrieve_diaspora_host_meta(host):
    """
    Retrieve a remote Diaspora host-meta document.

    :arg host: Host to retrieve from, e.g., "example.com" or "https://example.com".
    :returns: ``XRD`` instance
    """
    # Validate input
    if not host or not isinstance(host, str):
        raise ValueError("host must be a non-empty string")

    # Determine the URL(s) to try
    if host.startswith("http://") or host.startswith("https://"):
        base = host
    else:
        base = f"https://{host}"
    urls = [
        f"{base.rstrip('/')}/.well-known/host-meta",
        f"http://{host.rstrip('/')}/.well-known/host-meta"
    ]

    # Import modules locally to avoid requiring them at top level
    import urllib.request
    import urllib.error

    # Attempt to fetch the host-meta document
    last_exception = None
    for url in urls:
        try:
            req = urllib.request.Request(url, headers={"Accept": "application/xrd+xml"})
            with urllib.request.urlopen(req, timeout=5) as resp:
                if resp.status != 200:
                    raise ValueError(f"Failed to retrieve host-meta from {url}: HTTP {resp.status}")
                content = resp.read().decode(resp.headers.get_content_charset() or "utf-8")
        except Exception as exc:
            last_exception = exc
            continue
        else:
            # Parse the XML into an XRD instance
            try:
                # The XRD class is expected to be available in the diaspora library.
                from diaspora.xrd import XRD
                return XRD.parse_from_string(content)
            except Exception as exc:
                raise ValueError(f"Failed to parse host-meta XML from {url}: {exc}") from exc

    # If all attempts failed, raise the last exception encountered
    raise ValueError(f"Unable to retrieve host-meta from host '{host}'.") from last_exception

def retrieve_diaspora_host_meta(host):
    """
    Retrieve a remote Diaspora host-meta document.

    :arg host: Host to retrieve from
    :returns: ``XRD`` instance
    """
    # Basic validation
    if not isinstance(host, str) or not host.strip():
        raise ValueError("host must be a non-empty string")

    url = f"https://{host.rstrip('/')}/.well-known/host-meta"

    try:
        resp = requests.get(url, timeout=10)
        resp.raise_for_status()
    except Exception as exc:
        raise RuntimeError(f"Failed to fetch host-meta from {url}") from exc

    try:
