    except Exception as exc:
        raise RuntimeError(f"Failed to parse host-meta XML from {url}") from exc

    return xrd_obj

def send_document(url, data, timeout=10, method="post", *args, **kwargs):
    """Helper method to send a document via POST.

    Additional ``*args`` and ``**kwargs`` will be passed on to ``requests.post``.

    :arg url: Full url to send to, including protocol
    :arg data: Dictionary (will be form-encoded), bytes, or file-like object to send in the body
    :arg timeout: Seconds to wait for response (defaults to 10)
    :arg method: Method to use, defaults to post
    :returns: Tuple of status code (int or None) and error (exception class instance or None)
    """
    # Validate input parameters
    if not isinstance(url, str) or not url:
        raise ValueError("url must be a non-empty string")
    if method.lower() != "post":
        raise ValueError("Method not supported: only 'post' is allowed")
    try:
        # Import requests lazily to keep function self-contained
        import requests
        # Prepare arguments for the request
        req_kwargs = {
            "url": url,
            "data": data,
            "timeout": timeout,
        }
        # Merge additional args and kwargs
        # ``*args`` are unlikely to be used with requests.post, but we pass them if provided
        if args:
            # requests.post accepts only keyword arguments; ignore positional args
            pass
        req_kwargs.update(kwargs)
        # Send the request
        response = requests.post(**req_kwargs)
        # Return status code and no error
        return (response.status_code, None)
    except requests.exceptions.RequestException as exc:
        # Any requests-specific exception (timeout, connection error, etc.)
        return (None, exc)
    except Exception as exc:
        # Catch all other exceptions (e.g., invalid data types)
        return (None, exc)

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type
    """
    try:
        # Validate inputs
        if not isinstance(settings_dirs, (list, tuple)):
            raise TypeError("settings_dirs must be a list or tuple of directory paths")
        if not isinstance(spec_option, str):
            raise TypeError("spec_option must be a string")
        # Lazily import required standard libraries
        os = __import__("os")
        fnmatch = __import__("fnmatch")
        filenames = []
        for dir_path in settings_dirs:
            try:
                if not os.path.isdir(dir_path):
                    continue
                for entry in os.listdir(dir_path):
                    full_path = os.path.join(dir_path, entry)
                    if os.path.isfile(full_path) and fnmatch.fnmatch(entry, spec_option):
                        filenames.append(entry)
            except Exception:
                # Skip directories that cannot be accessed
                continue
        return sorted(filenames)
    except Exception as e:
        # In case of unforeseen errors, return an empty list or re-raise if needed
        return []

def list_of_file_names(settings_dirs, spec_option):
    """
    Returns a list of file names found in the supplied directories, optionally filtered
    by *spec_option*. ``settings_dirs`` may be a single directory path or an iterable
    of directory paths. ``spec_option`` may be:

    * ``None`` – return all files in the directories
    * a glob pattern such as ``*.ini`` – matched using ``glob``.
    * a regular expression – matched against file names using ``re``; if it contains
      any of ``*?[]`` it will be treated as a glob instead of a regex.

    The function tolerates non‑existent directories, unreadable paths, and
    invalid patterns by skipping the problematic entry and continuing the scan.
    All file names returned are the base names (no directory components).
    """
    import os
    import glob
    import re

    # Normalise settings_dirs to an iterable of paths
    if isinstance(settings_dirs, (str, bytes)):
        dirs = [settings_dirs]
    else:
        try:
            dirs = list(settings_dirs)
        except TypeError:
            raise TypeError("settings_dirs must be a string or an iterable of directory paths")

    found_files = set()
    for d in dirs:
        try:
            abs_dir = os.path.abspath(d)
        except Exception:
            # Skip if cannot resolve absolute path
            continue

        if not os.path.isdir(abs_dir):
            # Directory does not exist or is not a directory, skip
            continue

        # Determine how to filter files
        if spec_option is None:
            # List all regular files in the directory
            try:
                for entry in os.listdir(abs_dir):
                    full_path = os.path.join(abs_dir, entry)
                    if os.path.isfile(full_path):
                        found_files.add(entry)
            except OSError:
                continue
        else:
            if isinstance(spec_option, (bytes, bytearray)):
                spec = spec_option.decode()
            else:
                spec = str(spec_option)

            # If spec contains glob wildcards, use glob
            if any(ch in spec for ch in ('*', '?', '[')):
                pattern = os.path.join(abs_dir, spec)
                try:
                    for path in glob.glob(pattern):
                        if os.path.isfile(path):
                            found_files.add(os.path.basename(path))
                except OSError:
                    continue
            else:
                # Treat as a regular expression
                try:
                    regex = re.compile(spec)
                except re.error:
                    # Invalid regex; skip this directory
                    continue
                try:
                    for entry in os.listdir(abs_dir):
                        if regex.search(entry):
                            full_path = os.path.join(abs_dir, entry)
                            if os.path.isfile(full_path):
                                found_files.add(entry)
                except OSError:
                    continue

    return sorted(found_files)

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type"""

    os = __import__('os')
    fnmatch = __import__('fnmatch')

    if settings_dirs is None:
        return []

    # Normalize settings_dirs to a list
    if isinstance(settings_dirs, (str, bytes)):
        dir_list = [settings_dirs]
    else:
        try:
            dir_list = list(settings_dirs)
        except TypeError:
            dir_list = [settings_dirs]

    result = []
    for d in dir_list:
        try:
            if not os.path.isdir(d):
                continue
            for entry in os.listdir(d):
                full_path = os.path.join(d, entry)
                if not os.path.isfile(full_path):
                    continue
                if spec_option is None:
                    result.append(full_path)
                else:
                    if isinstance(spec_option, str):
                        if fnmatch.fnmatch(entry, spec_option):
                            result.append(full_path)
                    elif callable(spec_option):
                        try:
                            if spec_option(entry):
                                result.append(full_path)
                        except Exception:
                            # Skip entries for which the predicate raises an error
                            pass
                    else:
                        # Unsupported spec_option type; ignore it
                        pass
        except OSError:
            # Skip directories that cannot be accessed
            continue

    return result

