def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files."""
    # Basic type check
    if not isinstance(parser_dict, dict):
        raise TypeError("parser_dict must be a dictionary")

    # Helper that merges two dictionaries, recursively merging nested dicts.
    def _merge_dicts(src: dict, dest: dict) -> None:
        for key, val in src.items():
            if key in dest and isinstance(dest[key], dict) and isinstance(val, dict):
                _merge_dicts(val, dest[key])
            else:
                dest[key] = val

    # The directive is expected under the key ``"_include_groups"``.
    # If present, merge its contents into ``parser_dict`` and delete the key.
    include_key = "_include_groups"
    includes = parser_dict.pop(include_key, None)

    if includes is None:
        # Nothing to include, just return the original dictionary
        return parser_dict

    if not isinstance(includes, dict):
        raise ValueError(f"The value of the ``{include_key}`` key must be a dictionary")

    # Merge the included dictionary into the main one.
    try:
        _merge_dicts(includes, parser_dict)
    except Exception as exc:
        # Provide context in the error message
        raise RuntimeError(f"Failed to resolve include groups for key '{include_key}'") from exc

    return parser_dict

