            # The parser object (typically argparse.ArgumentParser) holds
            # its actions in the `_actions` attribute.
            for action in getattr(parser, "_actions", []):
                if isinstance(action, object) and getattr(action, "option_strings", None):
                    if action.option_strings:
                        options.extend(action.option_strings)
        except Exception as exc:
            # Fall back to an empty list if something goes wrong while introspecting
