    parser_container = None
    if hasattr(self, "command_parsers"):
        parser_container = self.command_parsers
    elif hasattr(self, "commands"):
        parser_container = self.commands
    elif hasattr(self, "parsers"):
        parser_container = self.parsers

    if parser_container is None:
        # No known container for parsers
        return []

    try:
        parser = parser_container[command_name]
    except (KeyError, IndexError, TypeError, AttributeError):
        # command not found or container not subscriptable
        return []

    # Try to retrieve options in various common ways
    if hasattr(parser, "options"):
        return list(parser.options)
    if hasattr(parser, "option_specs"):
        return list(parser.option_specs)
    if hasattr(parser, "get_option_specs"):
        try:
            return list(parser.get_option_specs())
        except Exception:
            return []
    if hasattr(parser, "get_option_spec"):
        try:
            return list(parser.get_option_spec())
        except Exception:
            return []

