            raise TypeError(f"The options for command '{command_name}' must be a dict, got {type(options).__name__}")
        # Return the specification for the given argument, or None if not present
        return options.get(argument_name, None)

def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name. """
    try:
        if not isinstance(command_name, str) or not isinstance(argument_name, str):
            return None
        return getattr(self, 'options_spec', {}).get(command_name, {}).get(argument_name)
    except Exception:
        return None

def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name. """
    try:
        # Validate inputs
        if not isinstance(command_name, str) or not command_name:
            raise ValueError("command_name must be a non-empty string")
        if not isinstance(argument_name, str) or not argument_name:
            raise ValueError("argument_name must be a non-empty string")

        # Retrieve the command registry
        commands = getattr(self, "commands", None)
        if commands is None:
            raise AttributeError("The object does not have a 'commands' attribute")

        # Get the command specification
        command_spec = commands.get(command_name)
        if command_spec is None:
            raise KeyError(f"Command '{command_name}' not found")

        # Get options dictionary from the command spec
        options = command_spec.get("options")
        if options is None:
            raise KeyError(f"No options defined for command '{command_name}'")

        # Retrieve the specific option specification
        option_spec = options.get(argument_name)
        if option_spec is None:
            raise KeyError(f"Option '{argument_name}' not found for command '{command_name}'")

        return option_spec

    except Exception as exc:
        # Wrap all errors in a RuntimeError with context
        raise RuntimeError(
            f"Error retrieving option spec for command '{command_name}' "
            f"and argument '{argument_name}': {exc}"
        ) from exc

def get_silent_args(self, args):
    """list of silenced argument

    :param args: The received arguments.
    :return: list, silenced argument names
    """
    silent = []
    if args is None:
        return silent

    # Helper to decide if a value should be considered silenced
    def _is_silent(val):
        try:
            # Consider None, False, empty strings, empty collections and zero as silent
            return val is None or val is False or (not val)
        except Exception:
            return False

    # Case 1: dictionary-like objects
    if isinstance(args, dict):
        for key, value in args.items():
            if _is_silent(value):
                silent.append(str(key))

    # Case 2: objects with items() (e.g., argparse.Namespace)
    elif hasattr(args, "items"):
        try:
            for key, value in args.items():
                if _is_silent(value):
                    silent.append(str(key))
        except Exception:
            pass

    # Case 3: generic objects: inspect attributes
    else:
        try:
            for attr in dir(args):
                if attr.startswith("_"):
                    continue
                try:
                    val = getattr(args, attr)
                except Exception:
                    continue
                if _is_silent(val):
                    silent.append(attr)
        except Exception:
            pass

    # Remove duplicates and sort for consistency
    return sorted(set(silent))

def get_silent_args(self, args):
    """list of silenced argument

    :param args: The received arguments.
    :return: list, slienced argument names
    """
    # Handle invalid input: args must be an iterable of strings
    if not args:
        return []
    try:
        # Ensure args is iterable
        iterator = iter(args)
    except TypeError:
        return []

    silent_args = []
    for arg in iterator:
        try:
            arg_str = str(arg)
        except Exception:
            continue
        # Check for typical silent flag patterns
        lowered = arg_str.lower()
        if (arg_str.startswith('-') and 'silent' in lowered) or lowered == 'silent':
            silent_args.append(arg_str)
        # Some command line libs use short flag '-s'
        # Optionally include short verbose flag
        elif arg_str == '-s':
            silent_args.append(arg_str)
    return silent_args

def get_silent_args(self, args):
    """list of silenced argument

    :param args: The received arguments.
    :return: list, slienced argument names
    """
    try:
        if args is None:
            return []
        # Accept dictionaries or objects with __dict__
        if isinstance(args, dict):
            arg_items = args.items()
        elif hasattr(args, "__dict__"):
            arg_items = args.__dict__.items()
        else:
            raise TypeError("args must be a dict or an object with attributes")
        silent = []
        for key, value in arg_items:
            # Treat None, empty string, or empty iterable as silent
            if value is None:
                silent.append(key)
            elif isinstance(value, str) and value == "":
                silent.append(key)
            elif isinstance(value, (list, tuple, set, dict)) and len(value) == 0:
                silent.append(key)
        return silent
    except Exception as exc:
        # Unexpected issues: log and return empty list
        # (logging omitted per instructions)
        return []

def get_silent_args(self, args):
    """
    list of silenced argument

    :param args: The received arguments.
    :return: list, slienced argument names
    """
    if args is None:
        return []

    silent_args = []
    try:
        if isinstance(args, dict):
            for key, value in args.items():
                if value is None or value is False or value == "":
                    silent_args.append(key)
        elif isinstance(args, (list, tuple)):
            for item in args:
                if isinstance(item, tuple) and len(item) == 2:
                    name, value = item
                    if value is None or value is False or value == "":
                        silent_args.append(name)
                elif isinstance(item, str):
                    silent_args.append(item)
    except Exception:
        # In case of any unexpected structure, return what we have collected so far
        pass

    return silent_args

def get_silent_args(self, args):
        """list of silenced argument

        :param args: The received arguments.
        :return: list, slienced argument names
        """
        try:
            if not isinstance(args, dict):
                # If args is not a dictionary, we can't determine silent args reliably
                return []
            silent_keys = []
            for key, value in args.items():
                # Consider an argument silent if its value is None or an empty string
                if value is None or value == "":
                    silent_keys.append(key)
            return silent_keys
        except Exception as e:
            # In case of any unexpected error, return an empty list and optionally log the error
            return []

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided."""
    # Ensure the class defines what the required arguments are
    if not hasattr(self, "required_args"):
        raise AttributeError("The object must have a 'required_args' attribute.")
    if not isinstance(self.required_args, (list, set, tuple)):
        raise TypeError("'required_args' must be an iterable of argument names.")

    # Validate input type for args
    if args is None:
        raise TypeError("The 'args' parameter cannot be None.")

    # Prepare a helper function to determine if a value is considered provided
    def is_provided(value):
        return value is not None

    missing = []

    # If args is a mapping (e.g., dict), use key lookup
    if isinstance(args, dict):
        for key in self.required_args:
            if key not in args or not is_provided(args[key]):
                missing.append(key)
    else:
        # For objects (e.g., argparse.Namespace), use attribute lookup
        for key in self.required_args:
            if not hasattr(args, key) or not is_provided(getattr(args, key)):
                missing.append(key)

    if missing:
        missing_str = ", ".join(missing)
        raise ValueError(f"Missing required arguments: {missing_str}")

    return True

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided."""
    # Ensure args is a mapping
    if not isinstance(args, dict):
        raise TypeError(f"Expected args to be a dict, got {type(args).__name__}")

    # The class is expected to define a 'required_args' attribute
    required = getattr(self, "required_args", None)
    if required is None:
        raise AttributeError(
            "The object must define a 'required_args' attribute "
            "(e.g., a list or set of argument names)."
        )
    if not isinstance(required, (list, tuple, set)):
        raise TypeError(
            f"'required_args' must be a list, tuple, or set, "
            f"got {type(required).__name__}"
        )

    # Find any missing required arguments
    missing = [arg for arg in required if arg not in args or args[arg] is None]
    if missing:
        missing_str = ", ".join(missing)
        raise ValueError(f"Missing required argument(s): {missing_str}")
    # Successful validation returns None implicitly.

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """
    List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when`` condition
    """
    try:
        required_args = []
        if not isinstance(options_spec, (list, tuple)):
            return required_args

        for opt in options_spec:
            name = None
            cond = None

            # Support option specification as dict with keys `name` and `required_when`
            if isinstance(opt, dict):
                name = opt.get('name')
                cond = opt.get('required_when')
            # Support option specification as a simple string name
            elif isinstance(opt, str):
                name = opt
                cond = None

            if not name:
                continue

            if cond is None:
                continue

            matched = False
            # If the condition is a callable, call it with command_name and args
            if callable(cond):
                try:
                    matched = bool(cond(command_name, args))
                except Exception:
                    matched = False
            # If the condition is a dict, attempt to map command_name to a sub-condition
            elif isinstance(cond, dict):
                sub = cond.get(command_name)
                if sub is None:
                    continue
                if callable(sub):
                    try:
                        matched = bool(sub(command_name, args))
                    except Exception:
                        matched = False
                elif isinstance(sub, (list, tuple)):
                    matched = all(
                        (c(command_name, args) if callable(c) else bool(c))
                        for c in sub
                    )
                else:
                    matched = bool(sub)
            # If the condition is a list/tuple, evaluate each element
            elif isinstance(cond, (list, tuple)):
                matched = all(
                    (c(command_name, args) if callable(c) else bool(c))
                    for c in cond
                )
            # For simple truthy values
            elif isinstance(cond, (bool, int, str)):
                matched = bool(cond)
            # Unsupported condition types are ignored

            if matched:
                required_args.append(name)

        return required_args
    except Exception:
        # In case of any unexpected error, return an empty list to avoid breaking the caller
        return []

def _get_conditionally_required_args(self, command_name, options_spec,
                                         args):
        """
        List arguments with ``required_when`` condition matched.

        :param command_name: the command name.
        :param options_spec:  the list of command spec options.
        :param args: the received input arguments
        :return: list, list of argument names with matched ``required_when``
            condition
        """
        # Basic type checks
        if not isinstance(options_spec, list):
            raise TypeError(
                f"options_spec must be a list, got {type(options_spec).__name__}"
            )
        if not isinstance(args, dict):
            raise TypeError(
                f"args must be a dict, got {type(args).__name__}"
            )

        conditionally_required = []

        for spec in options_spec:
            try:
                if not isinstance(spec, dict):
                    # Skip malformed spec entries
                    continue
                name = spec.get("name")
                if not isinstance(name, str):
                    continue
                required_when = spec.get("required_when")
                if required_when is None:
                    continue

                # Support different types for required_when
                condition_met = False

                if callable(required_when):
                    try:
                        condition_met = required_when(args, command_name=command_name)
                    except Exception:
                        # If callable fails, treat as not met
                        condition_met = False

                elif isinstance(required_when, (list, tuple)):
                    # Any condition in the iterable that evaluates to True
                    for cond in required_when:
                        if isinstance(cond, str):
                            if args.get(cond):
                                condition_met = True
                                break
                        elif callable(cond):
                            try:
                                if cond(args, command_name=command_name):
                                    condition_met = True
                                    break
                            except Exception:
                                continue
                    # If list is empty, skip
                elif isinstance(required_when, str):
                    # Treat string as a key that should be truthy
                    if args.get(required_when):
                        condition_met = True
                else:
                    # Unsupported type: ignore
                    continue

                if condition_met:
                    conditionally_required.append(name)
            except Exception:
                # Any unexpected error in processing a spec should not halt
                # the entire function; just skip to the next spec.
                continue

        return conditionally_required

def validate_length_args(self, args):
    """
    Check if value of arguments is not longer than length specified.

    :param args: The received arguments.  It can be:

        1. A list/tuple of 2‑item tuples/lists ``(value, max_length)``.
        2. A dictionary where each value is either a string (no length check)
           or a 2‑item tuple/list ``(value, max_length)``.

    If an argument fails the length check a ``ValueError`` is raised.
    Valid input types are returned unchanged; the function returns ``None`` only
    to signal success.

    Invalid ``args`` types or malformed elements raise ``TypeError``.
    """
    # Local helper to validate a single value/limit pair
    def _check_pair(value, limit, key_desc):
        if not isinstance(limit, int) or limit < 0:
            raise ValueError(f"Maximum length for {key_desc} must be a non‑negative integer.")
        try:
            val_len = len(value)
        except TypeError:
            raise TypeError(f"Value for {key_desc} must be a sequence with a defined length.")
        if val_len > limit:
            raise ValueError(f"Length of {key_desc} ({val_len}) exceeds "
                             f"maximum allowed ({limit}).")

    try:
        # Handle dictionary input
        if isinstance(args, dict):
            for key, val in args.items():
                if isinstance(val, (list, tuple)) and len(val) == 2:
                    _check_pair(val[0], val[1], f"argument '{key}'")
                elif isinstance(val, str):
                    # Strings without explicit limit are accepted; no check.
                    continue
                else:
                    raise TypeError(f"Dictionary value for key '{key}' must be a string "
                                    f"or a 2‑item tuple/list of (value, max_length).")

        # Handle list/tuple input
        elif isinstance(args, (list, tuple)):
            for idx, element in enumerate(args):
                if isinstance(element, (list, tuple)) and len(element) == 2:
                    _check_pair(element[0], element[1], f"element at index {idx}")
                else:
                    raise TypeError(f"Element at index {idx} must be a 2‑item tuple/list "
                                    f"of (value, max_length).")

        else:
            raise TypeError("Argument 'args' must be a dict, list, or tuple.")
    except Exception as exc:
        # Re‑raise with context about which argument failed
        raise exc from None
    # Indicate success implicitly by returning None
    return None

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments. Expected format:
                 - dict mapping argument names to a tuple (value, max_length)
                 or dict mapping argument names to a dict {'value':..., 'max_len':...}
    :raises ValueError: if any argument exceeds max length or input format is invalid.
    """
    if not isinstance(args, dict):
        raise TypeError("args must be a dictionary mapping argument names to values and limits.")
    for name, info in args.items():
        try:
            # Accept tuple or dict forms
            if isinstance(info, tuple) and len(info) == 2:
                value, max_len = info
            elif isinstance(info, dict) and 'value' in info and 'max_len' in info:
                value = info['value']
                max_len = info['max_len']
            else:
                raise ValueError(f"Invalid format for argument '{name}'. Expected tuple or dict with 'value' and 'max_len'.")
            if not isinstance(max_len, int) or max_len < 0:
                raise ValueError(f"Max length for argument '{name}' must be a non-negative integer.")
            if value is None:
                continue  # No length check for None
            try:
                length = len(value)
            except TypeError:
                # For non-Seq types, convert to string
                length = len(str(value))
            if length > max_len:
                raise ValueError(f"Argument '{name}' exceeds maximum length of {max_len}.")
        except Exception as e:
            raise ValueError(f"Error validating argument '{name}': {e}") from e
    return True

def validate_length_args(self, args):
        """Check if value of arguments is not longer than length specified.

        Parameters
        ----------
        args : dict or list/tuple
            The received arguments.  The method supports multiple input
            formats:

            * ``dict`` – keys are argument names and values are mappings
              that contain at least ``'value'`` and optionally ``'max_length'``.
              Example::

                {
                    'title': {'value': 'Hello', 'max_length': 10},
                    'description': {'value': 'A' * 50, 'max_length': 30}
                }

            * ``list`` or ``tuple`` – each element represents an argument
              and can be a ``dict`` with ``'name'``, ``'value'``,
              ``'max_length'`` or a plain ``(name, value, max_length)``
              tuple.  Any element that does not match these patterns is
              ignored.

        Raises
        ------
        TypeError
            If ``args`` is not a supported collection type.
        ValueError
            If an argument's value exceeds the indicated maximum length.
        """
        # Prepare a list of (name, value, max_length) tuples to validate
        items = []

        if isinstance(args, dict):
            for name, spec in args.items():
                if not isinstance(spec, dict):
                    continue
                value = spec.get("value")
                max_length = spec.get("max_length")
                items.append((name, value, max_length))
        elif isinstance(args, (list, tuple)):
            for elem in args:
                if isinstance(elem, dict):
                    name = elem.get("name")
                    value = elem.get("value")
                    max_length = elem.get("max_length")
                    if name is not None:
                        items.append((name, value, max_length))
                elif isinstance(elem, (list, tuple)) and len(elem) >= 3:
                    name, value, max_length = elem[:3]
                    items.append((name, value, max_length))
                # otherwise ignore unrecognised structure
        else:
            raise TypeError("args must be a dict, list, or tuple")

        # Iterate over items and raise error if any value exceeds maximum length
        for name, value, max_length in items:
            if max_length is None:
                continue  # No length constraint specified
            try:
                length = len(value)
            except TypeError:
                # If value does not support len(), skip the check
                continue
            if length > max_length:
                raise ValueError(
                    f"Argument '{name}' exceeds the maximum length of "
                    f"{max_length} (got {length})"
                )

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    # Ensure args is a mapping like a dict
    if not isinstance(args, dict):
        raise TypeError(f"Expected args to be a dict, got {type(args).__name__}")

    # If the object does not define allowed choices, nothing to validate
    allowed = getattr(self, "_choices", {})
    if not isinstance(allowed, dict):
        raise TypeError(f"_choices attribute must be a dict, got {type(allowed).__name__}")

    for key, value in args.items():
        if key not in allowed:
            # Unknown argument – skip or optionally warn
            continue

        opts = allowed[key]
        # Ensure opts is iterable; otherwise it cannot be used for membership tests
        try:
            iter(opts)
        except TypeError:
            raise TypeError(f"Choices for argument {key!r} must be an iterable, got {type(opts).__name__}")

        # Handle sequences of values
        if isinstance(value, (list, tuple, set)):
            # Check each element
            unknown = [v for v in value if v not in opts]
            if unknown:
                raise ValueError(
                    f"Invalid value(s) {unknown!r} for argument {key!r}. "
                    f"Allowed: {list(opts)!r}"
                )
        else:
            if value not in opts:
                raise ValueError(
                    f"Argument {key!r} must be one of {list(opts)!r}, got {value!r}"
                )
    return args

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    # Accept both dicts and Namespace-like objects
    if args is None:
        return
    if isinstance(args, dict):
        items = args.items()
    elif hasattr(args, "__dict__"):
        items = vars(args).items()
    else:
        raise TypeError("args must be a dict or object with attributes")

    # Retrieve the argument definitions, expected to be a dict of {arg_name: definition}
    argument_definitions = getattr(self, "arguments", {})
    if not isinstance(argument_definitions, dict):
        # If arguments are stored differently, fall back to empty dict
        argument_definitions = {}

    for name, value in items:
        definition = argument_definitions.get(name)
        if not definition:
            # If no definition, skip validation
            continue

        # Only validate if a list of choices is defined
        choices = definition.get("choices")
        if not isinstance(choices, (list, tuple, set)):
            continue

        # Handle multiple selections: value may be a list or tuple
        if isinstance(value, (list, tuple)):
            for item in value:
                if item not in choices:
                    raise ValueError(
                        f"Invalid choice '{item}' for argument '{name}'. "
                        f"Allowed: {sorted(choices)}"
                    )
        else:
            if value not in choices:
                raise ValueError(
                    f"Invalid choice '{value}' for argument '{name}'. "
                    f"Allowed: {sorted(choices)}"
                )

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    # Input validation: args should be a dict-like object
    if args is None:
        return
    if not isinstance(args, dict):
        raise TypeError(f"Expected args to be a dict, got {type(args).__name__}")

    # The class is expected to provide a mapping of argument names to the set of accepted choices.
    # If such mapping is not available, we simply skip validation.
    choices_map = getattr(self, "_choices", None)
    if not isinstance(choices_map, dict):
        return

    for key, value in args.items():
        # Only validate arguments that have an explicit choice specification
        if key in choices_map:
            allowed = choices_map[key]
            # Ensure the allowed collection is iterable
            if not isinstance(allowed, (list, tuple, set, frozenset)):
                # If the allowed definition is not a collection, skip validation
                continue

            if value not in allowed:
                raise ValueError(
                    f"Invalid choice for argument '{key}': {value!r}. Expected one of {allowed!r}"
                )
    # If we reach here, all choice arguments are valid
    return True

def validate_min_max_args(self, args):
        """
        Check if value of arguments is between minimum and maximum values.

        Parameters
        ----------
        args : dict or list or tuple
            * If dict: each value should be a tuple/list of (value, min_val, max_val).
            * If list/tuple: each element should be a tuple/list of (value, min_val, max_val).

        Raises
        ------
        ValueError
            If any argument is not within its allowed range or the input structure is invalid.
        """
        try:
            # Helper to validate a single (value, min, max) triple
            def _check_triple(triple):
                if not isinstance(triple, (tuple, list)):
                    raise ValueError(f"Argument {triple!r} is not a tuple/list.")
                if len(triple) != 3:
                    raise ValueError(f"Argument {triple!r} does not contain exactly 3 elements.")
                value, min_val, max_val = triple
                if min_val is None or max_val is None:
                    raise ValueError(f"Missing min or max in {triple!r}.")
                # Ensure numerical comparision works; if values are comparable.
                try:
                    if not (min_val <= value <= max_val):
                        raise ValueError(f"Value {value!r} not in range [{min_val!r}, {max_val!r}].")
                except TypeError as e:
                    raise ValueError(f"Cannot compare {value!r} with {min_val!r} and {max_val!r}: {e}")

            # If args is a mapping: iterate through items
            if isinstance(args, dict):
                for key, triple in args.items():
                    if not isinstance(triple, (tuple, list)):
                        raise ValueError(f"Value for key '{key}' must be a tuple/list (value, min, max).")
                    _check_triple(triple)
            # If args is a list or tuple: iterate directly
            elif isinstance(args, (list, tuple)):
                for idx, triple in enumerate(args):
                    _check_triple(triple)
            else:
                raise ValueError("args must be a dictionary, list, or tuple of triples.")
        except Exception as err:
            # Re-raise for caller to handle, preserving original exception type
            raise
        return True

def validate_min_max_args(self, args):
        """Check if value of arguments is between minimum and maximum values.

        :param args: The received arguments.
        """
        # Retrieve min/max thresholds from instance attributes
        min_val = getattr(self, "min_value", None)
        max_val = getattr(self, "max_value", None)

        if min_val is None:
            min_val = getattr(self, "min", None)
        if max_val is None:
            max_val = getattr(self, "max", None)

        # If thresholds are not defined, skip validation
        if min_val is None or max_val is None:
            return True

        # Prepare iterable; allow dict (use its values) or any iterable; otherwise treat as single value
        try:
            if isinstance(args, dict):
                iterable = args.values()
            else:
                iterable = list(args)
        except TypeError:
            iterable = [args]

        for val in iterable:
            try:
                if not (min_val <= val <= max_val):
                    raise ValueError(
                        f"Argument value {val} not in the range [{min_val}, {max_val}]"
                    )
            except TypeError as exc:
                raise TypeError(
                    f"Cannot compare argument value {val!r} with min/max: {exc}"
                ) from exc

        return True

def validate_min_max_args(self, args):
    """
    Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments. It can be a single numeric value,
                 a sequence of numeric values, or a dictionary whose values
                 are numeric.
    :raises ValueError: If any value is outside the defined bounds.
    :raises TypeError: If the provided arguments are not numeric or
                       not iterable as expected.
    :raises AttributeError: If the instance does not have ``min_value`` or
                            ``max_value`` attributes.
    """
    # Retrieve bounds from the instance; raise if not present
    try:
        min_val = self.min_value
        max_val = self.max_value
    except AttributeError as exc:
        raise AttributeError(
            "Instance must define 'min_value' and 'max_value' attributes for validation."
        ) from exc

    if min_val > max_val:
        raise ValueError(
            f"Invalid bounds: min_value ({min_val}) is greater than max_value ({max_val})."
        )

    # Normalize args to an iterable of values
    if args is None:
        raise TypeError("args cannot be None")

    # Handle a single numeric value
    if isinstance(args, (int, float)):
        values = (args,)
    # Handle dict: validate its values
    elif isinstance(args, dict):
        values = args.values()
    # Handle sequences (list, tuple, set, etc.)
    elif isinstance(args, (list, tuple)):
        values = args
    # Handle other iterable types (e.g., set, generator)
    elif hasattr(args, "__iter__"):
        values = args
    else:
        raise TypeError(
            f"Unsupported type for args: {type(args).__name__}. "
            "Expected a numeric value, a sequence, or a dictionary."
        )

    # Perform validation
    for val in values:
        if not isinstance(val, (int, float)):
            raise TypeError(f"Non-numeric value encountered: {val!r}")
        if val < min_val or val > max_val:
            raise ValueError(
                f"Value {val!r} out of bounds ({min_val}, {max_val})."
            )

    # If all values are within bounds, return True
    return True

