                "subcommand": subcommand,
                "option_name": option_name,
                # Include all entries from spec_option as attributes
                **{k: v for k, v in spec_option.items()}
            }

            # Dynamically create the class using the built‑in `type`
            ComplexArgClass = type(class_name, (object,), class_attrs)

            # Instantiate and return the complex type instance
            return ComplexArgClass()
        except Exception as ex:
            # Wrap any unexpected error to give a clear message
