                               f"for '{type_name}': {ex}") from ex

def create_complex_argumet_type(self, subcommand, type_name, option_name,
                                spec_option):
    """Build the complex argument type

    :param subcommand: the command name
    :param type_name: the complex type name
    :param option_name: the option name
    :param spec_option: option's specifications
    :return: the complex type instance
    """
    try:
        # Basic validation of required inputs
        if not all([subcommand, type_name, option_name, spec_option]):
            raise ValueError("All parameters must be provided and non-empty")

        # A simple container class for the complex argument type
        class ComplexArgumentType:
            def __init__(self, subcommand, type_name, option_name, spec_option):
                self.subcommand = subcommand
                self.type_name = type_name
                self.option_name = option_name
                # spec_option could be any structure; store it as-is
                self.spec_option = spec_option

            def __repr__(self):
                return (
                    f"<ComplexArgumentType type_name={self.type_name!r} "
                    f"option_name={self.option_name!r}>"
                )

            def __iter__(self):
                # allow iteration over key-value pairs
                return iter(self.__dict__.items())

        return ComplexArgumentType(subcommand, type_name, option_name, spec_option)

    except Exception as exc:
        # Wrap any unexpected errors in a RuntimeError for clarity
        raise RuntimeError(f"Failed to create complex argument type: {exc}") from exc

def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args. It can be a dict, a list/tuple of
        key/value pairs, or a list of strings formatted as 'key=value' or
        '--key=value'.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    control_args = {}
    nested_args = {}

    # Validate input type
    if not isinstance(args, (dict, list, tuple)):
        raise TypeError(
            f"args must be a dict or list/tuple of arguments, got {type(args)}")

    # Normalise items to an iterable of (key, value) tuples
    if isinstance(args, dict):
        items = args.items()
    else:
        items = []
        for elem in args:
            if isinstance(elem, dict):
                items.extend(elem.items())
            elif isinstance(elem, (tuple, list)) and len(elem) == 2:
                items.append((elem[0], elem[1]))
            elif isinstance(elem, str):
                stripped = elem.lstrip('-')
                if '=' in stripped:
                    key, val = stripped.split('=', 1)
                    items.append((key, val))
            else:
                # Unsupported element; ignore silently
                continue

    # Split into control and nested dictionaries
    for key, val in items:
        if isinstance(key, str) and key.startswith('control_'):
            # Strip the 'control_' prefix for consistency
            control_key = key[len('control_') :]
            control_args[control_key] = val
        else:
            nested_args[key] = val

    return control_args, nested_args

def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file.
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args, expected to be a dict or
                 an iterable of key/value pairs.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    control_args = {}
    nested_args = {}

    # Defensive: if args is None or empty, return empty dicts
    if not args:
        return control_args, nested_args

    # Normalise args into a dict if it's an iterable of (k, v) pairs
    if isinstance(args, dict):
        arg_dict = args
    else:
        try:
            arg_dict = dict(args)
        except Exception:
            raise TypeError("args must be a dict or an iterable of (key, value) pairs")

    # Define prefixes for control and custom arguments
    CONTROL_PREFIX = "control_"
    CUSTOM_PREFIX = "custom_"

    for key, value in arg_dict.items():
        if not isinstance(key, str):
            continue  # Skip non-string keys
        key_lower = key.lower()
        if key_lower.startswith(CONTROL_PREFIX):
            # Store control arguments without the prefix
            control_args[key_lower[len(CONTROL_PREFIX):]] = value
        elif key_lower.startswith(CUSTOM_PREFIX):
            # For custom arguments, include them in nested arguments
            # but mark with a special key to avoid collision
            nested_key = f"_custom_{key_lower[len(CUSTOM_PREFIX):]}"
            nested_args[nested_key] = value
        else:
            nested_args[key_lower] = value

    return control_args, nested_args

def get_nested_custom_and_control_args(self, args):
    """
    Split input arguments to control, nested, and custom parts.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file.
    Nested arguments: are used by the Ansible playbooks and will be
        put into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list or mapping of args.
    :return: (dict, dict) flat dicts (control_args, nested_args)
    """
    # Define prefixes that identify control and custom arguments
    control_prefixes = {"ctrl_", "control_"}
    custom_prefix = "custom_"

    control_args = {}
    nested_args = {}

    # Normalise args into a list of (key, value) tuples
    try:
        if isinstance(args, dict):
            items = list(args.items())
        elif isinstance(args, (list, tuple)):
            items = []
            for elem in args:
                if isinstance(elem, tuple) and len(elem) == 2:
                    items.append((str(elem[0]), elem[1]))
                elif isinstance(elem, str) and "=" in elem:
                    k, v = elem.split("=", 1)
                    items.append((k.strip(), v.strip()))
                else:
                    # Treat non‑key/value entries as keys with None value
                    items.append((str(elem).strip(), None))
        else:
            raise TypeError("args must be a dict or a list/tuple of key/value pairs")
    except Exception as exc:
        raise ValueError(f"Failed to process args: {exc}") from exc

    for key, value in items:
        # Ensure the key is a string for safe handling
        key_str = str(key)
        # Determine the category of the argument
        if any(key_str.startswith(prefix) for prefix in control_prefixes):
            control_args[key_str] = value
        elif key_str.startswith(custom_prefix):
            # Custom arguments are treated as nested arguments
            nested_args[key_str] = value
        else:
            nested_args[key_str] = value

    return control_args, nested_args

@staticmethod
    def merge_extra_vars(vars_dict, extra_vars=None):
        """Extend ``vars_dict`` with ``extra-vars``

        :param vars_dict: Dictionary to merge extra-vars into
        :param extra_vars: List of extra-vars (each item can be a ``key=value`` string
                           or a dict). Can also be a single dict.
        :return: A new dictionary with the merged variables.
        """
        if not isinstance(vars_dict, dict):
            raise TypeError("vars_dict must be a dictionary")

        # Work on a copy to avoid mutating the original dict
        result = dict(vars_dict)

        if not extra_vars:
            return result

        # Accept a single dict directly
        if isinstance(extra_vars, dict):
            for k, v in extra_vars.items():
                result[k] = v
            return result

        # If it's an iterable of items
        if isinstance(extra_vars, (list, tuple)):
            for item in extra_vars:
                if isinstance(item, dict):
                    result.update(item)
                elif isinstance(item, str):
                    if '=' in item:
                        key, val = item.split('=', 1)
                        result[key] = val
                    else:
                        # Try supporting space-separated key/value pairs
                        parts = item.split()
                        if len(parts) == 2:
                            key, val = parts
                            result[key] = val
                        else:
                            raise ValueError(
                                f"Invalid extra-var string format: '{item}'. "
                                "Expected 'key=value' or 'key value'."
                            )
                else:
                    raise TypeError(
                        f"Unsupported type in extra_vars list: {type(item).__name__}"
                    )
            return result

        raise TypeError(
            f"Unsupported type for extra_vars: {type(extra_vars).__name__}. "
            "Expected dict, list, or tuple."
        )

@staticmethod
def merge_extra_vars(vars_dict, extra_vars=None):
    """
    Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars or a dict. Each element should be a string of the form "key=value".
                       If an element contains no "=", the key will be set to True.
    :return: The updated dictionary (the same object as ``vars_dict``)
    :raises TypeError: If ``vars_dict`` is not a dict or an element of ``extra_vars`` is invalid.
    :raises ValueError: If an element of ``extra_vars`` is a string but cannot be parsed.
    """
    if not isinstance(vars_dict, dict):
        raise TypeError("vars_dict must be a dictionary")

    if not extra_vars:
        return vars_dict

    # If extra_vars is a dict, merge directly
    if isinstance(extra_vars, dict):
        try:
            vars_dict.update(extra_vars)
        except Exception as e:
            raise ValueError(f"Failed to update dictionary with {extra_vars}: {e}") from e
        return vars_dict

    # Otherwise treat as iterable of strings
    try:
        iterable = iter(extra_vars)
    except TypeError:
        raise TypeError("extra_vars must be None, a dict, or an iterable of strings")

    for var in iterable:
        if not isinstance(var, str):
            raise TypeError(f"Each extra var must be a string, got {type(var).__name__!r}")
        if "=" in var:
            key, raw_value = var.split("=", 1)
            key = key.strip()
            if not key:
                raise ValueError(f"Empty key in extra var '{var}'")
            # Try to interpret JSON-like literals, otherwise keep as string
            try:
                import json

                value = json.loads(raw_value)
            except Exception:
                value = raw_value
            vars_dict[key] = value
        else:
            # flag-like var, set to True
            vars_dict[var] = True

    return vars_dict

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI.

    :param ir_workspace: An Infrared Workspace object represents the active
        workspace
    :param ir_plugin: An InfraredPlugin object of the current plugin
    :param playbook_path: the playbook to invoke
    :param verbose: Ansible verbosity level
    :param extra_vars: dict. Passed to Ansible as extra-vars
    :param ansible_args: dict of ansible-playbook arguments to plumb down
        directly to Ansible.
    :return: CompletedProcess instance containing stdout, stderr, and return code.
    :raises: ValueError if required args are missing, RuntimeError on command failure.
    """
    import subprocess
    import json
    # Validate required parameters
    if not isinstance(playbook_path, str) or not playbook_path:
        raise ValueError("playbook_path must be a non-empty string")

    cmd = ["ansible-playbook", playbook_path]

    # Handle verbosity
    if verbose is not None:
        try:
            v_int = int(verbose)
            if v_int < 0:
                raise ValueError
        except Exception:
            raise ValueError("verbose must be a non-negative integer")
        cmd.extend(["-" + "v" * v_int])

    # Handle extra_vars
    if extra_vars is not None:
        if not isinstance(extra_vars, dict):
            raise ValueError("extra_vars must be a dict")
        try:
            json_str = json.dumps(extra_vars)
        except Exception as e:
            raise ValueError(f"Failed to encode extra_vars to JSON: {e}")
        cmd.extend(["--extra-vars", json_str])

    # Handle additional ansible args
    if ansible_args is not None:
        if not isinstance(ansible_args, dict):
            raise ValueError("ansible_args must be a dict")
        for key, value in ansible_args.items():
            if not isinstance(key, str) or not key:
                raise ValueError("ansible_args keys must be non-empty strings")
            flag = f"--{key}"
            if isinstance(value, bool):
                if value:
                    cmd.append(flag)
                # if False, skip adding
            else:
                cmd.append(f"{flag}={value}")

    # Optionally set environment or working directory if workspace provides it
    env = None
    cwd = None
    try:
        if hasattr(ir_workspace, "get_environment"):
            env = ir_workspace.get_environment()
    except Exception:
        env = None
    try:
        if hasattr(ir_workspace, "path"):
            cwd = ir_workspace.path
    except Exception:
        cwd = None

    try:
        result = subprocess.run(
            cmd,
            env=env,
            cwd=cwd,
            text=True,
            capture_output=True,
            check=False
        )
    except FileNotFoundError:
        raise RuntimeError("ansible-playbook command not found. Ensure Ansible is installed and in PATH.")
    except Exception as e:
        raise RuntimeError(f"Failed to execute ansible-playbook: {e}")

    if result.returncode != 0:
        # Include stdout and stderr in the error message
        msg = (
            f"ansible-playbook failed with exit code {result.returncode}\n"
            f"Command: {' '.join(cmd)}\n"
            f"STDOUT:\n{result.stdout}\n"
            f"STDERR:\n{result.stderr}"
        )
        raise RuntimeError(msg)
    return result

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object represents the active
     :param ir_plugin: An InfraredPlugin object of the current plugin
     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level
     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    import subprocess
    import json

    # Construct base command
    cmd = ["ansible-playbook", playbook_path]

    # Add verbosity flag if provided
    if verbose:
        # Ansible uses -v, -vv, -vvv, etc.
        try:
            vcount = int(verbose)
            if 1 <= vcount <= 4:
                cmd.append("-" + "v" * vcount)
            else:
                # default to -v if out of range
                cmd.append("-v")
        except Exception:
            # ignore invalid verbosity values
            pass

    # Add extra vars if provided
    if isinstance(extra_vars, dict):
        try:
            extra_vars_json = json.dumps(extra_vars)
            cmd += ["--extra-vars", extra_vars_json]
        except Exception:
            # fall back to ignore malformed extra_vars
            pass

    # Add additional ansible args if provided
    if isinstance(ansible_args, dict):
        for key, value in ansible_args.items():
            if isinstance(key, str):
                flag = f"--{key.lstrip('-')}"
                if isinstance(value, bool):
                    if value:
                        cmd.append(flag)
                else:
                    # Quote or escape value if needed
                    cmd.append(flag)
                    cmd.append(str(value))

    # Determine working directory from workspace if available
    cwd = None
    try:
        cwd = getattr(ir_workspace, "root_path", None) or getattr(ir_workspace, "path", None)
    except Exception:
        cwd = None

    try:
        result = subprocess.run(
            cmd,
            cwd=cwd,
            capture_output=True,
            text=True,
            check=True
        )
    except subprocess.CalledProcessError as e:
        if ir_plugin:
            try:
                ir_plugin.logger.error(
                    f"Failed to run ansible-playbook: {e.cmd}\n"
                    f"Return code: {e.returncode}\n"
                    f"Stdout: {e.stdout}\nStderr: {e.stderr}"
                )
            except Exception:
                pass
        # Re-raise with a more descriptive error
        raise RuntimeError(
            f"ansible-playbook command failed with exit code {e.returncode}"
        ) from e
    except Exception as e:
        if ir_plugin:
            try:
                ir_plugin.logger.error(
                    f"Unexpected error while running ansible-playbook: {e}"
                )
            except Exception:
                pass
        raise

    # Return the CompletedProcess object so callers can inspect output
    return result

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """
    Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object represents the active
     :param ir_plugin: An InfraredPlugin object of the current plugin
     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level (int or str)
