     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    import subprocess
    import json
    import os

    # Basic validation
    if not playbook_path or not isinstance(playbook_path, str):
        raise ValueError("playbook_path must be a non-empty string")
    if not os.path.isfile(playbook_path):
        raise FileNotFoundError(f"Playbook file not found: {playbook_path}")

    # Build the command
    cmd = ["ansible-playbook", playbook_path]

    # Verbosity
    if verbose is not None:
        try:
            level = int(verbose)
            if level > 0:
                cmd.append("-" + "v" * min(level, 3))
        except Exception:
            # ignore invalid verbosity
            pass

    # Extra vars
    if extra_vars:
        if not isinstance(extra_vars, dict):
            raise ValueError("extra_vars must be a dict")
        try:
            ev_str = json.dumps(extra_vars)
        except Exception as e:
            raise ValueError(f"Failed to serialize extra_vars: {e}")
        cmd.extend(["--extra-vars", ev_str])

    # Extra ansible args
    if ansible_args:
        if not isinstance(ansible_args, dict):
            raise ValueError("ansible_args must be a dict")
        for key, val in ansible_args.items():
            if val is None:
                continue
            # Boolean flags
            if isinstance(val, bool):
                if val:
                    cmd.append(key)
                continue
            # For list values, join with space
            if isinstance(val, (list, tuple)):
                cmd.append(key)
                cmd.extend(map(str, val))
            else:
                cmd.append(key)
                cmd.append(str(val))

    # Logging (use ir_plugin if available)
    try:
        log_method = getattr(ir_plugin, "log", None)
        if log_method and hasattr(log_method, "info"):
            log_method.info("Executing ansible-playbook: %s", " ".join(cmd))
        else:
            # Fallback to simple print
            print("Executing ansible-playbook:", " ".join(cmd))
    except Exception:
        # ignore logging errors
        pass

    # Execute
    try:
        result = subprocess.run(
            cmd,
            check=True,
            capture_output=True,
            text=True,
        )
    except subprocess.CalledProcessError as exc:
        # Attach stdout/stderr for debugging
        error_msg = (
            f"ansible-playbook failed with return code {exc.returncode}\n"
            f"stdout:\n{exc.stdout}\n"
            f"stderr:\n{exc.stderr}"
        )
        raise RuntimeError(error_msg) from exc
    except FileNotFoundError as exc:
        raise RuntimeError("ansible-playbook command not found") from exc
    except Exception as exc:
        raise RuntimeError(f"Unexpected error running ansible-playbook: {exc}") from exc

    # Return the subprocess.CompletedProcess instance
    return result

def _run_playbook(cli_args, vars_dict, ir_workspace, ir_plugin):
    """Runs ansible cli with vars dict

    :param vars_dict: dict, Will be passed as Ansible extra-vars
    :param cli_args: the list  of command line arguments
    :param ir_workspace: An Infrared Workspace object represents the active
     workspace
    :param ir_plugin: An InfraredPlugin object of the current plugin
    :return: ansible results
    """
    import subprocess
    import json

    if not isinstance(cli_args, list):
        raise TypeError("cli_args must be a list of command line arguments")
    if not isinstance(vars_dict, dict):
        raise TypeError("vars_dict must be a dictionary")

    try:
        vars_json = json.dumps(vars_dict)
    except Exception as exc:
        raise ValueError(f"vars_dict could not be serialized to JSON: {exc}") from exc

    cmd = ["ansible-playbook"] + cli_args + ["--extra-vars", vars_json]

    cwd = None
    if ir_workspace is not None:
        # Try common attributes that might hold the workspace path
        cwd = getattr(ir_workspace, "path", None) or getattr(ir_workspace, "working_dir", None)

    try:
        completed = subprocess.run(
            cmd,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            cwd=cwd,
            text=True,
            check=False,
        )
        return {
            "stdout": completed.stdout,
            "stderr": completed.stderr,
            "returncode": completed.returncode,
        }
    except FileNotFoundError as exc:
        # ansible-playbook not installed or not in PATH
        return {
            "stdout": "",
            "stderr": f"ansible-playbook command not found: {exc}",
            "returncode": -1,
        }
    except Exception as exc:
        # Any other exception
        return {
            "stdout": "",
            "stderr": f"Error running ansible-playbook: {exc}",
            "returncode": -1,
        }

def _run_playbook(cli_args, vars_dict, ir_workspace, ir_plugin):
    """
    Runs ansible cli with vars dict

    :param vars_dict: dict, Will be passed as Ansible extra-vars
    :param cli_args: the list  of command line arguments
    :param ir_workspace: An Infrared Workspace object represents the active
     workspace
    :param ir_plugin: An InfraredPlugin object of the current plugin
    :return: ansible results
    """
    # Validate input types
    if not isinstance(cli_args, list):
        raise TypeError(f"cli_args must be a list, got {type(cli_args).__name__}")
    if not isinstance(vars_dict, dict):
        raise TypeError(f"vars_dict must be a dict, got {type(vars_dict).__name__}")

    # Determine the ansible binary to use
    ansible_bin = "ansible-playbook"
    if hasattr(ir_plugin, "get_ansible_executable") and callable(ir_plugin.get_ansible_executable):
        try:
            ansible_bin_candidate = ir_plugin.get_ansible_executable()
            if isinstance(ansible_bin_candidate, str) and ansible_bin_candidate:
                ansible_bin = ansible_bin_candidate
        except Exception:
            pass  # Fall back to default

    # Build the command
    try:
        import json  # local import to avoid global import requirement
        cmd = [ansible_bin] + cli_args + ["--extra-vars", json.dumps(vars_dict)]
    except Exception as e:
        raise RuntimeError(f"Failed to build ansible command: {e}") from e

    # Prepare environment
    env = {}
    if hasattr(ir_workspace, "env") and isinstance(ir_workspace.env, dict):
        env.update(ir_workspace.env)
    env.update(os.environ)  # Merge with current environment

    # Execute the command
    try:
        import subprocess
        result = subprocess.run(
            cmd,
            capture_output=True,
            text=True,
            env=env,
        )
    except FileNotFoundError as e:
        raise RuntimeError(f"Ansible executable not found: {ansible_bin}") from e
    except Exception as e:
        raise RuntimeError(f"Error running ansible: {e}") from e

    # Prepare output
    output = {
        "stdout": result.stdout,
        "stderr": result.stderr,
        "returncode": result.returncode,
    }

    if result.returncode != 0:
        # Include command for debugging
        output["command"] = " ".join(cmd)
        raise RuntimeError(
            f"Ansible playbook failed with return code {result.returncode}. "
            f"Stderr: {result.stderr.strip()}"
        )

    return output

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict with arguments
    """
    if not isinstance(values_dict, dict):
        return

    # Helper to cast individual string values
    def cast_value(val):
        if not isinstance(val, str):
            return val
        lower = val.lower()
        if lower in ("true", "false"):
            return lower == "true"
        if "," in val:
            # split on comma and cast each part
            parts = [p.strip() for p in val.split(",")]
            return [cast_value(p) for p in parts]
        # try int, then float
        try:
            if val.startswith(("0x", "0X")) and len(val) > 2:
                return int(val, 16)
            return int(val)
        except ValueError:
            try:
                return float(val)
            except ValueError:
                return val

    for key, val in list(values_dict.items()):
        try:
            values_dict[key] = cast_value(val)
        except Exception:
            # If casting fails, keep original value
            continue

def _convert_non_cli_args(self, parser_name, values_dict):
        """
        Casts arguments to correct types by modifying values_dict param.

        By default all the values are strings.

        :param parser_name: The command name, e.g. main, virsh, ospd, etc
        :param values_dict: The dict of with arguments
        """
        # Basic input validation
        if not isinstance(parser_name, str):
            raise TypeError(f"parser_name must be a string, got {type(parser_name).__name__}")
        if not isinstance(values_dict, dict):
            raise TypeError(f"values_dict must be a dict, got {type(values_dict).__name__}")

        def _convert_value(val):
            """
            Convert a string value to its appropriate Python type.
            Handles booleans, integers, floats, None, and comma‑separated lists.
            """
            if not isinstance(val, str):
                return val
            s = val.strip()

            # None literal
            if s.lower() == "none":
                return None

            # Boolean literals
            if s.lower() in {"true", "false"}:
                return s.lower() == "true"

            # Integer
            try:
                return int(s)
            except ValueError:
                pass

            # Float
            try:
                return float(s)
            except ValueError:
                pass

            # List (comma separated)
            if "," in s:
                items = [item.strip() for item in s.split(",")]
                # Recursively convert each item
                return [_convert_value(item) for item in items]

            # Default: keep as string
            return s

        # Convert each value in the dictionary in place
        for key, value in list(values_dict.items()):
            try:
                converted = _convert_value(value)
                values_dict[key] = converted
            except Exception as exc:
                # Log the error in a real scenario; here we simply leave the value unchanged
                # and continue processing the remaining keys.
                pass
        # The conversion is performed in‑place; no return value is needed.

def _convert_non_cli_args(self, parser_name, values_dict):
        """Casts arguments to correct types by modifying values_dict param.

        By default all the values are strings.

        :param parser_name: The command name, e.g. main, virsh, ospd, etc
        :param values_dict: The dict of with arguments
        """
        # Helper to convert individual values
        def _convert_value(val):
            """Recursively convert string representations to native Python types."""
            if isinstance(val, list):
                return [_convert_value(v) for v in val]
            if isinstance(val, dict):
                return {k: _convert_value(v) for k, v in val.items()}
            if not isinstance(val, str):
                return val
            s = val.strip()
            # Boolean detection
            if s.lower() in {"true", "false", "yes", "no", "1", "0"}:
                return s.lower() in {"true", "yes", "1"}
            # Integer detection
            try:
                if s.isdigit() or (s.startswith("-") and s[1:].isdigit()):
                    return int(s)
            except Exception:
                pass
            # Float detection
            try:
                if "." in s or "e" in s.lower():
                    return float(s)
            except Exception:
                pass
            # Return original string if no conversion applicable
            return s

        # Apply conversion to all values in the dictionary
        for key, value in list(values_dict.items()):
            try:
                converted = _convert_value(value)
                values_dict[key] = converted
            except Exception:
                # Preserve original value on conversion error
                continue
        # No explicit return, modifies values_dict in place.

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json

    def _flatten(d, parent_key=''):
        flat = {}
        for k, v in d.items():
            new_key = f"{parent_key}.{k}" if parent_key else k
            if isinstance(v, dict):
                flat.update(_flatten(v, new_key))
            else:
                flat[new_key] = v
        return flat

    # Validate plugin_dir
    if not isinstance(plugin_dir, str):
        raise TypeError(f"plugin_dir must be a string, got {type(plugin_dir).__name__}")
    if not os.path.isdir(plugin_dir):
        raise FileNotFoundError(f"Specified plugin directory does not exist or is not a directory: {plugin_dir}")

    # Possible spec filenames
    spec_filenames = ["plugin.json", "plugin.yml", "plugin.yaml"]
    spec_path = None
    for name in spec_filenames:
        candidate = os.path.join(plugin_dir, name)
        if os.path.isfile(candidate):
            spec_path = candidate
            break

    if spec_path is None:
        raise FileNotFoundError(f"No plugin spec file found in {plugin_dir}. Expected one of: {', '.join(spec_filenames)}")

    # Load spec content
    try:
        with open(spec_path, 'r', encoding='utf-8') as f:
            content = f.read()
    except Exception as e:
        raise IOError(f"Failed to read plugin spec file at {spec_path}: {e}")

    # Parse JSON (ignoring YAML due to missing library)
    try:
        spec_dict = json.loads(content)
    except json.JSONDecodeError as e:
        # Try to parse as YAML by manually handling simple key:value pairs if YAML isn't available
        # This is a minimal fallback and may not work for complex YAML.
        try:
            import yaml
            spec_dict = yaml.safe_load(content)
        except Exception:
            raise ValueError(f"Failed to parse plugin spec as JSON: {e}")

    if not isinstance(spec_dict, dict):
        raise ValueError(f"Plugin spec root must be a dictionary, got {type(spec_dict).__name__}")

    # Flatten the dictionary
    flat_dict = _flatten(spec_dict)
    return flat_dict

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    flat = {}
    # Basic validation of the path
    if not plugin_dir or not isinstance(plugin_dir, str):
        raise ValueError("plugin_dir must be a non-empty string path")
    if not os.path.isdir(plugin_dir):
        raise ValueError(f"plugin_dir '{plugin_dir}' is not a valid directory")

    # Find a specification file – prefer JSON, then YAML/YML
    spec_file = None
    for fname in ("plugin.json", "plugin.yaml", "plugin.yml"):
        candidate = os.path.join(plugin_dir, fname)
        if os.path.isfile(candidate):
            spec_file = candidate
            break

    if spec_file is None:
        # No spec file found – return empty dict to avoid hard failure
        return flat

    # Load the spec file
    try:
        with open(spec_file, "r", encoding="utf-8") as f:
            if spec_file.endswith(".json"):
                spec = json.load(f)
            else:
                # Attempt to load YAML if available
                try:
                    import yaml  # noqa: F401
                    f.seek(0)
                    spec = yaml.safe_load(f)
                except Exception:
                    # Unsupported format or yaml not installed
                    spec = {}
    except Exception as exc:
        raise ValueError(f"Failed to load plugin spec from {spec_file}: {exc}") from exc

    if not isinstance(spec, dict):
        raise ValueError("Plugin spec must be a dictionary at the top level")

    # Helper to flatten nested dictionaries
    def _flatten(d, parent_key=""):
        for key, value in d.items():
            full_key = f"{parent_key}.{key}" if parent_key else key
            if isinstance(value, dict):
                _flatten(value, full_key)
            else:
                flat[full_key] = value

    _flatten(spec)
    return flat

def get_plugin_spec_flatten_dict(plugin_dir):
    """
    Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json

    def _flatten(d, parent_key="", sep="."):
        items = {}
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.update(_flatten(v, new_key, sep=sep))
            else:
                items[new_key] = v
        return items

    # Resolve path
    try:
        dir_path = str(plugin_dir)
    except Exception as exc:
        raise TypeError("plugin_dir must be a path-like string or object") from exc

    if not os.path.isdir(dir_path):
        raise FileNotFoundError(f"Plugin directory '{dir_path}' does not exist or is not a directory")

    # Supported spec file names
    spec_files = ["plugin.json", "plugin.yaml", "plugin.yml"]
    spec_path = None
    for fname in spec_files:
        fpath = os.path.join(dir_path, fname)
        if os.path.isfile(fpath):
            spec_path = fpath
            break

    if not spec_path:
        raise FileNotFoundError(f"No supported plugin spec file found in '{dir_path}'")

    # Read and parse spec
    try:
        with open(spec_path, "r", encoding="utf-8") as f:
            content = f.read()
    except Exception as exc:
        raise IOError(f"Failed to read spec file '{spec_path}'") from exc

    # Determine format and load
    try:
        if spec_path.endswith(".json"):
            spec_data = json.loads(content)
        elif spec_path.endswith((".yaml", ".yml")):
            # Attempt to import yaml if available
            try:
                yaml = __import__("yaml")
                spec_data = yaml.safe_load(content)
            except Exception:
                # Fallback: treat as empty
                spec_data = {}
        else:
            spec_data = {}
    except Exception as exc:
        raise ValueError(f"Failed to parse plugin spec '{spec_path}'") from exc

    if not isinstance(spec_data, dict):
        raise ValueError(f"Plugin spec root must be a mapping (dict), got {type(spec_data).__name__}")

    return _flatten(spec_data)

