def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json
    # yaml may not be installed, so we try to import lazily
    try:
        import yaml
    except ImportError:
        yaml = None

    # Detect spec file (plugin.json or plugin.yml)
    spec_path = None
    for fname in ("plugin.json", "plugin.yml", "plugin.yaml"):
        potential = os.path.join(plugin_dir, fname)
        if os.path.isfile(potential):
            spec_path = potential
            break

    if spec_path is None:
        raise FileNotFoundError(
            f"Could not find a plugin spec file in {plugin_dir!r}"
        )

    # Load spec contents
    try:
        with open(spec_path, "r", encoding="utf-8") as f:
            if spec_path.endswith(".json"):
                data = json.load(f)
            else:
                if yaml is None:
                    raise RuntimeError(
                        "PyYAML is required to parse YAML plugin specs but is not installed."
                    )
                data = yaml.safe_load(f) or {}
    except Exception as exc:
        raise ValueError(f"Failed to load plugin spec at {spec_path!r}: {exc}") from exc

    # Helper to flatten nested dict/list structures
    def _flatten(obj, parent_key=""):
        flat = {}
        if isinstance(obj, dict):
            for k, v in obj.items():
                new_key = f"{parent_key}.{k}" if parent_key else k
                flat.update(_flatten(v, new_key))
        elif isinstance(obj, list):
            for i, v in enumerate(obj):
                new_key = f"{parent_key}.{i}" if parent_key else str(i)
                flat.update(_flatten(v, new_key))
        else:
            flat[parent_key] = obj
        return flat

    return _flatten(data) if isinstance(data, dict) else {}

