def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    # Validate input types
    if not isinstance(path, str) or not isinstance(root, str):
        raise TypeError("Both 'path' and 'root' must be strings.")
    if root == "":
        raise ValueError("Root cannot be an empty string.")
    # Normalize any trailing separators from root
    root_norm = root.rstrip("/\\")
    # Special case: if path is exactly the root
    if path == root_norm:
        return ""
    # Path must start with the root
    if not path.startswith(root_norm):
        raise ValueError("Root is not a prefix of the path.")
    # Ensure the next character in path is a separator or path ends at root
    idx_after_root = len(root_norm)
    if len(path) > idx_after_root:
        next_char = path[idx_after_root]
        if next_char not in "/\\":
            raise ValueError("Root is not a valid directory prefix of the path.")
    # Strip the root and any leading separator left over
    stripped = path[idx_after_root:]
    # Remove a leading separator if present
    if stripped.startswith("/") or stripped.startswith("\\"):
        stripped = stripped[1:]
    return stripped)
